import type { Region, Player } from '../types';
import { STAT_CONFIG } from '../constants/config';
import { Panel, Button } from './ui';

interface GameOverScreenProps {
  region: Region | undefined;
  dungeonLevel: number;
  player: Player;
  onRestart: () => void;
}

export default function GameOverScreen({ region, dungeonLevel, player, onRestart }: GameOverScreenProps) {
  const lossPct = Math.round(STAT_CONFIG.DEATH_GOLD_LOSS_PCT * 100);
  return (
    <div className="w-full h-full flex items-center justify-center">
      <Panel layout="inline" maxWidth="max-w-md" className="text-center">
        <h1 className="font-display text-4xl font-bold text-rarity-common mb-4 tracking-wider" style={{ color: '#c0392b' }}>
          {'💀'} 항해 종료 {'💀'}
        </h1>
        <p className="text-age-paper/90 mb-2 text-lg">선장 <span className="text-age-gold font-bold">{player.name}</span></p>
        <p className="text-age-paper/60 mb-1 text-sm">지역: {region?.name} | 던전 Lv.{dungeonLevel}</p>
        <p className="text-age-paper/60 mb-3 text-sm">선장 레벨: {player.level}</p>
        <p className="text-age-amber/80 mb-6 text-xs">
          {'💰'} 사망 벌금 {lossPct}% · 잔액 {player.gold}
        </p>
        <Button size="lg" onClick={onRestart}>{'⚓'} 다시 항해</Button>
      </Panel>
    </div>
  );
}
