import { MONSTER_TYPES } from '../../constants/config';
import { SUB_REGIONS } from '../../constants/subRegions';
import { ITEMS } from '../../constants/items';
import type { Region } from '../../types';
import { Panel, Button } from '../ui';

interface RegionInfoModalProps {
  region: Region;
  clearedSubRegions: string[];
  onEnterTown: () => void;
  onClose: () => void;
}

export default function RegionInfoModal({ region, clearedSubRegions, onEnterTown, onClose }: RegionInfoModalProps) {
  const subRegions = region.subRegions.map(id => SUB_REGIONS[id]).filter(Boolean);
  const primaryType = MONSTER_TYPES[region.primaryType];

  return (
    <Panel
      layout="center"
      backdrop
      title={`${region.name} - ${region.capital}`}
      onClose={onClose}
      maxWidth="max-w-md"
    >
      <p className="text-age-paper/80 mb-4 text-sm">{region.description}</p>

      <div className="flex items-center gap-2 mb-4">
        <span className="text-sm text-age-paper/60">주요 속성:</span>
        <span className="text-sm font-semibold" style={{ color: primaryType?.color }}>
          {primaryType?.icon} {primaryType?.name}
        </span>
      </div>

      {subRegions.length > 0 && (
        <div className="mb-4">
          <h3 className="text-age-amber text-sm mb-2">탐험 지역</h3>
          <div className="space-y-1">
            {subRegions.map(sr => {
              const cleared = clearedSubRegions.includes(sr.id);
              return (
                <div key={sr.id} className="flex items-center gap-2 text-sm">
                  <span className={cleared ? 'text-age-leaf' : 'text-age-paper/60'}>
                    {cleared ? '✅' : '⚔️'}
                  </span>
                  <span className="text-age-paper">{sr.name}</span>
                  <span className="text-age-paper/50 text-xs">({sr.description})</span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {region.specialtyGoods.length > 0 && (
        <div className="mb-4">
          <span className="text-sm text-age-paper/60">특산물: </span>
          {region.specialtyGoods.map(id => {
            const item = ITEMS[id];
            return item ? (
              <span key={id} className="text-sm text-age-gold">{item.icon} {item.name} </span>
            ) : null;
          })}
        </div>
      )}

      <div className="flex gap-2 pt-2">
        <Button fullWidth onClick={onEnterTown}>{'🏘️'} 마을 입장</Button>
        <Button variant="ghost" onClick={onClose}>닫기</Button>
      </div>
    </Panel>
  );
}
