import { useEffect, useRef } from 'react';

/** WASD 이동 키 + 한글 IME 대응 키 셋 */
const MOVE_KEYS = new Set(['w', 'a', 's', 'd', 'ㅈ', 'ㅁ', 'ㄴ', 'ㅇ']);

/** 한글 IME 키를 영문 WASD로 정규화 (ㅈ→w, ㅁ→a, ㄴ→s, ㅇ→d) */
function normalize(key: string): string {
  switch (key) {
    case 'w': case 'ㅈ': return 'w';
    case 'a': case 'ㅁ': return 'a';
    case 's': case 'ㄴ': return 's';
    case 'd': case 'ㅇ': return 'd';
    default: return key;
  }
}

/** WASD 키 입력 추적 훅 - 한글 IME 지원, 포커스 이탈 시 자동 초기화 */
export function useArrowKeys() {
  const pressedKeys = useRef<Set<string>>(new Set());

  useEffect(() => {
    const onDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      if (MOVE_KEYS.has(k)) {
        pressedKeys.current.add(normalize(k));
      }
    };
    const onUp = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      if (MOVE_KEYS.has(k)) {
        pressedKeys.current.delete(normalize(k));
      }
    };
    const onBlur = () => {
      pressedKeys.current.clear();
    };

    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('keydown', onDown);
      window.removeEventListener('keyup', onUp);
      window.removeEventListener('blur', onBlur);
    };
  }, []);

  return pressedKeys;
}
