import type { EliteAffixType, SpawnedMonster } from '../types';

/** 엘리트 affix 시각 정보 (라벨 + 색상). */
export const ELITE_AFFIX_VISUALS: Record<EliteAffixType, { label: string; color: string; icon: string }> = {
  swift:     { label: '신속', color: '#7dd3fc', icon: '💨' },
  tank:      { label: '강철', color: '#94a3b8', icon: '🛡️' },
  regen:     { label: '재생', color: '#86efac', icon: '💚' },
  explosive: { label: '폭발', color: '#fb923c', icon: '💥' },
};

/** spawn 시점에 stat에 즉시 반영되는 affix들의 곱셈 테이블. */
const SPAWN_TIME_MULTS: Partial<Record<EliteAffixType, {
  attackMult?: number;
  speedMult?: number;
  defenseMult?: number;
  hpMult?: number;
  goldMult?: number;
}>> = {
  swift: { speedMult: 1.3, attackMult: 1.1 },
  tank:  { defenseMult: 2.0, hpMult: 1.5, goldMult: 1.2 },
};

/** regen affix의 초당 HP 회복량 (maxHp 비율). */
export const REGEN_HP_PER_SECOND_PCT = 0.03;

/** explosive affix의 폭발 데미지 (몬스터 attack 비율 + 반경 픽셀). */
export const EXPLOSIVE_DAMAGE_MULT = 2.5;
export const EXPLOSIVE_RADIUS = 100;

/**
 * 엘리트 affix를 1~2개 무작위 추출. 같은 affix는 한 몬스터에 중복 없음.
 *
 * 던전 레벨이 높을수록 affix 2개일 확률 증가.
 */
export function rollEliteAffixes(
  dungeonLevel: number,
  rng: () => number = Math.random,
): EliteAffixType[] {
  const all: EliteAffixType[] = ['swift', 'tank', 'regen', 'explosive'];
  // Lv3=10%, Lv5=20%, Lv10=45%
  const twoChance = Math.min(0.5, 0.05 + dungeonLevel * 0.04);
  const count = rng() < twoChance ? 2 : 1;

  const pool = [...all];
  const picks: EliteAffixType[] = [];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = Math.floor(rng() * pool.length);
    picks.push(pool[idx]);
    pool.splice(idx, 1);
  }
  return picks;
}

/**
 * spawn 시 affix 기반 스탯 곱을 적용. swift/tank만 즉시 효과,
 * regen/explosive는 런타임에서 별도로 처리됨.
 */
export function applySpawnTimeAffixEffects<T extends {
  attack: number;
  defense: number;
  speed: number;
  hp: number;
  maxHp: number;
  gold: number;
}>(monster: T, affixes: EliteAffixType[]): T {
  const next = { ...monster };
  for (const a of affixes) {
    const mults = SPAWN_TIME_MULTS[a];
    if (!mults) continue;
    if (mults.attackMult) next.attack = Math.floor(next.attack * mults.attackMult);
    if (mults.speedMult) next.speed = next.speed * mults.speedMult;
    if (mults.defenseMult) next.defense = Math.floor(next.defense * mults.defenseMult);
    if (mults.hpMult) {
      next.hp = Math.floor(next.hp * mults.hpMult);
      next.maxHp = Math.floor(next.maxHp * mults.hpMult);
    }
    if (mults.goldMult) next.gold = Math.floor(next.gold * mults.goldMult);
  }
  return next;
}

/** 엘리트가 regen affix를 가졌는지. */
export function hasRegen(m: Pick<SpawnedMonster, 'eliteAffixes'>): boolean {
  return !!m.eliteAffixes?.includes('regen');
}

/** 엘리트가 explosive affix를 가졌는지 (사망 시 AOE). */
export function hasExplosive(m: Pick<SpawnedMonster, 'eliteAffixes'>): boolean {
  return !!m.eliteAffixes?.includes('explosive');
}

/**
 * regen tick에 적용할 회복량 계산. tickIntervalMs에 비례.
 * cap은 호출자가 maxHp로 적용.
 */
export function calculateRegenAmount(maxHp: number, tickIntervalMs: number): number {
  return (maxHp * REGEN_HP_PER_SECOND_PCT * tickIntervalMs) / 1000;
}
