import { MONSTER_TYPES } from '../constants/config';
import type { SpawnedMonster } from '../types';

interface BossHealthBarProps {
  boss: SpawnedMonster;
}

export default function BossHealthBar({ boss }: BossHealthBarProps) {
  const pct = (boss.currentHp / boss.maxHp) * 100;
  return (
    <div className="absolute top-14 left-1/2 -translate-x-1/2 panel-parchment rounded-md p-3 min-w-80 animate-slide-up" style={{ borderColor: 'rgba(192, 57, 43, 0.6)' }}>
      <div className="flex items-center justify-center gap-2 mb-2">
        <span className="text-xl">{MONSTER_TYPES[boss.monsterType]?.icon}</span>
        <span className="text-age-gold font-display font-bold tracking-wide">{'👑'} {boss.name}</span>
      </div>
      <div className="w-full h-6 bg-age-navy rounded overflow-hidden border border-age-blood/50 relative">
        <div
          className="h-full transition-all"
          style={{
            width: `${pct}%`,
            background: 'linear-gradient(90deg, #7a1e14, #c0392b, #e07b39)',
          }}
        />
        <div className="absolute inset-0 pointer-events-none" style={{ boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.12), inset 0 -2px 4px rgba(0,0,0,0.4)' }} />
      </div>
      <div className="text-center text-xs text-age-paper/70 mt-1">
        {Math.floor(boss.currentHp)} / {boss.maxHp}
      </div>
    </div>
  );
}
