import { Panel, Button } from '../ui';
import type { SaveData, SaveSlotId } from '../../types';
import { REGIONS } from '../../constants/regions';

interface SaveSlotsModalProps {
  mode: 'save' | 'load';
  slots: { id: SaveSlotId; data: SaveData | null }[];
  onSelect: (slotId: SaveSlotId) => void;
  onDelete?: (slotId: SaveSlotId) => void;
  onClose: () => void;
}

const SLOT_LABELS: Record<SaveSlotId, string> = {
  slot1: '슬롯 1',
  slot2: '슬롯 2',
  slot3: '슬롯 3',
  auto:  '자동 저장',
};

function formatTimestamp(ts: number): string {
  const d = new Date(ts);
  const pad = (n: number) => n.toString().padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export default function SaveSlotsModal({ mode, slots, onSelect, onDelete, onClose }: SaveSlotsModalProps) {
  const title = mode === 'save' ? '저장 슬롯' : '불러오기';

  return (
    <Panel layout="center" backdrop title={title} icon={'💾'} onClose={onClose} maxWidth="max-w-md w-full">
      <div className="space-y-2">
        {slots.map(({ id, data }) => {
          const empty = !data;
          const regionName = data ? REGIONS[data.currentRegion]?.name ?? data.currentRegion : '';
          const isAuto = id === 'auto';
          const loadDisabled = mode === 'load' && empty;
          const saveDisabled = mode === 'save' && isAuto;

          return (
            <div
              key={id}
              className={`rounded border p-3 bg-age-navy/70 transition-colors ${
                empty ? 'border-age-gold/10' : 'border-age-gold/30'
              }`}
            >
              <div className="flex gap-3">
                <div className="w-24 h-[54px] flex-shrink-0 rounded border border-age-gold/20 bg-black/60 overflow-hidden flex items-center justify-center">
                  {!empty && data.thumbnail ? (
                    <img src={data.thumbnail} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <span className="text-age-paper/30 text-[10px]">{empty ? '–' : '미리보기 없음'}</span>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-1">
                    <div className="flex items-center gap-2">
                      <span className="text-age-gold font-bold text-sm">{SLOT_LABELS[id]}</span>
                      {isAuto && <span className="text-[10px] text-age-amber">(자동)</span>}
                    </div>
                    {!empty && onDelete && (
                      <button
                        onClick={() => onDelete(id)}
                        className="text-age-paper/40 hover:text-age-blood text-xs transition-colors"
                        title="삭제"
                      >
                        {'🗑️'}
                      </button>
                    )}
                  </div>

                  {empty ? (
                    <div className="text-age-paper/40 text-xs mb-2">(비어있음)</div>
                  ) : (
                    <div className="text-age-paper/80 text-xs mb-2 leading-snug">
                      <div>
                        <span className="text-age-paper">{data.player.name}</span>
                        <span className="text-age-paper/60"> · Lv.{data.player.level}</span>
                        <span className="text-age-paper/60"> · {regionName}</span>
                      </div>
                      <div className="text-age-paper/50">{formatTimestamp(data.timestamp)}</div>
                    </div>
                  )}

                  <Button
                    size="xs"
                    fullWidth
                    variant={mode === 'save' ? 'primary' : 'ghost'}
                    disabled={loadDisabled || saveDisabled}
                    onClick={() => !loadDisabled && !saveDisabled && onSelect(id)}
                  >
                    {mode === 'save' ? '저장' : '불러오기'}
                  </Button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </Panel>
  );
}
