import { useEffect, useRef } from 'react';
import { GAME_CONFIG } from '../constants/config';
import type { TileMap, SpawnedMonster, Player } from '../types';

interface MinimapProps {
  map: TileMap;
  player: Pick<Player, 'x' | 'y'>;
  monsters: SpawnedMonster[];
  boss: SpawnedMonster | null;
}

const TILE_PX = 6;

function tileColor(v: number): string {
  switch (v) {
    case 0: return '#2a2a3d';
    case 1: return '#4a4a5a';
    case 2: return '#9333ea';
    case 3: return '#e67e22';
    case 4: return '#9b59b6';
    case 5: return '#95a5a6';
    case 6: return '#1E90FF';
    default: return '#1a1a2a';
  }
}

export default function Minimap({ map, player, monsters, boss }: MinimapProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const w = GAME_CONFIG.MAP_WIDTH * TILE_PX;
  const h = GAME_CONFIG.MAP_HEIGHT * TILE_PX;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, w, h);

    for (let y = 0; y < map.length; y++) {
      const row = map[y];
      if (!row) continue;
      for (let x = 0; x < row.length; x++) {
        ctx.fillStyle = tileColor(row[x]);
        ctx.fillRect(x * TILE_PX, y * TILE_PX, TILE_PX, TILE_PX);
      }
    }

    const toPx = (v: number) => (v / GAME_CONFIG.TILE_SIZE) * TILE_PX;

    ctx.fillStyle = '#ef4444';
    for (const m of monsters) {
      ctx.beginPath();
      ctx.arc(toPx(m.x), toPx(m.y), 1.8, 0, Math.PI * 2);
      ctx.fill();
    }

    if (boss) {
      ctx.fillStyle = '#facc15';
      ctx.beginPath();
      ctx.arc(toPx(boss.x), toPx(boss.y), 3, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = '#22d3ee';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(toPx(player.x), toPx(player.y), 2.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }, [map, player.x, player.y, monsters, boss, w, h]);

  return (
    <div className="absolute top-12 right-2 panel-parchment border border-age-gold/40 rounded-md p-1.5 animate-fade-in">
      <canvas ref={canvasRef} width={w} height={h} className="block rounded-sm" />
    </div>
  );
}
