import { useState } from 'react';
import { ITEMS } from '../../constants/items';
import type { TravelEncounter, Item } from '../../types';
import { Panel, Button } from '../ui';

interface TravelEncounterModalProps {
  encounter: TravelEncounter;
  playerPower: number;
  playerGold: number;
  onFight: () => boolean;
  onFlee: () => void;
  onCollectReward: () => void;
  onBuyItem: (item: Item) => void;
  onClose: () => void;
}

export default function TravelEncounterModal({
  encounter, playerPower, playerGold, onFight, onFlee, onCollectReward, onBuyItem, onClose,
}: TravelEncounterModalProps) {
  const [result, setResult] = useState<'pending' | 'win' | 'lose'>('pending');

  const isCombat = encounter.type === 'pirate' || encounter.type === 'sea_monster';
  const isLoot = encounter.type === 'shipwreck' || encounter.type === 'treasure';
  const isMerchant = encounter.type === 'merchant';

  const handleFight = () => {
    const won = onFight();
    setResult(won ? 'win' : 'lose');
  };

  return (
    <Panel layout="center" backdrop maxWidth="max-w-md w-full">
      <div className="text-center mb-4">
        <span className="text-5xl drop-shadow-lg">{encounter.data.icon}</span>
        <h2 className="font-display text-xl font-bold text-age-gold mt-2 tracking-wide">{encounter.data.name}</h2>
      </div>

      {isCombat && result === 'pending' && (
        <>
          <p className="text-age-paper/80 text-sm text-center mb-4">
            {encounter.type === 'pirate'
              ? '해적이 습격해왔습니다! 전투하시겠습니까?'
              : '거대한 바다 괴물이 나타났습니다!'}
          </p>
          <div className="flex gap-3 text-sm mb-4">
            <div className="flex-1 bg-age-sea/20 border border-age-sea/40 p-2 rounded text-center">
              <div className="text-age-sea text-xs">아군 전투력</div>
              <div className="text-age-paper font-bold">{playerPower}</div>
            </div>
            <div className="flex-1 bg-age-blood/20 border border-age-blood/40 p-2 rounded text-center">
              <div className="text-age-blood text-xs">적 전투력</div>
              <div className="text-age-paper font-bold">{encounter.data.enemyPower || 0}</div>
            </div>
          </div>
          <div className="flex gap-2">
            <Button fullWidth variant="danger" onClick={handleFight}>{'⚔️'} 전투</Button>
            <Button fullWidth variant="ghost" onClick={onFlee}>{'🏃'} 회피</Button>
          </div>
        </>
      )}

      {isCombat && result === 'win' && (
        <>
          <p className="text-age-leaf text-center mb-4 font-bold text-lg">승리!</p>
          {encounter.data.reward && (
            <div className="text-center text-sm text-age-gold mb-4">
              {encounter.data.reward.gold && <span>{'💰'} +{encounter.data.reward.gold}G </span>}
              {encounter.data.reward.exp && <span>{'⭐'} +{encounter.data.reward.exp} EXP </span>}
              {encounter.data.reward.items?.map(id => (
                <span key={id}>{ITEMS[id]?.icon} {ITEMS[id]?.name} </span>
              ))}
            </div>
          )}
          <Button fullWidth onClick={() => { onCollectReward(); onClose(); }}>보상 획득</Button>
        </>
      )}

      {isCombat && result === 'lose' && (
        <>
          <p className="text-age-blood text-center mb-4 font-bold">패배... 약간의 피해를 입었습니다.</p>
          <Button fullWidth variant="ghost" onClick={onClose}>계속 항해</Button>
        </>
      )}

      {isLoot && (
        <>
          <p className="text-age-paper/80 text-sm text-center mb-4">
            {encounter.type === 'shipwreck' ? '난파선에서 물자를 발견했습니다!' : '바다에서 보물 상자를 발견했습니다!'}
          </p>
          {encounter.data.reward && (
            <div className="text-center text-sm text-age-gold mb-4">
              {encounter.data.reward.gold && <span>{'💰'} +{encounter.data.reward.gold}G </span>}
              {encounter.data.reward.exp && <span>{'⭐'} +{encounter.data.reward.exp} EXP </span>}
              {encounter.data.reward.items?.map(id => (
                <span key={id}>{ITEMS[id]?.icon} {ITEMS[id]?.name} </span>
              ))}
            </div>
          )}
          <Button fullWidth onClick={() => { onCollectReward(); onClose(); }}>{'🎁'} 획득</Button>
        </>
      )}

      {isMerchant && (
        <>
          <p className="text-age-paper/80 text-sm text-center mb-4">떠돌이 상인이 희귀 물품을 판매합니다.</p>
          <div className="grid grid-cols-2 gap-2 mb-4">
            {encounter.data.shopItems?.map(id => {
              const item = ITEMS[id];
              if (!item) return null;
              const affordable = playerGold >= item.price;
              return (
                <button
                  key={id}
                  onClick={() => onBuyItem(item)}
                  className={`p-2 rounded border text-center transition-all ${
                    affordable
                      ? 'border-age-gold/25 bg-age-navy/70 hover:border-age-gold/70'
                      : 'border-age-blood/40 bg-age-navy/70 opacity-50'
                  }`}
                >
                  <span className="text-2xl">{item.icon}</span>
                  <div className="text-xs text-age-paper">{item.name}</div>
                  <div className="text-xs text-age-gold">{item.price}G</div>
                </button>
              );
            })}
          </div>
          <Button fullWidth variant="ghost" onClick={onClose}>떠나기</Button>
        </>
      )}
    </Panel>
  );
}
