    england: { merchant: '윌리엄 상인', blacksmith: '토마스 대장장이', elder: '드레이크 제독', mercenary: '용병 길드장 제임스' },
    netherlands: { merchant: '얀 상인', blacksmith: '피터 대장장이', elder: '동인도 회사 총독', mercenary: '용병 길드장 빌럼' },
    morocco: { merchant: '압둘라 상인', blacksmith: '하산 대장장이', elder: '술탄의 사절', mercenary: '용병 길드장 타리크' },
    ottoman: { merchant: '술레이만 상인', blacksmith: '메흐메드 대장장이', elder: '대재상', mercenary: '용병 길드장 이브라힘' },
    greece: { merchant: '니코스 상인', blacksmith: '디미트리스 대장장이', elder: '소크라테스 원로', mercenary: '용병 길드장 아킬레스' },
    norway: { merchant: '올라프 상인', blacksmith: '토르 대장장이', elder: '바이킹 원로 시구르드', mercenary: '용병 길드장 라그나르' },
    egypt: { merchant: '아누비스 상인', blacksmith: '이모텝 대장장이', elder: '클레오파트라 사절', mercenary: '용병 길드장 라메세스' },
    india: { merchant: '라비 상인', blacksmith: '아르준 대장장이', elder: '마하라자 사절', mercenary: '용병 길드장 시바' },
