import { useState } from 'react';

/**
 * 첫 게임 시작 시 1회 노출되는 튜토리얼 오버레이.
 * 닫으면 localStorage('bc_tutorial_seen')에 1 저장 → 다시 안 보임.
 * 설정에서 명시적으로 재호출 가능 (resetTutorial 사용).
 */

const STORAGE_KEY = 'bc_tutorial_seen';

export function hasSeenTutorial(): boolean {
  try {
    return localStorage.getItem(STORAGE_KEY) === '1';
  } catch {
    return false;
  }
}

export function markTutorialSeen(): void {
  try { localStorage.setItem(STORAGE_KEY, '1'); } catch { /* noop */ }
}

export function resetTutorial(): void {
  try { localStorage.removeItem(STORAGE_KEY); } catch { /* noop */ }
}

interface Step {
  title: string;
  body: string;
  icon: string;
}

const STEPS: Step[] = [
  {
    icon: '⛵',
    title: '대항해시대에 오신 것을 환영합니다',
    body: '15세기 유럽, 부서진 나침반 하나로 신대륙으로 향하는 모험이 시작됩니다. 검과 마법, 그리고 한 척의 배가 있다면 어떤 바다도 두렵지 않습니다.',
  },
  {
    icon: '🏘️',
    title: '마을: WASD로 이동하세요',
    body: '4명의 NPC를 클릭해 상점/제작/퀘스트/용병을 이용할 수 있습니다. 푸른 포탈을 클릭하면 던전으로 들어갑니다.',
  },
  {
    icon: '⚔️',
    title: '전투: 마우스 클릭 또는 1~5 + Space',
    body: '몬스터를 클릭하면 선택된 스킬을 시전합니다. Tab으로 가까운 적을 락온하고 Space로 공격할 수도 있습니다. 6종 스킬 중 1~5 키로 골라 사용하세요.',
  },
  {
    icon: '🗺',
    title: '세계 지도와 무역',
    body: 'M 키 또는 마을의 세계지도 버튼으로 항구를 오갈 수 있습니다. 각 지역 특산품을 싸게 사서 멀리 팔수록 차익이 커집니다. 항해 중에는 식량이 소모됩니다.',
  },
  {
    icon: '⭐',
    title: '레벨업과 빌드',
    body: 'STR(공격/무게)·AGI(속도/크리)·INT(마법/식량 절감)에 포인트를 분배하세요. 스킬을 시전할수록 마스터리가 쌓이고, 스킬 트리(T)에서 포인트를 투자해 스킬을 강화할 수 있습니다.',
  },
];

interface TutorialOverlayProps {
  onClose: () => void;
}

export default function TutorialOverlay({ onClose }: TutorialOverlayProps) {
  const [stepIdx, setStepIdx] = useState(0);
  const step = STEPS[stepIdx];
  const isLast = stepIdx === STEPS.length - 1;

  const next = () => {
    if (isLast) {
      markTutorialSeen();
      onClose();
    } else {
      setStepIdx((i) => i + 1);
    }
  };

  const skip = () => {
    markTutorialSeen();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/70 flex items-center justify-center backdrop-blur-sm">
      <div className="panel-parchment rounded-lg p-6 max-w-md mx-4 border-2 border-age-gold/60 shadow-gold">
        <div className="text-5xl text-center mb-3">{step.icon}</div>
        <h2 className="text-age-gold font-bold text-lg text-center mb-2">{step.title}</h2>
        <p className="text-age-paper/85 text-sm leading-relaxed mb-4">{step.body}</p>

        <div className="flex items-center justify-center gap-1.5 mb-4">
          {STEPS.map((_, i) => (
            <span
              key={i}
              className={`block w-2 h-2 rounded-full transition-colors ${
                i === stepIdx ? 'bg-age-gold' : 'bg-age-gold/30'
              }`}
            />
          ))}
        </div>

        <div className="flex gap-2 justify-between">
          <button
            onClick={skip}
            className="btn-age btn-age-ghost text-xs px-3 py-1.5"
          >
            건너뛰기
          </button>
          <button
            onClick={next}
            className="btn-age btn-age-primary text-xs px-4 py-1.5"
            autoFocus
          >
            {isLast ? '시작하기 ⚔️' : '다음 →'}
          </button>
        </div>
      </div>
    </div>
  );
}
