import { ITEMS, CRAFTING_RECIPES } from '../../constants/items';
import { getNPCsForRegion } from '../../constants/regions';
import { getRarityColor } from '../../utils/combat';
import type { Player, InventoryItem, CraftingRecipe } from '../../types';
import { Panel, Button } from '../ui';

interface CraftingModalProps {
  player: Player;
  inventory: InventoryItem[];
  currentRegion: string;
  onCraftItem: (recipe: CraftingRecipe) => void;
  onClose: () => void;
}

export default function CraftingModal({ player, inventory, currentRegion, onCraftItem, onClose }: CraftingModalProps) {
  const npcName = getNPCsForRegion(currentRegion)[1]?.name || '대장장이';
  const headerExtra = <span className="text-age-gold text-sm">{'💰'} {player.gold}</span>;

  return (
    <Panel title={npcName} icon={'🔨'} onClose={onClose} headerExtra={headerExtra} maxWidth="min-w-[420px]">
      <div className="space-y-3 max-h-[60vh] overflow-auto pr-1">
        {Object.entries(CRAFTING_RECIPES).map(([id, recipe]) => {
          const result = ITEMS[recipe.result];
          let canCraft = player.gold >= recipe.goldCost;
          recipe.materials.forEach(m => {
            if (inventory.filter(i => i.id === m.itemId).length < m.count) canCraft = false;
          });

          return (
            <div
              key={id}
              className={`rounded border p-3 bg-age-navy/70 transition-opacity ${
                canCraft ? 'border-age-gold/30' : 'border-age-gold/10 opacity-60'
              }`}
            >
              <div className="flex items-center gap-2 mb-2">
                <span className="text-2xl">{result?.icon}</span>
                <div>
                  <div className="font-bold" style={{ color: getRarityColor(result?.rarity) }}>{result?.name}</div>
                  <div className="text-xs text-age-gold">{recipe.goldCost}G</div>
                </div>
              </div>

              <div className="text-xs text-age-paper/70 mb-2">
                재료: {recipe.materials.map(m => `${ITEMS[m.itemId]?.name} x${m.count}`).join(', ')}
              </div>

              <Button
                size="xs"
                fullWidth
                disabled={!canCraft}
                onClick={() => onCraftItem(recipe)}
              >
                {canCraft ? '제작' : '재료 부족'}
              </Button>
            </div>
          );
        })}
      </div>
    </Panel>
  );
}
