import { SKILLS } from '../../constants/skills';
import {
  NODE_KINDS,
  NODE_INFO,
  MAX_POINTS_PER_NODE,
  getNodePoints,
  availablePoints,
} from '../../utils/skillTree';
import type { Player, SkillNodeKind } from '../../types';
import { Panel } from '../ui';

interface SkillTreeModalProps {
  player: Player;
  onInvest: (skillId: string, kind: SkillNodeKind) => void;
  onClose: () => void;
}

export default function SkillTreeModal({ player, onInvest, onClose }: SkillTreeModalProps) {
  const remaining = availablePoints(player);
  const skills = Object.values(SKILLS);

  return (
    <Panel title="스킬 트리" icon={'🌿'} onClose={onClose} maxWidth="min-w-[460px]">
      <div className="mb-2 text-xs text-age-paper/80 flex items-center justify-between">
        <span>가용 포인트</span>
        <span className="text-age-gold font-bold text-sm">{remaining}</span>
      </div>
      <div className="text-[10px] text-age-paper/50 mb-3">
        스킬을 시전할수록 마스터리가 오르고, 마스터리 레벨당 1 포인트가 적립됩니다.
      </div>

      <div className="space-y-2 max-h-[420px] overflow-y-auto pr-1">
        {skills.map((skill) => (
          <div key={skill.id} className="border border-age-gold/20 rounded p-2 bg-age-navy/40">
            <div className="flex items-center gap-2 mb-1.5">
              <span className="text-base">{skill.icon}</span>
              <span className="text-age-paper font-bold text-sm">{skill.name}</span>
              <span className="text-age-paper/40 text-[10px] ml-auto">Lv.{skill.unlockLevel}+</span>
            </div>
            <div className="grid grid-cols-3 gap-1.5">
              {NODE_KINDS.map((kind) => {
                const points = getNodePoints(player.skillTreeAllocations, skill.id, kind);
                const maxed = points >= MAX_POINTS_PER_NODE;
                const canInvest = remaining > 0 && !maxed;
                return (
                  <button
                    key={kind}
                    onClick={() => canInvest && onInvest(skill.id, kind)}
                    disabled={!canInvest}
                    className={`p-1.5 rounded text-[10px] border transition-all text-left ${
                      maxed
                        ? 'bg-age-gold/15 border-age-gold/60 text-age-gold cursor-default'
                        : canInvest
                          ? 'bg-age-navy/70 border-age-gold/30 text-age-paper hover:border-age-gold/70 hover:bg-age-navy/40'
                          : 'bg-age-navy/40 border-age-gold/10 text-age-paper/40 cursor-not-allowed'
                    }`}
                    title={NODE_INFO[kind].description}
                  >
                    <div className="flex items-center gap-1">
                      <span>{NODE_INFO[kind].icon}</span>
                      <span className="flex-1 truncate">{NODE_INFO[kind].label}</span>
                    </div>
                    <div className="text-age-amber font-bold mt-0.5">
                      {points} / {MAX_POINTS_PER_NODE}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </Panel>
  );
}
