/** 지역과 직업에 맞는 랜덤 용병 이름 생성 */
export function generateMercenaryName(type: MercenaryType, region: string): string {
  const names = MERCENARY_NAMES[region]?.[type] || MERCENARY_NAMES.portugal[type];
  return names[Math.floor(Math.random() * names.length)];
}

/** 용병 직업 타입을 한글명으로 변환 (warrior→전사, mage→마법사, archer→궁수) */
export function getMercenaryTypeName(type: MercenaryType): string {
  switch (type) {
    case 'warrior': return '전사';
    case 'mage': return '마법사';
    case 'archer': return '궁수';
  }
}
