import { useState, useCallback } from 'react';
import type { FloatingText } from '../types';

/** 동시에 존재 가능한 플로팅 텍스트 상한. 전투 시 텍스트 메쉬 누적으로 인한 프레임 저하 방지. */
const MAX_FLOATING_TEXTS = 24;

/** 플로팅 텍스트 관리 훅 - 데미지/힐/EXP 텍스트 생성, 1초 후 자동 제거 */
export function useFloatingText() {
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  const addFloatingText = useCallback((x: number, y: number, text: string, color: string, scale?: number) => {
    const id = Date.now() + Math.random();
    setFloatingTexts(prev => {
      const next = [...prev, { id, x, y, text, color, opacity: 1, offsetY: 0, scale }];
      return next.length > MAX_FLOATING_TEXTS ? next.slice(next.length - MAX_FLOATING_TEXTS) : next;
    });
    setTimeout(() => setFloatingTexts(prev => prev.filter(t => t.id !== id)), 1000);
  }, []);

  return { floatingTexts, setFloatingTexts, addFloatingText };
}
