import { useState } from 'react';
import { STAT_CONFIG } from '../constants/config';
import { REGIONS } from '../constants/regions';
import { Panel, Button } from './ui';

interface CharacterCreateProps {
  onCreateCharacter: (name: string, str: number, agi: number, int: number, homeRegion: string) => void;
}

export default function CharacterCreateScreen({ onCreateCharacter }: CharacterCreateProps) {
  const [name, setName] = useState('');
  const [str, setStr] = useState<number>(STAT_CONFIG.STARTING_STR);
  const [agi, setAgi] = useState<number>(STAT_CONFIG.STARTING_AGI);
  const [int, setInt] = useState<number>(STAT_CONFIG.STARTING_INT);
  const [homeRegion, setHomeRegion] = useState('portugal');
  const [remaining, setRemaining] = useState<number>(STAT_CONFIG.INITIAL_STAT_POINTS);

  const addStat = (stat: 'str' | 'agi' | 'int') => {
    if (remaining <= 0) return;
    if (stat === 'str') setStr(s => s + 1);
    if (stat === 'agi') setAgi(s => s + 1);
    if (stat === 'int') setInt(s => s + 1);
    setRemaining(r => r - 1);
  };

  const removeStat = (stat: 'str' | 'agi' | 'int') => {
    if (stat === 'str' && str > STAT_CONFIG.STARTING_STR) { setStr(s => s - 1); setRemaining(r => r + 1); }
    if (stat === 'agi' && agi > STAT_CONFIG.STARTING_AGI) { setAgi(s => s - 1); setRemaining(r => r + 1); }
    if (stat === 'int' && int > STAT_CONFIG.STARTING_INT) { setInt(s => s - 1); setRemaining(r => r + 1); }
  };

  const canStart = name.trim().length > 0 && name.length <= 8 && remaining === 0;
  const startingRegions = ['portugal', 'spain'];

  return (
    <div className="w-full h-full flex items-center justify-center">
      <Panel layout="inline" maxWidth="max-w-lg w-full" title={'캐릭터 생성'} icon={'🧭'}>
        <div className="mb-5">
          <label className="block text-age-paper/80 text-xs mb-1.5">선장 이름 (최대 8자)</label>
          <input
            type="text"
            value={name}
            onChange={e => setName(e.target.value.slice(0, 8))}
            placeholder="이름을 입력하세요"
            className="w-full px-3 py-2 bg-age-navy/70 border border-age-gold/30 rounded text-age-paper placeholder-age-paper/30 focus:border-age-gold/70 outline-none text-sm"
          />
        </div>

        <div className="mb-5">
          <div className="flex justify-between items-center mb-2">
            <span className="text-age-paper/80 text-xs">스탯 배분</span>
            <span className="text-age-gold font-bold text-sm">남은 포인트: {remaining}</span>
          </div>
          <div className="space-y-2">
            <StatRow
              label="STR (힘)"
              value={str}
              desc={`공격 +${str * STAT_CONFIG.STR_TO_ATTACK}, 방어 +${str * STAT_CONFIG.STR_TO_DEFENSE}, 무게 +${str * STAT_CONFIG.STR_TO_WEIGHT}`}
              onAdd={() => addStat('str')}
              onRemove={() => removeStat('str')}
              canAdd={remaining > 0}
              canRemove={str > STAT_CONFIG.STARTING_STR}
            />
            <StatRow
              label="AGI (민첩)"
              value={agi}
              desc={`속도 +${(agi * STAT_CONFIG.AGI_TO_SPEED).toFixed(1)}, 이동시간 -${Math.floor(agi * STAT_CONFIG.AGI_TRAVEL_REDUCTION * 100)}%`}
              onAdd={() => addStat('agi')}
              onRemove={() => removeStat('agi')}
              canAdd={remaining > 0}
              canRemove={agi > STAT_CONFIG.STARTING_AGI}
            />
            <StatRow
              label="INT (지능)"
              value={int}
              desc={`마법 +${int * STAT_CONFIG.INT_TO_MAGIC}, 식량소모 -${Math.floor(int * STAT_CONFIG.INT_FOOD_REDUCTION * 100)}%`}
              onAdd={() => addStat('int')}
              onRemove={() => removeStat('int')}
              canAdd={remaining > 0}
              canRemove={int > STAT_CONFIG.STARTING_INT}
            />
          </div>
        </div>

        <div className="mb-5">
          <label className="block text-age-paper/80 text-xs mb-2">시작 국가</label>
          <div className="flex gap-3">
            {startingRegions.map(id => {
              const region = REGIONS[id];
              const selected = homeRegion === id;
              return (
                <button
                  key={id}
                  onClick={() => setHomeRegion(id)}
                  className={`flex-1 p-3 rounded border-2 transition-all text-left ${
                    selected
                      ? 'border-age-gold bg-age-gold/15 shadow-gold'
                      : 'border-age-gold/20 bg-age-navy/50 hover:border-age-gold/50'
                  }`}
                >
                  <div className="text-age-paper font-bold text-sm">{region.name}</div>
                  <div className="text-age-paper/60 text-[11px]">{region.capital}</div>
                  <div className="text-age-paper/50 text-[10px] mt-1">{region.description}</div>
                </button>
              );
            })}
          </div>
        </div>

        <Button
          size="lg"
          fullWidth
          disabled={!canStart}
          onClick={() => canStart && onCreateCharacter(name.trim(), str, agi, int, homeRegion)}
        >
          {'⚓'} 모험 시작!
        </Button>
        {!canStart && (
          <p className="text-age-paper/50 text-xs text-center mt-2">
            {name.trim().length === 0 ? '이름을 입력하세요' : remaining > 0 ? '모든 스탯 포인트를 배분하세요' : ''}
          </p>
        )}
      </Panel>
    </div>
  );
}

function StatRow({ label, value, desc, onAdd, onRemove, canAdd, canRemove }: {
  label: string;
  value: number;
  desc: string;
  onAdd: () => void;
  onRemove: () => void;
  canAdd: boolean;
  canRemove: boolean;
}) {
  return (
    <div className="flex items-center gap-3 bg-age-navy/60 border border-age-gold/15 p-2 rounded">
      <div className="w-28">
        <div className="text-age-paper font-bold text-sm">{label}</div>
        <div className="text-age-paper/50 text-[10px] leading-tight">{desc}</div>
      </div>
      <div className="flex items-center gap-2 ml-auto">
        <button
          onClick={onRemove}
          disabled={!canRemove}
          className={`w-7 h-7 rounded text-sm font-bold transition-colors ${
            canRemove ? 'bg-age-blood/70 hover:bg-age-blood text-white' : 'bg-age-navy text-age-paper/30 cursor-not-allowed'
          }`}
        >-</button>
        <span className="text-age-gold font-bold text-lg w-6 text-center">{value}</span>
        <button
          onClick={onAdd}
          disabled={!canAdd}
          className={`w-7 h-7 rounded text-sm font-bold transition-colors ${
            canAdd ? 'bg-age-leaf/70 hover:bg-age-leaf text-white' : 'bg-age-navy text-age-paper/30 cursor-not-allowed'
          }`}
        >+</button>
      </div>
    </div>
  );
}
