/**
 * 그래픽 옵션 - 모듈 싱글톤 + localStorage 영속화.
 * 구독자 패턴으로 컴포넌트 리렌더 트리거.
 */

const STORAGE_KEY = 'age-of-sail/graphics';

export type GraphicsQuality = 'low' | 'medium' | 'high';

export interface GraphicsSettings {
  /** 물 셰이더(파도 정점 애니메이션) 활성화 */
  waterShader: boolean;
  /** 던전 점광 / 추가 라이팅 활성화 */
  dynamicLighting: boolean;
  /** 죽음 파티클 표시 */
  particles: boolean;
  /** 플로팅 텍스트 표시 */
  floatingText: boolean;
  /** 카메라 흔들림 */
  cameraShake: boolean;
  /** 포스트프로세싱 (Bloom / Vignette / 저체력 색수차) */
  postprocessing: boolean;
  /** 전체 품질 프리셋 (참고용 라벨) */
  quality: GraphicsQuality;
}

const defaults: GraphicsSettings = {
  waterShader: true,
  dynamicLighting: true,
  particles: true,
  floatingText: true,
  cameraShake: true,
  postprocessing: true,
  quality: 'high',
};

function load(): GraphicsSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...defaults };
    const parsed = JSON.parse(raw);
    return { ...defaults, ...parsed };
  } catch {
    return { ...defaults };
  }
}

const state: GraphicsSettings = load();
const listeners = new Set<() => void>();

function persist() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* ignore quota */ }
}

function notify() {
  for (const l of listeners) l();
}

export function getGraphicsSettings(): Readonly<GraphicsSettings> {
  return state;
}

export function setGraphicsToggle<K extends keyof GraphicsSettings>(key: K, value: GraphicsSettings[K]) {
  state[key] = value;
  persist();
  notify();
}

export function applyQualityPreset(q: GraphicsQuality) {
  state.quality = q;
  if (q === 'low') {
    state.waterShader = false;
    state.dynamicLighting = false;
    state.particles = false;
    state.floatingText = true;
    state.cameraShake = false;
    state.postprocessing = false;
  } else if (q === 'medium') {
    state.waterShader = true;
    state.dynamicLighting = false;
    state.particles = true;
    state.floatingText = true;
    state.cameraShake = true;
    state.postprocessing = false;
  } else {
    state.waterShader = true;
    state.dynamicLighting = true;
    state.particles = true;
    state.floatingText = true;
    state.cameraShake = true;
    state.postprocessing = true;
  }
  persist();
  notify();
}

export function subscribeGraphics(fn: () => void): () => void {
  listeners.add(fn);
  return () => { listeners.delete(fn); };
}
