import { useEffect, useState } from 'react';
import { GAME_STATES, MONSTER_TYPES } from '../constants/config';
import { SKILLS } from '../constants/skills';
import { getSkillLevel, getMasteryDamageMult } from '../utils/skillMastery';
import type { Player, GameState } from '../types';

interface SkillBarProps {
  player: Player;
  selectedSkill: string;
  skillCooldowns: Record<string, number>;
  gameState: GameState;
  setSelectedSkill: (skill: string) => void;
  setShowInventory: React.Dispatch<React.SetStateAction<boolean>>;
  setShowQuests: React.Dispatch<React.SetStateAction<boolean>>;
  setShowMercenary: React.Dispatch<React.SetStateAction<boolean>>;
  returnToWorldMap: () => void;
}

export default function SkillBar({
  player,
  selectedSkill,
  skillCooldowns,
  gameState,
  setSelectedSkill,
  setShowInventory,
  setShowQuests,
  setShowMercenary,
  returnToWorldMap,
}: SkillBarProps) {
  // 쿨다운 표시 갱신용 100ms 틱 (활성 쿨다운이 있을 때만 동작)
  const [, setTick] = useState(0);
  const hasActiveCd = Object.values(skillCooldowns).some(t => t > Date.now());
  useEffect(() => {
    if (!hasActiveCd) return;
    const id = window.setInterval(() => setTick(t => t + 1), 100);
    return () => window.clearInterval(id);
  }, [hasActiveCd]);

  const now = Date.now();

  return (
    <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1.5 panel-parchment rounded-md p-2">
      {Object.entries(SKILLS).map(([key, skill], idx) => {
        const unlocked = skill.unlockLevel <= player.level;
        const cdRemainMs = skillCooldowns[key] && now < skillCooldowns[key] ? skillCooldowns[key] - now : 0;
        const cd = cdRemainMs > 0 ? (cdRemainMs / skill.cooldown) * 100 : 0;
        const cdSecs = cdRemainMs > 0 ? (cdRemainMs / 1000).toFixed(1) : null;
        const typeInfo = skill.element ? MONSTER_TYPES[skill.element] : null;
        const selected = selectedSkill === key;
        const noMana = player.mp < skill.manaCost;
        const casts = player.skillMastery?.[key] || 0;
        const masteryLv = getSkillLevel(casts);
        const masteryBonusPct = Math.round((getMasteryDamageMult(masteryLv) - 1) * 100);
        const showMastery = unlocked && masteryLv > 1;

        return (
          <button
            key={key}
            onClick={() => unlocked && setSelectedSkill(key)}
            disabled={!unlocked}
            className={`relative w-12 h-12 rounded border-2 flex flex-col items-center justify-center text-age-paper transition-all ${
              !unlocked ? 'border-age-gold/10 bg-age-navy/80 opacity-50' :
              selected ? 'border-age-gold bg-age-gold/15 shadow-gold' :
              noMana ? 'border-age-blood/50 bg-age-navy/80 opacity-70' :
              'border-age-gold/25 bg-age-navy/80 hover:border-age-gold/60'
            }`}
            title={`${skill.name}${typeInfo ? ` (${typeInfo.name})` : ''}${unlocked ? ` · 숙련도 Lv.${masteryLv}${masteryBonusPct > 0 ? ` (+${masteryBonusPct}%)` : ''}` : ''}`}
          >
            <span className="text-xl">{skill.icon}</span>
            <span className="text-[9px] absolute bottom-0 right-1 text-age-paper/60">{idx + 1}</span>
            {typeInfo && <span className="absolute top-0 right-0.5 text-[9px]">{typeInfo.icon}</span>}
            {showMastery && (
              <span className="absolute top-0 left-0.5 text-[9px] font-bold text-age-gold px-0.5 rounded bg-age-navy/70">
                {masteryLv}
              </span>
            )}
            {cd > 0 && <div className="absolute bottom-0 left-0 right-0 bg-age-navy/80 pointer-events-none" style={{ height: `${cd}%` }} />}
            {cdSecs && (
              <span className="absolute inset-0 flex items-center justify-center text-[12px] font-bold text-age-paper drop-shadow-[0_1px_1px_rgba(0,0,0,0.85)] pointer-events-none">
                {cdSecs}s
              </span>
            )}
            {!unlocked && (
              <div className="absolute inset-0 flex items-center justify-center bg-age-navy/70 rounded text-[11px]">
                {'🔒'}{skill.unlockLevel}
              </div>
            )}
          </button>
        );
      })}

      <div className="w-px bg-age-gold/30 mx-1" />

      <UtilButton icon={'🎒'} label="I" onClick={() => setShowInventory(p => !p)} />
      <UtilButton icon={'📜'} label="Q" onClick={() => setShowQuests(p => !p)} />

      {gameState === GAME_STATES.TOWN && (
        <>
          <UtilButton icon={'⚔️'} label="용병" onClick={() => setShowMercenary(p => !p)} />
          <UtilButton icon={'🗺️'} label="M" onClick={returnToWorldMap} highlight />
        </>
      )}
    </div>
  );
}

function UtilButton({ icon, label, onClick, highlight }: { icon: string; label: string; onClick: () => void; highlight?: boolean }) {
  return (
    <button
      onClick={onClick}
      className={`w-12 h-12 rounded border-2 flex flex-col items-center justify-center text-age-paper transition-all ${
        highlight
          ? 'border-age-gold/70 bg-age-navy/80 hover:border-age-gold hover:shadow-gold'
          : 'border-age-gold/25 bg-age-navy/80 hover:border-age-gold/60'
      }`}
    >
      <span className="text-xl">{icon}</span>
      <span className="text-[9px] text-age-paper/60">{label}</span>
    </button>
  );
}
