import { QUEST_STATUS } from '../../constants/config';
import { QUESTS } from '../../constants/quests';
import type { Player, QuestProgress } from '../../types';
import { Panel, Button } from '../ui';

interface QuestModalProps {
  questProgress: Record<string, QuestProgress>;
  player: Player;
  onAcceptQuest: (qid: string) => void;
  onCompleteQuest: (qid: string) => void;
  onClose: () => void;
}

export default function QuestModal({ questProgress, player, onAcceptQuest, onCompleteQuest, onClose }: QuestModalProps) {
  return (
    <Panel title="퀘스트" icon={'📜'} onClose={onClose} maxWidth="min-w-[420px]" className="max-h-[440px] overflow-auto">
      <div className="space-y-3">
        {Object.entries(QUESTS).filter(([id, q]) => {
          if (questProgress[id]?.status === QUEST_STATUS.REWARDED) return false;
          if (q.unlockLevel > player.level) return false;
          if (q.prerequisite && questProgress[q.prerequisite]?.status !== QUEST_STATUS.REWARDED) return false;
          return true;
        }).map(([id, quest]) => {
          const prog = questProgress[id];
          const isActive = prog?.status === QUEST_STATUS.ACTIVE;
          const isCompleted = prog?.status === QUEST_STATUS.COMPLETED;

          return (
            <div
              key={id}
              className={`rounded border p-3 bg-age-navy/70 transition-colors ${
                quest.isMain ? 'border-age-gold/60 shadow-gold' : 'border-age-gold/20'
              }`}
            >
              <div className="font-bold text-age-paper mb-1">
                {quest.isMain && <span className="text-age-gold">{'⭐ '}</span>}
                {quest.name}
              </div>
              <p className="text-age-paper/70 text-sm mb-2">{quest.description}</p>

              {isActive && (
                <div className="mb-2">
                  <div className="w-full h-2 bg-age-navy rounded-sm overflow-hidden border border-age-gold/20">
                    <div
                      className={`h-full transition-all ${isCompleted ? 'bg-age-leaf' : 'bg-age-sea'}`}
                      style={{ width: `${(prog.currentCount / quest.targetCount) * 100}%` }}
                    />
                  </div>
                  <div className="text-xs text-age-paper/50 mt-1">{prog.currentCount}/{quest.targetCount}</div>
                </div>
              )}

              <div className="text-xs text-age-paper/60 mb-2">
                보상: {quest.rewards.exp && `${quest.rewards.exp} EXP `}
                {quest.rewards.gold && `${quest.rewards.gold} Gold`}
              </div>

              {!isActive && !isCompleted && (
                <Button size="xs" fullWidth variant="ghost" onClick={() => onAcceptQuest(id)}>
                  수락
                </Button>
              )}
              {isCompleted && (
                <Button size="xs" fullWidth variant="success" onClick={() => onCompleteQuest(id)}>
                  완료
                </Button>
              )}
            </div>
          );
        })}
      </div>
    </Panel>
  );
}
