import { create } from 'zustand';
import type { Mercenary } from '../types';

/**
 * 용병 슬레이트(slate)를 보관하는 store.
 *
 * setMercenaries는 React useState의 dispatch와 같은 시그니처로 노출되어
 * App.tsx의 기존 호출부를 손대지 않아도 된다.
 */
interface MercenaryStore {
  mercenaries: Mercenary[];
}

export const useMercenaryStore = create<MercenaryStore>(() => ({
  mercenaries: [],
}));

type SetArg = Mercenary[] | ((prev: Mercenary[]) => Mercenary[]);

export const setMercenaries = (arg: SetArg): void => {
  useMercenaryStore.setState((state) => ({
    mercenaries: typeof arg === 'function' ? arg(state.mercenaries) : arg,
  }));
};

export const useMercenaries = () => useMercenaryStore((s) => s.mercenaries);
