import type { Player, SkillNodeKind } from '../types';
import { SKILLS } from '../constants/skills';
import { getSkillLevel } from './skillMastery';

/**
 * 스킬 트리 시스템:
 * - 각 스킬마다 3 노드: damage / cooldown / range
 * - 노드 1점당 효과 +15% (damage/range), -15% (cooldown)
 * - 노드별 최대 5점 (총 15% × 5 = 75% / 35% cooldown 감소)
 * - 마스터리 레벨 1당 트리 포인트 1점 적립
 *
 * 키 포맷: `${skillId}.${nodeKind}` (예: 'cannonball.damage')
 */

export const NODE_VALUE_PER_POINT = 0.15;
export const MAX_POINTS_PER_NODE = 5;
export const NODE_KINDS: SkillNodeKind[] = ['damage', 'cooldown', 'range'];

export function makeNodeKey(skillId: string, kind: SkillNodeKind): string {
  return `${skillId}.${kind}`;
}

/** 한 노드에 투자된 포인트 수 (0..MAX). */
export function getNodePoints(
  allocations: Record<string, number> | undefined,
  skillId: string,
  kind: SkillNodeKind,
): number {
  if (!allocations) return 0;
  const v = allocations[makeNodeKey(skillId, kind)];
  return typeof v === 'number' && v > 0 ? Math.min(MAX_POINTS_PER_NODE, v) : 0;
}

/** 마스터리 합계로 총 가용 포인트 산출 (스킬별 mastery 레벨 합). */
export function totalEarnedPoints(skillMastery: Record<string, number>): number {
  let total = 0;
  for (const skillId of Object.keys(SKILLS)) {
    total += getSkillLevel(skillMastery[skillId]);
  }
  return total;
}

/** 이미 투자된 총 포인트 (모든 노드에 걸쳐 합). */
export function totalSpentPoints(allocations: Record<string, number> | undefined): number {
  if (!allocations) return 0;
  let total = 0;
  for (const v of Object.values(allocations)) {
    if (typeof v === 'number' && v > 0) {
      total += Math.min(MAX_POINTS_PER_NODE, v);
    }
  }
  return total;
}

/** 현재 가용 포인트 (적립 - 투자). */
export function availablePoints(player: Pick<Player, 'skillMastery' | 'skillTreeAllocations'>): number {
  return totalEarnedPoints(player.skillMastery) - totalSpentPoints(player.skillTreeAllocations);
}

/** 노드 1점 투자: 가용 포인트 + 최대치 체크 후 새 allocations 반환. 실패 시 null. */
export function investNodePoint(
  player: Pick<Player, 'skillMastery' | 'skillTreeAllocations'>,
  skillId: string,
  kind: SkillNodeKind,
): Record<string, number> | null {
  if (availablePoints(player) <= 0) return null;
  const current = getNodePoints(player.skillTreeAllocations, skillId, kind);
  if (current >= MAX_POINTS_PER_NODE) return null;
  return {
    ...(player.skillTreeAllocations ?? {}),
    [makeNodeKey(skillId, kind)]: current + 1,
  };
}

/** damage 곱셈 보너스: 1.0 base + node_points × 0.15. */
export function getDamageMult(
  allocations: Record<string, number> | undefined,
  skillId: string,
): number {
  return 1 + getNodePoints(allocations, skillId, 'damage') * NODE_VALUE_PER_POINT;
}

/** cooldown 곱셈 (감소): 1.0 base - node_points × 0.15 (최소 0.25). */
export function getCooldownMult(
  allocations: Record<string, number> | undefined,
  skillId: string,
): number {
  return Math.max(0.25, 1 - getNodePoints(allocations, skillId, 'cooldown') * NODE_VALUE_PER_POINT);
}

/** range 곱셈 보너스. */
export function getRangeMult(
  allocations: Record<string, number> | undefined,
  skillId: string,
): number {
  return 1 + getNodePoints(allocations, skillId, 'range') * NODE_VALUE_PER_POINT;
}

/** UI용 노드 라벨 + 설명. */
export const NODE_INFO: Record<SkillNodeKind, { label: string; icon: string; description: string }> = {
  damage:   { label: '데미지 강화', icon: '⚔️', description: '데미지 +15% (포인트당)' },
  cooldown: { label: '쿨다운 단축', icon: '⏱️', description: '쿨다운 -15% (포인트당)' },
  range:    { label: '사거리 확장', icon: '🎯', description: '사거리 +15% (포인트당)' },
};
