import { STAT_CONFIG } from '../constants/config';

/**
 * 스킬 시전 횟수 → 숙련도 레벨. 기본 1Lv, 10회마다 +1Lv, 최대 10Lv.
 */
export function getSkillLevel(casts: number | undefined): number {
  if (!casts || casts <= 0) return 1;
  const gained = Math.floor(casts / STAT_CONFIG.MASTERY_CASTS_PER_LEVEL);
  return Math.max(1, Math.min(STAT_CONFIG.MASTERY_LEVEL_CAP, 1 + gained));
}

/**
 * 숙련도 레벨별 데미지 배율. 1Lv=1.0, 10Lv=+45% (0.05 * 9).
 */
export function getMasteryDamageMult(level: number): number {
  return 1 + (level - 1) * STAT_CONFIG.MASTERY_BONUS_PER_LEVEL;
}

/**
 * 숙련도 진행도 (다음 레벨까지의 비율, 0~1). 캡 도달 시 1 반환.
 */
export function getMasteryProgress(casts: number | undefined): number {
  const c = casts || 0;
  const level = getSkillLevel(c);
  if (level >= STAT_CONFIG.MASTERY_LEVEL_CAP) return 1;
  const inLevel = c % STAT_CONFIG.MASTERY_CASTS_PER_LEVEL;
  return inLevel / STAT_CONFIG.MASTERY_CASTS_PER_LEVEL;
}
