import { create } from 'zustand';
import type { GameState, TileMap } from '../types';
import { GAME_STATES } from '../constants/config';
import { generateTownMap } from '../utils/mapGenerator';

/**
 * 월드/진행 상태 store.
 * - gameState: 화면 라우팅 키
 * - currentRegion / currentSubRegion: 현재 위치
 * - dungeonLevel: 던전 회차
 * - map: 현재 화면에 그려지는 타일맵 (마을/던전/보스 전환 시 교체)
 * - unlockedRegions / clearedSubRegions: 게임 진행도
 */
interface WorldStore {
  gameState: GameState;
  currentRegion: string;
  currentSubRegion: string | undefined;
  dungeonLevel: number;
  map: TileMap;
  unlockedRegions: string[];
  clearedSubRegions: string[];
  /** NG+ 차수 (0 = 일반, 1+ = 모든 보스 클리어 후 반복 차수) */
  ngPlusLevel: number;
}

export const useWorldStore = create<WorldStore>(() => ({
  gameState: GAME_STATES.MENU,
  currentRegion: 'portugal',
  currentSubRegion: undefined,
  dungeonLevel: 1,
  map: generateTownMap('portugal'),
  unlockedRegions: ['portugal', 'spain'],
  clearedSubRegions: [],
  ngPlusLevel: 0,
}));

type Updater<T> = T | ((prev: T) => T);

function makeSetter<K extends keyof WorldStore>(key: K) {
  return (arg: Updater<WorldStore[K]>): void => {
    useWorldStore.setState((state) => ({
      [key]: typeof arg === 'function' ? (arg as (p: WorldStore[K]) => WorldStore[K])(state[key]) : arg,
    } as Partial<WorldStore>));
  };
}

export const setGameState = makeSetter('gameState');
export const setCurrentRegion = makeSetter('currentRegion');
export const setCurrentSubRegion = makeSetter('currentSubRegion');
export const setDungeonLevel = makeSetter('dungeonLevel');
export const setMap = makeSetter('map');
export const setUnlockedRegions = makeSetter('unlockedRegions');
export const setClearedSubRegions = makeSetter('clearedSubRegions');
export const setNgPlusLevel = makeSetter('ngPlusLevel');

export const useGameState = () => useWorldStore((s) => s.gameState);
export const useCurrentRegion = () => useWorldStore((s) => s.currentRegion);
export const useCurrentSubRegion = () => useWorldStore((s) => s.currentSubRegion);
export const useDungeonLevel = () => useWorldStore((s) => s.dungeonLevel);
export const useMap = () => useWorldStore((s) => s.map);
export const useUnlockedRegions = () => useWorldStore((s) => s.unlockedRegions);
export const useClearedSubRegions = () => useWorldStore((s) => s.clearedSubRegions);
export const useNgPlusLevel = () => useWorldStore((s) => s.ngPlusLevel);
