import { useEffect, useRef, useState } from 'react';

/**
 * 터치 디바이스용 가상 조이스틱.
 *
 * useArrowKeys()의 pressedKeys ref를 받아 직접 w/a/s/d를 추가·제거한다.
 * useGameLoop은 그 Set만 읽으므로 키보드와 조이스틱이 동일 경로로 합쳐진다.
 *
 * 활성화 조건: (pointer: coarse) 미디어 쿼리 매치 — 터치만 가능한 디바이스에서만 노출.
 * 마우스+터치 하이브리드(태블릿 PC 등)는 노출 안 함.
 */

interface VirtualJoystickProps {
  pressedKeys: React.RefObject<Set<string>>;
}

const KNOB_RADIUS = 60;
const DEADZONE = 0.25;

export default function VirtualJoystick({ pressedKeys }: VirtualJoystickProps) {
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const [knobPos, setKnobPos] = useState<{ x: number; y: number } | null>(null);
  const baseRef = useRef<HTMLDivElement>(null);
  const touchIdRef = useRef<number | null>(null);
  const activeDirsRef = useRef<Set<string>>(new Set());

  // 1회 감지: pointer-coarse 미디어 쿼리
  useEffect(() => {
    const mq = window.matchMedia('(pointer: coarse)');
    setIsTouchDevice(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setIsTouchDevice(e.matches);
    mq.addEventListener?.('change', onChange);
    return () => mq.removeEventListener?.('change', onChange);
  }, []);

  // 조이스틱 활성 방향들이 바뀌면 pressedKeys ref 동기화 (replace)
  const syncKeys = (dirs: Set<string>) => {
    const prev = activeDirsRef.current;
    // remove old
    for (const k of prev) {
      if (!dirs.has(k)) pressedKeys.current?.delete(k);
    }
    // add new
    for (const k of dirs) {
      if (!prev.has(k)) pressedKeys.current?.add(k);
    }
    activeDirsRef.current = dirs;
  };

  const onTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    if (touchIdRef.current !== null) return;
    const t = e.changedTouches[0];
    touchIdRef.current = t.identifier;
    updateKnobFromTouch(t.clientX, t.clientY);
  };

  const onTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
    for (const t of Array.from(e.changedTouches)) {
      if (t.identifier === touchIdRef.current) {
        updateKnobFromTouch(t.clientX, t.clientY);
      }
    }
  };

  const onTouchEnd = (e: React.TouchEvent<HTMLDivElement>) => {
    for (const t of Array.from(e.changedTouches)) {
      if (t.identifier === touchIdRef.current) {
        touchIdRef.current = null;
        setKnobPos(null);
        syncKeys(new Set());
      }
    }
  };

  const updateKnobFromTouch = (clientX: number, clientY: number) => {
    const base = baseRef.current;
    if (!base) return;
    const rect = base.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    let dx = clientX - cx;
    let dy = clientY - cy;
    const len = Math.hypot(dx, dy);
    if (len > KNOB_RADIUS) {
      dx = (dx / len) * KNOB_RADIUS;
      dy = (dy / len) * KNOB_RADIUS;
    }
    setKnobPos({ x: dx, y: dy });

    const normalizedLen = Math.min(1, len / KNOB_RADIUS);
    const dirs = new Set<string>();
    if (normalizedLen >= DEADZONE) {
      const nx = dx / KNOB_RADIUS;
      const ny = dy / KNOB_RADIUS;
      // 30도 이상 기울어진 축에 대해 키 활성
      if (ny < -0.35) dirs.add('w');
      if (ny > 0.35) dirs.add('s');
      if (nx < -0.35) dirs.add('a');
      if (nx > 0.35) dirs.add('d');
    }
    syncKeys(dirs);
  };

  if (!isTouchDevice) return null;

  return (
    <div
      ref={baseRef}
      className="fixed left-6 bottom-6 z-50 w-[140px] h-[140px] rounded-full bg-age-navy/30 border-2 border-age-gold/40 backdrop-blur-sm touch-none select-none"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
      onTouchCancel={onTouchEnd}
      aria-label="이동 조이스틱"
    >
      <div
        className="absolute top-1/2 left-1/2 w-12 h-12 rounded-full bg-age-gold/80 border-2 border-age-gold transition-transform"
        style={{
          transform: `translate(calc(-50% + ${knobPos?.x ?? 0}px), calc(-50% + ${knobPos?.y ?? 0}px))`,
          transitionDuration: knobPos ? '0ms' : '120ms',
        }}
      />
    </div>
  );
}
