import { useCallback, useEffect, useRef, useState } from 'react';
import type { Item, TravelEncounter, TravelState, AchievementTrigger } from '../types';
import { GAME_STATES } from '../constants/config';
import { REGIONS } from '../constants/regions';
import { ITEMS } from '../constants/items';
import {
  calculateFoodConsumption,
  calculateTravelTime,
} from '../utils/stats';
import {
  generateTravelEncounters,
  resolveCombatEncounter,
} from '../utils/encounters';
import { generateTownMap } from '../utils/mapGenerator';
import { usePlayerStore, setPlayer } from '../stores/usePlayerStore';
import { setInventory } from '../stores/useInventoryStore';
import { useMercenaryStore } from '../stores/useMercenaryStore';
import {
  useGameState,
  useCurrentRegion,
  setGameState,
  setCurrentRegion,
  setMap,
} from '../stores/useWorldStore';

/**
 * 항해 도메인 훅:
 * - travel state (출발/도착, 진행도, 활성 조우)
 * - selectRegion: 지역 선택 → (같은 곳) 정보 표시 / (다른 곳) 항해 시작
 * - cancelTravel: 항해 취소 → 세계지도 복귀
 * - 항해 진행 루프(500ms 간격): 식량 소모, 조우 트리거, 도착 처리
 * - 조우 핸들러: 전투/보상/도주/구매 + 종료
 */
export interface TravelSystemHooks {
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
  gainExp: (amount: number) => void;
  unlockAchievement: (id: AchievementTrigger) => void;
  /** 같은 지역 선택 시 호출 — 부모가 RegionInfo 모달을 연다. */
  onShowRegionInfo: () => void;
  /** 항해 도착 시 호출 — 부모가 잔존 몬스터/투사체/드롭/보스를 정리한다. */
  onArrival: () => void;
}

export function useTravelSystem(hooks: TravelSystemHooks) {
  const [travelState, setTravelState] = useState<TravelState | null>(null);
  const [travelProgress, setTravelProgress] = useState(0);
  const [activeEncounter, setActiveEncounter] = useState<TravelEncounter | null>(null);

  const gameState = useGameState();
  const currentRegion = useCurrentRegion();

  const hooksRef = useRef(hooks);
  hooksRef.current = hooks;

  const selectRegion = useCallback(
    (regionId: string) => {
      const player = usePlayerStore.getState().player;
      const mercenaries = useMercenaryStore.getState().mercenaries;
      const region = REGIONS[regionId];
      if (!region || region.unlockLevel > player.level) return;

      if (regionId === currentRegion) {
        hooksRef.current.onShowRegionInfo();
        return;
      }

      const fromRegion = REGIONS[currentRegion];
      const toRegion = REGIONS[regionId];
      if (!fromRegion || !toRegion) return;

      const foodPerTravel = calculateFoodConsumption(player.int);
      const mercFood = mercenaries.reduce((s, m) => s + m.foodPerTravel, 0);
      const totalFoodNeeded = (foodPerTravel + mercFood) * 3; // rough estimate
      if (player.food < totalFoodNeeded) {
        hooksRef.current.addFloatingText(
          player.x || 500,
          (player.y || 400) - 30,
          '식량이 부족합니다!',
          '#e74c3c',
        );
        return;
      }

      const duration = calculateTravelTime(fromRegion.coordinates, toRegion.coordinates, player.agi);
      const encounters = generateTravelEncounters(duration, player.level);

      setTravelState({
        fromRegion: currentRegion,
        toRegion: regionId,
        startTime: Date.now(),
        duration,
        encounters,
        currentEncounterIndex: 0,
      });
      setTravelProgress(0);
      setGameState(GAME_STATES.TRAVELING);
    },
    [currentRegion],
  );

  const cancelTravel = useCallback(() => {
    setTravelState((prev) => {
      if (!prev) return prev;
      setGameState(GAME_STATES.WORLD_MAP);
      return null;
    });
  }, []);

  // Travel loop — player/mercs는 매 tick getState로 읽어 deps에서 제외.
  useEffect(() => {
    if (gameState !== GAME_STATES.TRAVELING || !travelState || activeEncounter) return;

    const interval = setInterval(() => {
      const now = Date.now();
      const elapsed = now - travelState.startTime;
      const progress = Math.min((elapsed / travelState.duration) * 100, 100);
      setTravelProgress(progress);

      const player = usePlayerStore.getState().player;
      const mercs = useMercenaryStore.getState().mercenaries;
      const foodPerTick = calculateFoodConsumption(player.int) / 12; // ~5sec intervals
      const mercFoodPerTick = mercs.reduce((s, m) => s + m.foodPerTravel, 0) / 12;
      const totalFoodTick = foodPerTick + mercFoodPerTick;

      setPlayer((prev) => {
        const newFood = prev.food - totalFoodTick;
        if (newFood <= 0) {
          return { ...prev, food: 0, hp: Math.max(1, prev.hp - 2) };
        }
        return { ...prev, food: newFood };
      });

      const nextEncounter = travelState.encounters.find(
        (e, i) =>
          !e.resolved &&
          i >= travelState.currentEncounterIndex &&
          progress >= e.triggeredAtPercent,
      );
      if (nextEncounter) {
        setActiveEncounter(nextEncounter);
      }

      if (progress >= 100) {
        clearInterval(interval);
        setCurrentRegion(travelState.toRegion);
        setMap(generateTownMap(travelState.toRegion));
        setPlayer((prev) => ({ ...prev, x: 500, y: 400, targetX: 500, targetY: 400 }));
        hooksRef.current.onArrival();
        setTravelState(null);
        setGameState(GAME_STATES.TOWN);
        hooksRef.current.unlockAchievement('first_travel');
      }
    }, 500);

    return () => clearInterval(interval);
  }, [gameState, travelState, activeEncounter]);

  const handleEncounterFight = useCallback((): boolean => {
    if (!activeEncounter) return false;
    const player = usePlayerStore.getState().player;
    const mercenaries = useMercenaryStore.getState().mercenaries;
    const playerPower = player.attack + player.defense + player.magic;
    const mercPower = mercenaries.reduce((s, m) => s + m.attack + m.defense, 0);
    const won = resolveCombatEncounter(playerPower, mercPower, activeEncounter.data.enemyPower || 0);

    if (!won) {
      setPlayer((prev) => ({
        ...prev,
        hp: Math.max(1, prev.hp - Math.floor(prev.maxHp * 0.2)),
      }));
    }
    return won;
  }, [activeEncounter]);

  const handleEncounterCollectReward = useCallback(() => {
    if (!activeEncounter?.data.reward) return;
    const reward = activeEncounter.data.reward;
    if (reward.gold) setPlayer((prev) => ({ ...prev, gold: prev.gold + reward.gold! }));
    if (reward.exp) hooksRef.current.gainExp(reward.exp);
    if (reward.items) {
      for (const itemId of reward.items) {
        const item = ITEMS[itemId];
        if (item) {
          setInventory((inv) => [...inv, { ...item, uid: `inv_${Date.now()}_${Math.random()}` }]);
        }
      }
    }
  }, [activeEncounter]);

  const handleEncounterFlee = useCallback(() => {
    // Just close the encounter (no side effects). closeEncounter is called by the caller.
  }, []);

  const handleEncounterBuyItem = useCallback((item: Item) => {
    const player = usePlayerStore.getState().player;
    if (player.gold < item.price) return;
    if (player.currentWeight + item.weight > player.maxWeight) return;
    setPlayer((prev) => ({ ...prev, gold: prev.gold - item.price }));
    setInventory((inv) => [...inv, { ...item, uid: `inv_${Date.now()}` }]);
  }, []);

  const closeEncounter = useCallback(() => {
    setTravelState((prev) => {
      if (!prev) return prev;
      if (!activeEncounter) return prev;
      const updatedEncounters = prev.encounters.map((e) =>
        e === activeEncounter ? { ...e, resolved: true } : e,
      );
      let currentEncounterIndex = updatedEncounters.findIndex((e) => !e.resolved);
      if (currentEncounterIndex === -1) currentEncounterIndex = updatedEncounters.length;
      return { ...prev, encounters: updatedEncounters, currentEncounterIndex };
    });
    setActiveEncounter(null);
  }, [activeEncounter]);

  return {
    travelState,
    travelProgress,
    activeEncounter,
    selectRegion,
    cancelTravel,
    handleEncounterFight,
    handleEncounterCollectReward,
    handleEncounterFlee,
    handleEncounterBuyItem,
    closeEncounter,
  };
}
