import { useState } from 'react';
import { getRarityColor } from '../../utils/combat';
import { formatAffix } from '../../utils/affixes';
import { findSetForItem, getSetActivationSummary, getActiveSetBonuses } from '../../utils/itemSets';
import { ITEM_RARITY } from '../../constants/config';
import type { Player, InventoryItem, Equipment } from '../../types';
import { Panel } from '../ui';

interface InventoryModalProps {
  inventory: InventoryItem[];
  player: Player;
  equipment: Equipment;
  onUseItem: (uid: string) => void;
  onClose: () => void;
}

type TabType = 'all' | 'equipment' | 'consumable' | 'material' | 'trade_good';

const TYPE_LABEL: Record<string, string> = {
  equipment: '장비',
  consumable: '소모품',
  food: '식량',
  material: '재료',
  trade_good: '교역품',
};

export default function InventoryModal({ inventory, player, equipment, onUseItem, onClose }: InventoryModalProps) {
  const [tab, setTab] = useState<TabType>('all');
  const [hoverItem, setHoverItem] = useState<InventoryItem | null>(null);

  const filtered = tab === 'all' ? inventory : inventory.filter(i => {
    if (tab === 'consumable') return i.type === 'consumable' || i.type === 'food';
    return i.type === tab;
  });

  const tabs: { key: TabType; label: string }[] = [
    { key: 'all', label: '전체' },
    { key: 'equipment', label: '장비' },
    { key: 'consumable', label: '소비' },
    { key: 'material', label: '재료' },
    { key: 'trade_good', label: '교역품' },
  ];

  return (
    <Panel title="인벤토리" icon={'🎒'} onClose={onClose} maxWidth="min-w-[400px]">
      <div className="flex gap-1 mb-3">
        {tabs.map(t => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={`px-2.5 py-1 text-xs rounded transition-colors ${
              tab === t.key
                ? 'bg-age-gold/25 text-age-gold border border-age-gold/50'
                : 'bg-age-navy/70 text-age-paper/60 border border-age-gold/15 hover:text-age-paper hover:border-age-gold/40'
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div className="relative">
        <div className="grid grid-cols-5 gap-2 mb-3">
          {Array(20).fill(null).map((_, i) => {
            const item = filtered[i];
            return (
              <button
                key={i}
                onClick={() => item && onUseItem(item.uid)}
                onMouseEnter={() => item && setHoverItem(item)}
                onMouseLeave={() => setHoverItem(null)}
                className={`w-12 h-12 rounded-sm border-2 flex items-center justify-center transition-all relative ${
                  item
                    ? 'bg-age-navy/70 hover:bg-age-navy/40 hover:shadow-gold'
                    : 'bg-age-navy/40 border-age-gold/10'
                }`}
                style={item ? { borderColor: getRarityColor(item.rarity) } : {}}
              >
                {item && <span className="text-xl">{item.icon}</span>}
              </button>
            );
          })}
        </div>

        {hoverItem && (
          <ItemTooltip
            item={hoverItem}
            equippedInSlot={hoverItem.type === 'equipment' && hoverItem.slot ? equipment[hoverItem.slot] : null}
            equipment={equipment}
          />
        )}
      </div>

      <ActiveSetBonuses equipment={equipment} />

      <div className="text-xs text-age-paper/70 space-y-1 border-t border-age-gold/20 pt-2">
        <p>
          <span style={{ color: '#e89c8c' }}>STR {player.str}</span>
          <span className="text-age-paper/40"> | </span>
          <span style={{ color: '#9de09a' }}>AGI {player.agi}</span>
          <span className="text-age-paper/40"> | </span>
          <span style={{ color: '#8cc8e8' }}>INT {player.int}</span>
        </p>
        <p>
          {'⚔️'} 공격: {player.attack} | {'🛡️'} 방어: {player.defense} | {'✨'} 마법: {player.magic} | {'💨'} 속도: {player.speed.toFixed(1)}
        </p>
        <p className="text-age-amber">
          {'✦'} 크리: {(player.critChance * 100).toFixed(0)}% × {player.critDamage.toFixed(1)}
        </p>
        <p className="text-age-amber">
          {'⚖️'} 무게: {Math.floor(player.currentWeight)} / {player.maxWeight} kg
        </p>
      </div>
    </Panel>
  );
}

function ItemTooltip({ item, equippedInSlot, equipment }: { item: InventoryItem; equippedInSlot?: InventoryItem | null; equipment: Equipment }) {
  const itemSet = findSetForItem(item.id);
  const setSummary = itemSet ? getSetActivationSummary(equipment, itemSet) : null;
  const rarity = ITEM_RARITY[item.rarity];
  const color = rarity.color;
  const statEntries = item.stats
    ? (Object.entries(item.stats).filter(([, v]) => typeof v === 'number' && v !== 0) as [keyof NonNullable<InventoryItem['stats']>, number][])
    : [];

  // 비교: 같은 슬롯에 장착 중인 장비 vs 호버 중 장비
  const isEquipment = item.type === 'equipment';
  const equipped = isEquipment ? equippedInSlot ?? null : null;
  type StatKey = keyof NonNullable<InventoryItem['stats']>;
  const allStatKeys: StatKey[] = ['attack', 'defense', 'magic', 'maxHp', 'maxMp', 'speed'];
  const diffs = isEquipment
    ? allStatKeys
        .map(k => {
          const cur = (item.stats?.[k] ?? 0) as number;
          const old = (equipped?.stats?.[k] ?? 0) as number;
          return { k, delta: cur - old };
        })
        .filter(d => d.delta !== 0)
    : [];

  return (
    <div
      className="absolute left-1/2 -translate-x-1/2 -top-2 -translate-y-full z-20 panel-parchment border-2 rounded-md px-3 py-2 text-xs min-w-[200px] max-w-[260px] pointer-events-none shadow-gold"
      style={{ borderColor: color }}
    >
      <div className="font-bold text-sm mb-1" style={{ color }}>
        {item.icon} {item.name}
      </div>
      <div className="text-age-paper/70 text-[11px] mb-1.5">
        {rarity.name} · {TYPE_LABEL[item.type] ?? item.type}
        {item.slot && <span> · {item.slot}</span>}
      </div>

      {statEntries.length > 0 && (
        <div className="space-y-0.5 mb-1.5 border-t border-age-gold/20 pt-1.5">
          {statEntries.map(([k, v]) => (
            <div key={k} className="text-age-leaf">
              {STAT_ICON[k]} {STAT_LABEL[k]} +{v}
            </div>
          ))}
        </div>
      )}

      {item.rolledAffixes && item.rolledAffixes.length > 0 && (
        <div className="space-y-0.5 mb-1.5 border-t border-age-gold/20 pt-1.5">
          <div className="text-[10px] text-age-paper/50 mb-0.5">옵션</div>
          {item.rolledAffixes.map((aff, i) => (
            <div key={i} className="text-age-amber text-[11px]">
              ✦ {formatAffix(aff)}
            </div>
          ))}
        </div>
      )}

      {itemSet && setSummary && (
        <div className="space-y-0.5 mb-1.5 border-t border-age-gold/20 pt-1.5">
          <div className="text-[10px] text-age-paper/50 mb-0.5">
            🌟 {itemSet.name} ({setSummary.equippedCount} / {itemSet.items.length} 장착)
          </div>
          {itemSet.bonuses.map((b, i) => {
            const active = setSummary.equippedCount >= b.pieces;
            return (
              <div key={i} className={`text-[11px] ${active ? 'text-age-leaf font-bold' : 'text-age-paper/40'}`}>
                {active ? '✓ ' : '○ '}{b.description}
              </div>
            );
          })}
        </div>
      )}

      {isEquipment && (
        <div className="space-y-0.5 mb-1.5 border-t border-age-gold/20 pt-1.5">
          <div className="text-[10px] text-age-paper/50 mb-0.5">
            {equipped ? `장착 비교 (vs ${equipped.icon} ${equipped.name})` : '비교 (현재 미장착)'}
          </div>
          {diffs.length === 0 && (
            <div className="text-age-paper/40 text-[11px]">차이 없음</div>
          )}
          {diffs.map(({ k, delta }) => (
            <div
              key={k}
              className="text-[11px]"
              style={{ color: delta > 0 ? '#4ade80' : '#f87171' }}
            >
              {STAT_ICON[k]} {STAT_LABEL[k]} {delta > 0 ? `+${delta}` : delta}
            </div>
          ))}
        </div>
      )}

      {item.effect && typeof item.value === 'number' && (
        <div className="text-age-sea mb-1">
          {item.effect === 'hp' && `❤️ HP +${item.value}`}
          {item.effect === 'mp' && `💧 MP +${item.value}`}
          {item.effect === 'both' && `❤️💧 HP/MP +${item.value}`}
        </div>
      )}

      {typeof item.foodValue === 'number' && (
        <div className="text-age-leaf mb-1">🍞 식량 +{item.foodValue}</div>
      )}

      {item.tradeInfo && (
        <div className="text-age-amber mb-1">
          ⚓ {item.tradeInfo.originRegion} 특산품
        </div>
      )}

      <div className="flex justify-between text-[11px] text-age-paper/60 border-t border-age-gold/20 pt-1">
        <span>⚖️ {item.weight}kg</span>
        <span className="text-age-gold">💰 {item.price}</span>
      </div>
    </div>
  );
}

function ActiveSetBonuses({ equipment }: { equipment: Equipment }) {
  const active = getActiveSetBonuses(equipment);
  if (active.length === 0) return null;
  return (
    <div className="text-xs border-t border-age-gold/20 pt-2 mb-2 space-y-0.5">
      <div className="text-[10px] text-age-paper/50 mb-0.5">활성 세트 보너스</div>
      {active.map(({ set, bonus }, i) => (
        <div key={`${set.id}-${i}`} className="text-age-leaf text-[11px]">
          🌟 <span className="font-bold">{set.name}</span> · {bonus.description}
        </div>
      ))}
    </div>
  );
}

const STAT_LABEL: Record<keyof NonNullable<InventoryItem['stats']>, string> = {
  attack: '공격',
  defense: '방어',
  magic: '마법',
  maxHp: '최대 HP',
  maxMp: '최대 MP',
  speed: '속도',
};

const STAT_ICON: Record<keyof NonNullable<InventoryItem['stats']>, string> = {
  attack: '⚔️',
  defense: '🛡️',
  magic: '✨',
  maxHp: '❤️',
  maxMp: '💧',
  speed: '💨',
};
