import { useEffect, useState } from 'react';
import { Panel, Button } from '../ui';
import { getAudioSettings, setAudioEnabled, setAudioVolume, subscribeAudio } from '../../utils/audio';
import {
  applyQualityPreset,
  getGraphicsSettings,
  setGraphicsToggle,
  subscribeGraphics,
  type GraphicsQuality,
  type GraphicsSettings,
} from '../../utils/graphicsSettings';
import { resetTutorial } from '../TutorialOverlay';
import { setLanguage, getLanguage } from '../../i18n/config';

interface SettingsModalProps {
  autoSaveEnabled: boolean;
  autoSaveIntervalMinutes: number;
  unlockedAchievements: string[];
  totalAchievements: number;
  onToggleAutoSave: () => void;
  onSetAutoSaveInterval: (minutes: number) => void;
  onOpenSlots: () => void;
  onExport: () => void;
  onImport: () => void;
  onClose: () => void;
}

const INTERVAL_OPTIONS = [1, 3, 5, 10];

export default function SettingsModal({
  autoSaveEnabled,
  autoSaveIntervalMinutes,
  unlockedAchievements,
  totalAchievements,
  onToggleAutoSave,
  onSetAutoSaveInterval,
  onOpenSlots,
  onExport,
  onImport,
  onClose,
}: SettingsModalProps) {
  const [audio, setAudio] = useState(getAudioSettings());
  const [gfx, setGfx] = useState<GraphicsSettings>({ ...getGraphicsSettings() });

  useEffect(() => {
    const unsub = subscribeAudio(() => setAudio(getAudioSettings()));
    return unsub;
  }, []);

  useEffect(() => {
    const unsub = subscribeGraphics(() => setGfx({ ...getGraphicsSettings() }));
    return unsub;
  }, []);

  const QUALITY_LABELS: Record<GraphicsQuality, string> = { low: '저', medium: '중', high: '고' };

  const renderGfxToggle = (key: keyof Omit<GraphicsSettings, 'quality'>, label: string) => (
    <div className="flex items-center justify-between bg-age-navy/70 border border-age-gold/20 rounded p-2 mb-1.5">
      <span className="text-age-paper text-xs">{label}</span>
      <button
        onClick={() => setGraphicsToggle(key, !gfx[key])}
        className={`relative w-10 h-5 rounded-full transition-colors ${
          gfx[key] ? 'bg-age-gold/70' : 'bg-age-navy border border-age-gold/30'
        }`}
      >
        <span
          className={`absolute top-0.5 w-4 h-4 rounded-full bg-age-paper transition-all ${
            gfx[key] ? 'left-5' : 'left-0.5'
          }`}
        />
      </button>
    </div>
  );

  return (
    <Panel layout="center" backdrop title="설정" icon={'⚙️'} onClose={onClose} maxWidth="max-w-md w-full">
      <section className="mb-5">
        <h3 className="text-age-amber text-sm mb-2 font-semibold">사운드</h3>
        <div className="flex items-center justify-between bg-age-navy/70 border border-age-gold/20 rounded p-3 mb-2">
          <span className="text-age-paper text-sm">{audio.enabled ? '🔊 효과음 켜짐' : '🔇 효과음 꺼짐'}</span>
          <button
            onClick={() => setAudioEnabled(!audio.enabled)}
            className={`relative w-12 h-6 rounded-full transition-colors ${
              audio.enabled ? 'bg-age-gold/70' : 'bg-age-navy border border-age-gold/30'
            }`}
          >
            <span
              className={`absolute top-0.5 w-5 h-5 rounded-full bg-age-paper transition-all ${
                audio.enabled ? 'left-6' : 'left-0.5'
              }`}
            />
          </button>
        </div>
        <div className="flex items-center gap-3 bg-age-navy/70 border border-age-gold/20 rounded p-3">
          <span className="text-age-paper/80 text-xs w-10">음량</span>
          <input
            type="range"
            min={0}
            max={100}
            value={Math.round(audio.volume * 100)}
            onChange={e => setAudioVolume(Number(e.target.value) / 100)}
            disabled={!audio.enabled}
            className={`flex-1 accent-age-gold ${!audio.enabled ? 'opacity-40 cursor-not-allowed' : ''}`}
          />
          <span className="text-age-gold text-xs w-10 text-right">{Math.round(audio.volume * 100)}%</span>
        </div>
      </section>

      <section className="mb-5">
        <h3 className="text-age-amber text-sm mb-2 font-semibold">그래픽</h3>
        <div className="text-age-paper/70 text-xs mb-1">품질 프리셋</div>
        <div className="flex gap-2 mb-2">
          {(['low', 'medium', 'high'] as GraphicsQuality[]).map(q => (
            <button
              key={q}
              onClick={() => applyQualityPreset(q)}
              className={`flex-1 py-1.5 rounded text-xs transition-colors ${
                gfx.quality === q
                  ? 'bg-age-gold/25 text-age-gold border border-age-gold/50'
                  : 'bg-age-navy/70 text-age-paper/60 border border-age-gold/15 hover:text-age-paper'
              }`}
            >
              {QUALITY_LABELS[q]}
            </button>
          ))}
        </div>
        {renderGfxToggle('waterShader', '🌊 물 셰이더 (파도 애니메이션)')}
        {renderGfxToggle('dynamicLighting', '💡 동적 조명 (던전 횃불)')}
        {renderGfxToggle('particles', '✨ 파티클 (사망 폭발)')}
        {renderGfxToggle('floatingText', '💬 플로팅 텍스트')}
        {renderGfxToggle('cameraShake', '📳 카메라 흔들림')}
        {renderGfxToggle('postprocessing', '🌟 포스트프로세싱 (블룸 / 비네팅 / 저체력 색수차)')}
      </section>

      <section className="mb-5">
        <h3 className="text-age-amber text-sm mb-2 font-semibold">자동 저장</h3>
        <div className="flex items-center justify-between bg-age-navy/70 border border-age-gold/20 rounded p-3 mb-2">
          <span className="text-age-paper text-sm">자동 저장 {autoSaveEnabled ? '사용' : '해제'}</span>
          <button
            onClick={onToggleAutoSave}
            className={`relative w-12 h-6 rounded-full transition-colors ${
              autoSaveEnabled ? 'bg-age-gold/70' : 'bg-age-navy border border-age-gold/30'
            }`}
          >
            <span
              className={`absolute top-0.5 w-5 h-5 rounded-full bg-age-paper transition-all ${
                autoSaveEnabled ? 'left-6' : 'left-0.5'
              }`}
            />
          </button>
        </div>
        <div className="text-age-paper/70 text-xs mb-2">저장 간격</div>
        <div className="flex gap-2">
          {INTERVAL_OPTIONS.map(min => (
            <button
              key={min}
              onClick={() => onSetAutoSaveInterval(min)}
              disabled={!autoSaveEnabled}
              className={`flex-1 py-1.5 rounded text-xs transition-colors ${
                autoSaveIntervalMinutes === min
                  ? 'bg-age-gold/25 text-age-gold border border-age-gold/50'
                  : 'bg-age-navy/70 text-age-paper/60 border border-age-gold/15 hover:text-age-paper'
              } ${!autoSaveEnabled ? 'opacity-40 cursor-not-allowed' : ''}`}
            >
              {min}분
            </button>
          ))}
        </div>
      </section>

      <section className="mb-5">
        <h3 className="text-age-amber text-sm mb-2 font-semibold">세이브</h3>
        <div className="flex gap-2">
          <Button size="sm" fullWidth onClick={onOpenSlots}>{'💾'} 슬롯 관리</Button>
          <Button size="sm" variant="ghost" onClick={onExport}>{'⬇️'} 내보내기</Button>
          <Button size="sm" variant="ghost" onClick={onImport}>{'⬆️'} 불러오기</Button>
        </div>
        <div className="mt-2">
          <Button
            size="sm"
            variant="ghost"
            fullWidth
            onClick={() => {
              resetTutorial();
              onClose();
            }}
          >
            📖 튜토리얼 다시 보기 (다음 마을 진입 시)
          </Button>
        </div>
        <div className="mt-3">
          <h3 className="text-age-amber text-xs mb-1 font-semibold">🌐 언어 / Language</h3>
          <div className="flex gap-2">
            <Button
              size="sm"
              fullWidth
              variant={getLanguage() === 'ko' ? 'primary' : 'ghost'}
              onClick={() => { setLanguage('ko'); onClose(); }}
            >
              한국어
            </Button>
            <Button
              size="sm"
              fullWidth
              variant={getLanguage() === 'en' ? 'primary' : 'ghost'}
              onClick={() => { setLanguage('en'); onClose(); }}
            >
              English (preview)
            </Button>
          </div>
          <p className="text-[10px] text-age-paper/50 mt-1">
            영어 번역은 현재 메뉴/설정만 적용됩니다. 게임 내 텍스트는 한국어로 표시됩니다.
          </p>
        </div>
      </section>

      <section>
        <h3 className="text-age-amber text-sm mb-2 font-semibold">업적</h3>
        <div className="bg-age-navy/70 border border-age-gold/20 rounded p-3 text-sm">
          <div className="text-age-paper/80">
            달성:{' '}
            <span className="text-age-gold font-bold">{unlockedAchievements.length}</span>
            <span className="text-age-paper/50"> / {totalAchievements}</span>
          </div>
          <div className="mt-2 w-full h-2 bg-age-navy rounded-sm overflow-hidden border border-age-gold/20">
            <div
              className="h-full bg-age-gold transition-all"
              style={{ width: `${totalAchievements === 0 ? 0 : (unlockedAchievements.length / totalAchievements) * 100}%` }}
            />
          </div>
        </div>
      </section>
    </Panel>
  );
}
