import { ITEM_RARITY, MONSTER_TYPES } from '../constants/config';
import type { ItemRarityKey } from '../types';

/** 아이템 등급에 해당하는 색상 코드 반환 (없으면 흰색) */
export const getRarityColor = (rarity?: ItemRarityKey): string =>
  (rarity && ITEM_RARITY[rarity]?.color) || '#ffffff';

/** 속성 상성에 따른 데미지 계산 (유리 1.5배, 불리 0.7배, 무속성/동일 1배) */
export const calculateTypeDamage = (attackerType: string | null, defenderType: string, baseDamage: number): number => {
  if (!attackerType || !defenderType) return baseDamage;
  const type = MONSTER_TYPES[attackerType];
  if (!type) return baseDamage;
  if (type.strength === defenderType) return Math.floor(baseDamage * 1.5);
  if (type.weakness === defenderType) return Math.floor(baseDamage * 0.7);
  return baseDamage;
};

/**
 * Roll final damage with ±15% variance and critical-hit check.
 * Returns both the rolled integer damage and whether it was a crit.
 */
export const rollDamage = (base: number, critChance = 0, critMult = 1.5): { damage: number; isCrit: boolean } => {
  const variance = 0.85 + Math.random() * 0.3; // 0.85..1.15
  const isCrit = critChance > 0 && Math.random() < critChance;
  const mult = isCrit ? critMult : 1;
  return { damage: Math.max(1, Math.floor(base * variance * mult)), isCrit };
};
