import type { Item } from '../types';
import { getRegionDistance } from './stats';

/** 무역품 판매 가격 계산 - 원산지에서는 기본가, 멀수록 최대 priceMult배까지 상승 */
export function calculateTradePrice(item: Item, currentRegion: string): number {
  if (!item.tradeInfo) return item.price;

  const { originRegion, basePrice, priceMult } = item.tradeInfo;

  if (currentRegion === originRegion) {
    return basePrice;
  }

  const distance = getRegionDistance(originRegion, currentRegion);
  // Distance ranges from ~3 to ~40 units; normalize to 0-1
  const normalizedDist = Math.min(distance / 40, 1);

  // Price increases with distance: at max distance, price = basePrice * priceMult
  const sellPrice = Math.floor(basePrice * (1 + normalizedDist * (priceMult - 1)));
  return sellPrice;
}
