import { useEffect } from 'react';
import { GAME_STATES } from '../constants/config';
import { SKILLS } from '../constants/skills';
import type { GameState } from '../types';

/** useKeyboardInput 훅 파라미터 - 모달 토글, 스킬 선택, 저장 콜백 */
interface UseKeyboardInputParams {
  gameState: GameState;
  playerLevel: number;
  returnToWorldMap: () => void;
  setShowInventory: React.Dispatch<React.SetStateAction<boolean>>;
  setShowQuests: React.Dispatch<React.SetStateAction<boolean>>;
  setShowShop: React.Dispatch<React.SetStateAction<boolean>>;
  setShowCrafting: React.Dispatch<React.SetStateAction<boolean>>;
  setShowRegionInfo: React.Dispatch<React.SetStateAction<boolean>>;
  setShowSkillTree?: React.Dispatch<React.SetStateAction<boolean>>;
  setSelectedSkill: React.Dispatch<React.SetStateAction<string>>;
  onSaveGame?: () => void;
  /** 모달이 하나라도 열려있는지 (true일 때 Esc는 모달만 닫음) */
  anyModalOpen?: boolean;
  /** 일시정지 토글 콜백 (TOWN/DUNGEON/BOSS에서만 동작) */
  togglePause?: () => void;
  /** Tab 키로 타겟 락 사이클 (DUNGEON/BOSS에서만) */
  cycleTarget?: () => void;
  /** Space 키로 락된 타겟에 선택 스킬 시전 */
  attackLockedTarget?: () => void;
}

/**
 * 키보드 단축키 훅 - I(인벤토리), Q(퀘스트), M(세계지도), 1~6(스킬), F5(저장), ESC(닫기)
 * 한글 IME 키(ㅑ,ㅂ,ㅡ)도 지원
 */
export function useKeyboardInput({
  gameState,
  playerLevel,
  returnToWorldMap,
  setShowInventory,
  setShowQuests,
  setShowShop,
  setShowCrafting,
  setShowRegionInfo,
  setShowSkillTree,
  setSelectedSkill,
  onSaveGame,
  anyModalOpen,
  togglePause,
  cycleTarget,
  attackLockedTarget,
}: UseKeyboardInputParams) {
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (gameState === GAME_STATES.MENU) return;

      if (e.key === 'F5' && onSaveGame && (gameState === GAME_STATES.TOWN || gameState === GAME_STATES.WORLD_MAP)) {
        e.preventDefault();
        onSaveGame();
        return;
      }

      // Tab: 타겟 사이클 (DUNGEON/BOSS에서 모달 닫혀있을 때만)
      if (e.key === 'Tab' && !anyModalOpen && cycleTarget &&
          (gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS)) {
        e.preventDefault();
        cycleTarget();
        return;
      }
      // Space: 락된 타겟 공격
      if (e.key === ' ' && !anyModalOpen && attackLockedTarget &&
          (gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS)) {
        e.preventDefault();
        attackLockedTarget();
        return;
      }

      const k = e.key.toLowerCase();
      if (k === 'i' || k === 'ㅑ') {
        setShowInventory(p => !p);
        setShowQuests(false);
        setShowShop(false);
        setShowCrafting(false);
      } else if (k === 'q' || k === 'ㅂ') {
        setShowQuests(p => !p);
        setShowInventory(false);
        setShowShop(false);
        setShowCrafting(false);
      } else if (k === 'm' || k === 'ㅡ') {
        if (gameState === GAME_STATES.TOWN) returnToWorldMap();
      } else if ((k === 't' || k === 'ㅅ') && setShowSkillTree) {
        setShowSkillTree(p => !p);
      } else if (k === 'escape') {
        if (anyModalOpen) {
          setShowInventory(false);
          setShowQuests(false);
          setShowShop(false);
          setShowCrafting(false);
          setShowRegionInfo(false);
        } else if (
          togglePause &&
          (gameState === GAME_STATES.TOWN ||
            gameState === GAME_STATES.DUNGEON ||
            gameState === GAME_STATES.BOSS)
        ) {
          togglePause();
        }
      } else if (k >= '1' && k <= '6') {
        const skills = Object.keys(SKILLS);
        const idx = parseInt(k) - 1;
        if (skills[idx] && SKILLS[skills[idx]].unlockLevel <= playerLevel) {
          setSelectedSkill(skills[idx]);
        }
      }
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [gameState, playerLevel, returnToWorldMap, setShowInventory, setShowQuests, setShowShop, setShowCrafting, setShowRegionInfo, setShowSkillTree, setSelectedSkill, onSaveGame, anyModalOpen, togglePause, cycleTarget, attackLockedTarget]);
}
