import React from 'react'
import ReactDOM from 'react-dom/client'
import * as Sentry from '@sentry/react'
import App from './App'
import { initSentry } from './utils/sentry'
import './i18n/config'
import './index.css'

const sentryActive = initSentry()
const RootApp = sentryActive ? Sentry.withErrorBoundary(App, {
  fallback: (
    <div style={{
      padding: 24, color: '#fff', background: '#1a1a2e', height: '100vh',
      display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: 12,
    }}>
      <h2>예기치 않은 오류가 발생했습니다</h2>
      <p style={{ opacity: 0.7, fontSize: 13 }}>새로고침하면 마지막 자동 저장에서 계속 진행할 수 있습니다.</p>
      <button onClick={() => window.location.reload()} style={{ padding: '6px 14px', cursor: 'pointer' }}>새로고침</button>
    </div>
  ),
}) : App

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <RootApp />
  </React.StrictMode>,
)
