import { create } from 'zustand';
import type { SpawnedMonster, Projectile, DroppedItem } from '../types';

/**
 * 휘발성 전투 상태 store.
 *
 * - monsters: 던전/마을의 활성 몬스터 목록 (useGameLoop가 매 프레임 갱신)
 * - boss: 보스 슬롯 (없으면 null)
 * - projectiles: 비행 중인 투사체 (매 프레임 위치 갱신 / 사거리 도달 시 제거)
 * - droppedItems: 바닥에 떨어진 골드/아이템/상자 (픽업 시 제거)
 *
 * 매 프레임 갱신되는 특성상 셀렉터를 좁게 잡아 GameScene만 구독하도록 설계되었다.
 */
interface CombatStore {
  monsters: SpawnedMonster[];
  boss: SpawnedMonster | null;
  projectiles: Projectile[];
  droppedItems: DroppedItem[];
}

export const useCombatStore = create<CombatStore>(() => ({
  monsters: [],
  boss: null,
  projectiles: [],
  droppedItems: [],
}));

type Updater<T> = T | ((prev: T) => T);

function makeSetter<K extends keyof CombatStore>(key: K) {
  return (arg: Updater<CombatStore[K]>): void => {
    useCombatStore.setState((state) => ({
      [key]: typeof arg === 'function' ? (arg as (p: CombatStore[K]) => CombatStore[K])(state[key]) : arg,
    } as Partial<CombatStore>));
  };
}

export const setMonsters = makeSetter('monsters');
export const setBoss = makeSetter('boss');
export const setProjectiles = makeSetter('projectiles');
export const setDroppedItems = makeSetter('droppedItems');

export const useMonsters = () => useCombatStore((s) => s.monsters);
export const useBoss = () => useCombatStore((s) => s.boss);
export const useProjectiles = () => useCombatStore((s) => s.projectiles);
export const useDroppedItems = () => useCombatStore((s) => s.droppedItems);
