import { GAME_CONFIG } from '../constants/config';

/** 두 점 사이의 유클리드 거리 계산 */
export const getDistance = (x1: number, y1: number, x2: number, y2: number): number =>
  Math.hypot(x2 - x1, y2 - y1);

/** 두 점 사이의 각도(라디안) 계산 - 투사체 방향에 사용 */
export const getAngle = (x1: number, y1: number, x2: number, y2: number): number =>
  Math.atan2(y2 - y1, x2 - x1);

/** 픽셀 좌표를 타일 그리드 좌표로 변환 (40px 단위) */
export const pixelToTile = (x: number, y: number): { tileX: number; tileY: number } => ({
  tileX: Math.floor(x / GAME_CONFIG.TILE_SIZE),
  tileY: Math.floor(y / GAME_CONFIG.TILE_SIZE),
});

/** 레벨에 필요한 경험치 계산 (100 × 1.5^(level-1), 지수적 증가) */
export const calculateExpToLevel = (level: number): number =>
  Math.floor(100 * Math.pow(1.5, level - 1));
