import { useCallback, useRef, useState } from 'react';
import { ACHIEVEMENTS } from '../constants/achievements';
import type { AchievementTrigger } from '../types';
import type { ToastData } from '../components/ui';

export interface UseAchievementsApi {
  unlocked: string[];
  toasts: ToastData[];
  unlock: (trigger: AchievementTrigger) => void;
  pushToast: (toast: Omit<ToastData, 'id'>) => void;
  dismissToast: (id: number) => void;
  restore: (ids: string[]) => void;
}

export function useAchievements(): UseAchievementsApi {
  const [unlocked, setUnlocked] = useState<string[]>([]);
  const [toasts, setToasts] = useState<ToastData[]>([]);
  const toastIdRef = useRef(1);

  const pushToast = useCallback((toast: Omit<ToastData, 'id'>) => {
    const id = toastIdRef.current++;
    setToasts(prev => [...prev, { id, ...toast }]);
  }, []);

  const dismissToast = useCallback((id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const unlock = useCallback((trigger: AchievementTrigger) => {
    setUnlocked(prev => {
      if (prev.includes(trigger)) return prev;
      const ach = ACHIEVEMENTS[trigger];
      if (!ach) return prev;
      const id = toastIdRef.current++;
      setToasts(ts => [...ts, {
        id,
        title: `업적 달성 - ${ach.name}`,
        message: ach.description,
        icon: ach.icon,
        tone: 'achievement',
        duration: 4200,
      }]);
      return [...prev, trigger];
    });
  }, []);

  const restore = useCallback((ids: string[]) => {
    setUnlocked(ids);
  }, []);

  return { unlocked, toasts, unlock, pushToast, dismissToast, restore };
}
