import type { Equipment, ItemSet, ItemSetBonus, ItemStats } from '../types';
import { ITEM_SETS } from '../constants/itemSets';

const SLOTS: (keyof Equipment)[] = ['weapon', 'armor', 'helmet', 'boots', 'accessory'];

/** 한 세트의 장착 아이템 수를 센다. */
export function countEquippedSetPieces(equipment: Equipment, set: ItemSet): number {
  let count = 0;
  for (const slot of SLOTS) {
    const item = equipment[slot];
    if (item && set.items.includes(item.id)) count++;
  }
  return count;
}

/**
 * 현재 장비 구성에서 활성된 모든 세트 보너스 단계를 반환.
 * UI 표시 및 스탯 계산에 모두 사용 가능.
 */
export function getActiveSetBonuses(equipment: Equipment): Array<{ set: ItemSet; bonus: ItemSetBonus; equippedCount: number }> {
  const result: Array<{ set: ItemSet; bonus: ItemSetBonus; equippedCount: number }> = [];
  for (const set of Object.values(ITEM_SETS)) {
    const equippedCount = countEquippedSetPieces(equipment, set);
    if (equippedCount === 0) continue;
    for (const bonus of set.bonuses) {
      if (equippedCount >= bonus.pieces) {
        result.push({ set, bonus, equippedCount });
      }
    }
  }
  return result;
}

/**
 * 활성 세트 보너스의 stat/crit 합을 반환.
 * calculateDerivedStats가 호출하여 장비 스탯 위에 합산한다.
 */
export function calculateSetBonusStats(equipment: Equipment): {
  attack: number;
  defense: number;
  magic: number;
  speed: number;
  maxHp: number;
  maxMp: number;
  critChance: number;
} {
  const acc = { attack: 0, defense: 0, magic: 0, speed: 0, maxHp: 0, maxMp: 0, critChance: 0 };
  for (const { bonus } of getActiveSetBonuses(equipment)) {
    if (bonus.stats) {
      acc.attack += bonus.stats.attack || 0;
      acc.defense += bonus.stats.defense || 0;
      acc.magic += bonus.stats.magic || 0;
      acc.speed += bonus.stats.speed || 0;
      acc.maxHp += bonus.stats.maxHp || 0;
      acc.maxMp += bonus.stats.maxMp || 0;
    }
    if (bonus.critChance) acc.critChance += bonus.critChance;
  }
  return acc;
}

/**
 * UI용: 한 세트가 현재 장비 기준으로 어떤 단계까지 활성됐는지 + 다음 단계까지 몇 개 필요한지.
 * InventoryModal에서 호버나 별도 영역에 표시 가능.
 */
export function getSetActivationSummary(equipment: Equipment, set: ItemSet): {
  equippedCount: number;
  activeBonuses: ItemSetBonus[];
  nextBonus: ItemSetBonus | null;
} {
  const equippedCount = countEquippedSetPieces(equipment, set);
  const activeBonuses = set.bonuses.filter((b) => equippedCount >= b.pieces);
  const nextBonus = set.bonuses.find((b) => equippedCount < b.pieces) ?? null;
  return { equippedCount, activeBonuses, nextBonus };
}

/** 한 아이템이 어떤 세트에 속하는지 (없으면 null). 같은 id가 여러 세트엔 들어가지 않는다고 가정. */
export function findSetForItem(itemId: string): ItemSet | null {
  for (const set of Object.values(ITEM_SETS)) {
    if (set.items.includes(itemId)) return set;
  }
  return null;
}

// Re-export ItemStats type for callers that need to construct test bonuses.
export type { ItemStats };
