import { STAT_CONFIG } from '../constants/config';
import { REGIONS } from '../constants/regions';
import { calculateSetBonusStats } from './itemSets';
import type { Equipment, InventoryItem } from '../types';

/** STR/AGI/INT + 장비 스탯(베이스 + 롤된 affix) 으로 파생 스탯 계산 */
export function calculateDerivedStats(
  str: number,
  agi: number,
  int: number,
  equipment: Equipment,
) {
  const eqStats = getEquipmentStats(equipment);

  return {
    attack: STAT_CONFIG.BASE_ATTACK + str * STAT_CONFIG.STR_TO_ATTACK + eqStats.attack,
    defense: STAT_CONFIG.BASE_DEFENSE + str * STAT_CONFIG.STR_TO_DEFENSE + eqStats.defense,
    magic: STAT_CONFIG.BASE_MAGIC + int * STAT_CONFIG.INT_TO_MAGIC + eqStats.magic,
    speed: STAT_CONFIG.BASE_SPEED + agi * STAT_CONFIG.AGI_TO_SPEED + eqStats.speed,
    critChance: Math.min(
      STAT_CONFIG.MAX_CRIT_CHANCE,
      STAT_CONFIG.BASE_CRIT_CHANCE + agi * STAT_CONFIG.AGI_TO_CRIT + eqStats.critChance,
    ),
    critDamage: STAT_CONFIG.BASE_CRIT_DAMAGE,
    maxWeight: STAT_CONFIG.BASE_CARRY_WEIGHT + str * STAT_CONFIG.STR_TO_WEIGHT,
    maxHpBonus: eqStats.maxHp,
    maxMpBonus: eqStats.maxMp,
  };
}

/** 장착된 장비 5슬롯의 베이스 스탯 + 롤된 affix + 활성 세트 보너스를 합산. */
function getEquipmentStats(equipment: Equipment) {
  const stats = { attack: 0, defense: 0, magic: 0, speed: 0, maxHp: 0, maxMp: 0, critChance: 0 };
  const slots: (keyof Equipment)[] = ['weapon', 'armor', 'helmet', 'boots', 'accessory'];
  for (const slot of slots) {
    const item = equipment[slot];
    if (!item) continue;
    if (item.stats) {
      stats.attack += item.stats.attack || 0;
      stats.defense += item.stats.defense || 0;
      stats.magic += item.stats.magic || 0;
      stats.speed += item.stats.speed || 0;
      stats.maxHp += item.stats.maxHp || 0;
      stats.maxMp += item.stats.maxMp || 0;
    }
    if (item.rolledAffixes) {
      for (const aff of item.rolledAffixes) {
        if (aff.type === 'attack') stats.attack += aff.value;
        else if (aff.type === 'defense') stats.defense += aff.value;
        else if (aff.type === 'magic') stats.magic += aff.value;
        else if (aff.type === 'speed') stats.speed += aff.value;
        else if (aff.type === 'maxHp') stats.maxHp += aff.value;
        else if (aff.type === 'maxMp') stats.maxMp += aff.value;
        else if (aff.type === 'critChance') stats.critChance += aff.value;
      }
    }
  }

  // 활성 세트 보너스 합산
  const setBonus = calculateSetBonusStats(equipment);
  stats.attack += setBonus.attack;
  stats.defense += setBonus.defense;
  stats.magic += setBonus.magic;
  stats.speed += setBonus.speed;
  stats.maxHp += setBonus.maxHp;
  stats.maxMp += setBonus.maxMp;
  stats.critChance += setBonus.critChance;

  return stats;
}

/** 두 지역 간 여행 시간 계산 (좌표 거리 기반, AGI로 최대 50% 단축) */
export function calculateTravelTime(
  fromCoords: [number, number],
  toCoords: [number, number],
  agi: number,
): number {
  const dx = toCoords[0] - fromCoords[0];
  const dy = toCoords[1] - fromCoords[1];
  const distance = Math.sqrt(dx * dx + dy * dy);

  // Normalize distance to 0-1 range (max possible distance in Europe ~50 units)
  const normalized = Math.min(distance / 50, 1);

  const baseTime = STAT_CONFIG.MIN_TRAVEL_TIME_MS +
    normalized * (STAT_CONFIG.MAX_TRAVEL_TIME_MS - STAT_CONFIG.MIN_TRAVEL_TIME_MS);

  const reduction = 1 - Math.min(agi * STAT_CONFIG.AGI_TRAVEL_REDUCTION, 0.5);
  return Math.max(STAT_CONFIG.MIN_TRAVEL_TIME_MS, Math.floor(baseTime * reduction));
}

/** 식량 소모율 계산 (INT로 최대 50% 절감) */
export function calculateFoodConsumption(int: number): number {
  const reduction = 1 - Math.min(int * STAT_CONFIG.INT_FOOD_REDUCTION, 0.5);
  return STAT_CONFIG.BASE_FOOD_CONSUMPTION * reduction;
}

/** 최대 용병 수 계산 (기본 1 + 레벨/3마다 +1) */
export function calculateMaxMercenaries(level: number): number {
  return STAT_CONFIG.BASE_MAX_MERCENARIES + Math.floor(level / STAT_CONFIG.LEVEL_PER_EXTRA_MERC);
}

/** 인벤토리 전체 무게 합산 */
export function calculateInventoryWeight(inventory: InventoryItem[]): number {
  return inventory.reduce((total, item) => total + (item.weight || 0), 0);
}

/** 두 지역 간 직선 거리 계산 (좌표계 단위, 무역 가격에 사용) */
export function getRegionDistance(fromRegion: string, toRegion: string): number {
  const from = REGIONS[fromRegion];
  const to = REGIONS[toRegion];
  if (!from || !to) return 0;
  const dx = to.coordinates[0] - from.coordinates[0];
  const dy = to.coordinates[1] - from.coordinates[1];
  return Math.sqrt(dx * dx + dy * dy);
}
