import { useState } from 'react';
import { GAME_STATES } from '../constants/config';
import { useNgPlusLevel } from '../stores/useWorldStore';
import type { Player, Region, GameState } from '../types';

interface HUDProps {
  player: Player;
  region: Region | undefined;
  gameState: GameState;
  dungeonLevel: number;
  onAllocateStat?: (stat: 'str' | 'agi' | 'int') => void;
}

export default function HUD({ player, region, gameState, dungeonLevel, onAllocateStat }: HUDProps) {
  const ngPlusLevel = useNgPlusLevel();
  const [collapsed, setCollapsed] = useState(false);

  const hpPercent = (player.hp / player.maxHp) * 100;
  const mpPercent = (player.mp / player.maxMp) * 100;

  if (collapsed) {
    return (
      <div className="absolute top-2 left-2 panel-parchment rounded-md px-2.5 py-1.5 text-age-paper text-xs flex items-center gap-2.5 animate-fade-in">
        <span className="text-age-gold font-bold">{player.name} Lv.{player.level}</span>
        <MiniBar icon={'❤️'} color="bg-age-blood" percent={hpPercent} iconColor="text-age-blood" />
        <MiniBar icon={'💧'} color="bg-age-sea" percent={mpPercent} iconColor="text-age-sea" />
        <span className="text-age-gold">{'💰'}{player.gold}</span>
        <span className="text-age-leaf">{'🍞'}{Math.floor(player.food)}</span>
        <button onClick={() => setCollapsed(false)} className="text-age-paper/60 hover:text-age-gold ml-0.5 transition-colors">{'▼'}</button>
      </div>
    );
  }

  return (
    <div className="absolute top-2 left-2 panel-parchment rounded-md p-3 text-age-paper text-sm max-w-[270px] animate-fade-in">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <span className="text-age-gold font-bold">{player.name} Lv.{player.level}</span>
          {ngPlusLevel > 0 && (
            <span className="text-age-amber text-[10px] font-bold px-1.5 py-0.5 rounded border border-age-amber/60 bg-age-amber/10">
              NG+{ngPlusLevel}
            </span>
          )}
          <span className="text-age-amber text-[11px]">{region?.name}</span>
          <span className="text-age-paper/60 text-[11px]">
            {gameState === GAME_STATES.TOWN ? '🏘️' : `⚔️ ${dungeonLevel}층`}
          </span>
        </div>
        <button onClick={() => setCollapsed(true)} className="text-age-paper/60 hover:text-age-gold text-xs transition-colors">{'▲'}</button>
      </div>

      <Bar icon={'❤️'} color="bg-age-blood" percent={hpPercent} label={`${Math.floor(player.hp)}/${player.maxHp}`} />
      <Bar icon={'💧'} color="bg-age-sea" percent={mpPercent} label={`${Math.floor(player.mp)}/${player.maxMp}`} />
      <Bar icon={'⭐'} color="bg-purple-500" percent={(player.exp / player.expToLevel) * 100} label={`${player.exp}/${player.expToLevel}`} small />

      <div className="flex gap-3 mt-2 mb-2 text-xs">
        <span className="text-age-gold">{'💰'} {player.gold}</span>
        <span className="text-age-leaf">{'🍞'} {Math.floor(player.food)}</span>
        <span className="text-age-paper/70">{'⚖️'} {Math.floor(player.currentWeight)}/{player.maxWeight}</span>
      </div>

      <div className="flex gap-2 text-[10px] mb-1">
        <span className="text-rarity-common" style={{ color: '#e89c8c' }}>STR {player.str}</span>
        <span style={{ color: '#9de09a' }}>AGI {player.agi}</span>
        <span style={{ color: '#8cc8e8' }}>INT {player.int}</span>
      </div>

      <div className="text-[10px] text-age-paper/60">
        {'⚔️'}{player.attack} {'🛡️'}{player.defense} {'✨'}{player.magic} {'💨'}{player.speed.toFixed(1)} <span className="text-age-amber">{'✦'}{(player.critChance * 100).toFixed(0)}%</span>
      </div>

      {player.statPoints > 0 && onAllocateStat && (
        <div className="mt-2 pt-2 border-t border-age-gold/30">
          <div className="text-age-gold text-xs mb-1.5 animate-pulse">{'⭐'} 스탯 포인트: {player.statPoints}</div>
          <div className="flex gap-1">
            <button onClick={() => onAllocateStat('str')}
              className="flex-1 px-1 py-1 bg-age-blood/70 hover:bg-age-blood text-white text-[10px] rounded transition-colors font-bold">STR+</button>
            <button onClick={() => onAllocateStat('agi')}
              className="flex-1 px-1 py-1 bg-age-leaf/70 hover:bg-age-leaf text-white text-[10px] rounded transition-colors font-bold">AGI+</button>
            <button onClick={() => onAllocateStat('int')}
              className="flex-1 px-1 py-1 bg-age-sea/70 hover:bg-age-sea text-white text-[10px] rounded transition-colors font-bold">INT+</button>
          </div>
        </div>
      )}
    </div>
  );
}

function Bar({ icon, color, percent, label, small }: { icon: string; color: string; percent: number; label: string; small?: boolean }) {
  return (
    <div className="flex items-center gap-1.5 mb-1">
      <span className="w-4 text-xs">{icon}</span>
      <div className={`w-32 ${small ? 'h-2' : 'h-3'} bg-age-navy/80 rounded-sm overflow-hidden border border-age-gold/20`}>
        <div className={`h-full ${color} transition-all`} style={{ width: `${percent}%` }} />
      </div>
      <span className="text-[10px] w-16 text-right text-age-paper/80">{label}</span>
    </div>
  );
}

function MiniBar({ icon, color, percent, iconColor }: { icon: string; color: string; percent: number; iconColor: string }) {
  return (
    <div className="flex items-center gap-1">
      <span className={`text-xs ${iconColor}`}>{icon}</span>
      <div className="w-12 h-2 bg-age-navy/80 rounded-sm overflow-hidden border border-age-gold/20">
        <div className={`h-full ${color} transition-all`} style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
