import { create } from 'zustand';
import type { QuestProgress } from '../types';
import { QUESTS } from '../constants/quests';
import { QUEST_STATUS } from '../constants/config';

/**
 * 퀘스트 진행 상태(상태 + 카운트)를 보관하는 store.
 * 게임 시작 시 모든 퀘스트를 AVAILABLE/0으로 초기화한다.
 */

export function createInitialQuestProgress(): Record<string, QuestProgress> {
  const progress: Record<string, QuestProgress> = {};
  Object.keys(QUESTS).forEach((id) => {
    progress[id] = { status: QUEST_STATUS.AVAILABLE, currentCount: 0 };
  });
  return progress;
}

interface QuestStore {
  questProgress: Record<string, QuestProgress>;
}

export const useQuestStore = create<QuestStore>(() => ({
  questProgress: createInitialQuestProgress(),
}));

type SetArg =
  | Record<string, QuestProgress>
  | ((prev: Record<string, QuestProgress>) => Record<string, QuestProgress>);

export const setQuestProgress = (arg: SetArg): void => {
  useQuestStore.setState((state) => ({
    questProgress: typeof arg === 'function' ? arg(state.questProgress) : arg,
  }));
};

export const resetQuestProgress = (): void => {
  useQuestStore.setState({ questProgress: createInitialQuestProgress() });
};

export const useQuestProgress = () => useQuestStore((s) => s.questProgress);
