import type { Player, InventoryItem, Equipment, QuestProgress, SaveData, Mercenary, SaveSlotId } from '../types';

/** Save format version (bumped when incompatible changes ship) */
const SAVE_VERSION = 3;

const SLOT_STORAGE_PREFIX = 'bc_save_';
const SLOT_IDS: SaveSlotId[] = ['slot1', 'slot2', 'slot3', 'auto'];

export function createSaveData(
  player: Player,
  inventory: InventoryItem[],
  equipment: Equipment,
  questProgress: Record<string, QuestProgress>,
  currentRegion: string,
  dungeonLevel: number,
  unlockedRegions: string[],
  selectedSkill: string,
  mercenaries: Mercenary[],
  clearedSubRegions: string[],
  achievements: string[] = [],
  playTimeMs = 0,
  thumbnail?: string,
  ngPlusLevel = 0,
): SaveData {
  const { x: _x, y: _y, targetX: _tx, targetY: _ty, ...playerData } = player;
  return {
    version: SAVE_VERSION,
    timestamp: Date.now(),
    player: playerData,
    inventory,
    equipment,
    questProgress,
    currentRegion,
    dungeonLevel,
    unlockedRegions,
    selectedSkill,
    mercenaries,
    clearedSubRegions,
    achievements,
    playTimeMs,
    ngPlusLevel,
    thumbnail,
  };
}

export function isValidSaveData(data: unknown): data is SaveData {
  if (!data || typeof data !== 'object') return false;
  const d = data as Record<string, unknown>;
  return (
    typeof d.version === 'number' &&
    typeof d.timestamp === 'number' &&
    d.player != null &&
    Array.isArray(d.inventory) &&
    d.equipment != null &&
    d.questProgress != null &&
    typeof d.currentRegion === 'string' &&
    typeof d.dungeonLevel === 'number' &&
    Array.isArray(d.unlockedRegions) &&
    typeof d.selectedSkill === 'string'
  );
}

/**
 * v1 또는 v2 세이브를 v3로 마이그레이션.
 * - v1 → v2: 1차 스탯(str/agi/int), 이름, 식량 등 누락 보강
 * - v2 → v3: ngPlusLevel = 0 기본값 채움
 * 이름은 호환을 위해 migrateV1toV2 유지.
 */
export function migrateV1toV2(data: SaveData): SaveData {
  // v1 -> v2: backfill primary stats and other v2-only fields
  if (data.version < 2) {
    const player = data.player as Record<string, unknown>;
    if (player.str === undefined) player.str = 3;
    if (player.agi === undefined) player.agi = 3;
    if (player.int === undefined) player.int = 3;
    if (player.statPoints === undefined) player.statPoints = 0;
    if (player.name === undefined) player.name = '선장';
    if (player.homeRegion === undefined) player.homeRegion = 'portugal';
    if (player.food === undefined) player.food = 20;
    if (player.maxWeight === undefined) player.maxWeight = 80;
    if (player.currentWeight === undefined) player.currentWeight = 0;
    if (player.critChance === undefined) player.critChance = 0.05 + (typeof player.agi === 'number' ? player.agi * 0.008 : 0);
    if (player.critDamage === undefined) player.critDamage = 1.5;
    if (!player.skillMastery || typeof player.skillMastery !== 'object') player.skillMastery = {};
    if (!data.mercenaries) data.mercenaries = [];
    if (!data.clearedSubRegions) data.clearedSubRegions = [];
    if (!data.achievements) data.achievements = [];
    if (data.playTimeMs === undefined) data.playTimeMs = 0;
    data.version = 2;
  }

  // v2 hardening (idempotent — applied to v2 saves and to freshly upgraded v1 saves)
  if (!data.achievements) data.achievements = [];
  if (data.playTimeMs === undefined) data.playTimeMs = 0;
  const p = data.player as Record<string, unknown>;
  if (p.critChance === undefined) p.critChance = 0.05 + (typeof p.agi === 'number' ? p.agi * 0.008 : 0);
  if (p.critDamage === undefined) p.critDamage = 1.5;
  if (!p.skillMastery || typeof p.skillMastery !== 'object') p.skillMastery = {};

  // v2 -> v3: NG+ default
  if (data.version < 3) {
    if (data.ngPlusLevel === undefined) data.ngPlusLevel = 0;
    data.version = 3;
  }

  return data;
}

function isElectron(): boolean {
  return !!window.electronAPI;
}

/** Save to a specific slot in localStorage (used by autosave and manual slot saves). */
export function saveToSlot(slotId: SaveSlotId, saveData: SaveData): boolean {
  try {
    localStorage.setItem(SLOT_STORAGE_PREFIX + slotId, JSON.stringify(saveData));
    return true;
  } catch {
    return false;
  }
}

/** Load from a specific slot. Returns null if empty or invalid. */
export function loadFromSlot(slotId: SaveSlotId): SaveData | null {
  try {
    const raw = localStorage.getItem(SLOT_STORAGE_PREFIX + slotId);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!isValidSaveData(data)) return null;
    return migrateV1toV2(data);
  } catch {
    return null;
  }
}

/** Return all 4 slots in order with their data (data=null if empty). */
export function listSlots(): { id: SaveSlotId; data: SaveData | null }[] {
  return SLOT_IDS.map(id => ({ id, data: loadFromSlot(id) }));
}

export function deleteSlot(slotId: SaveSlotId): void {
  try {
    localStorage.removeItem(SLOT_STORAGE_PREFIX + slotId);
  } catch {
    /* noop */
  }
}

/** Export save as JSON file (Electron IPC or browser download). */
export async function saveGame(saveData: SaveData): Promise<boolean> {
  if (isElectron()) {
    const result = await window.electronAPI!.saveGame(saveData);
    return result.success;
  }
  const json = JSON.stringify(saveData, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `broken_compass_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
  return true;
}

/** Import save from JSON file. */
export async function loadGame(): Promise<SaveData | null> {
  if (isElectron()) {
    const result = await window.electronAPI!.loadGame();
    if (!result.success || !result.data) return null;
    if (!isValidSaveData(result.data)) return null;
    return migrateV1toV2(result.data);
  }

  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) { resolve(null); return; }
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const data = JSON.parse(reader.result as string);
          if (!isValidSaveData(data)) { resolve(null); return; }
          resolve(migrateV1toV2(data));
        } catch {
          resolve(null);
        }
      };
      reader.readAsText(file);
    };
    input.oncancel = () => resolve(null);
    input.click();
  });
}
