import { GAME_CONFIG, TILE_TYPES } from '../constants/config';
import { MONSTERS, BOSSES, REGION_SPAWNS } from '../constants/monsters';
import { SUB_REGIONS } from '../constants/subRegions';
import { ITEMS } from '../constants/items';
import { rollAffixes } from './affixes';
import { rollEliteAffixes, applySpawnTimeAffixEffects } from './eliteAffixes';
import type { Monster, SpawnedMonster, DroppedItem, Item, TileMap } from '../types';

/** 장비 아이템에 등급/레벨 기반 affix를 롤해 새 객체로 반환. 비장비는 그대로 반환. */
function withRolledAffixes(item: Item, level: number): Item {
  if (item.type !== 'equipment') return item;
  return { ...item, rolledAffixes: rollAffixes(item.rarity, level) };
}

/**
 * NG+ 차수당 곱: HP/공격은 ×1.5, 경험치/골드는 ×2.0.
 * ngPlus = 0이면 1.0 (효과 없음).
 */
export const NG_PLUS_HP_ATK_MULT = 1.5;
export const NG_PLUS_REWARD_MULT = 2.0;

/** 몬스터를 던전 레벨 + NG+ 차수에 맞춰 스케일링.
 *  - 던전 레벨당 +12% HP/공격/경험치/골드 (누적)
 *  - NG+ 차수당 HP/공격 ×1.5^n, 경험치/골드 ×2.0^n
 */
export const scaleMonster = (monster: Monster, level: number, ngPlus = 0) => {
  const levelMult = 1 + (level - 1) * 0.12;
  const ngHpAtkMult = Math.pow(NG_PLUS_HP_ATK_MULT, ngPlus);
  const ngRewardMult = Math.pow(NG_PLUS_REWARD_MULT, ngPlus);
  return {
    ...monster,
    hp: Math.floor(monster.hp * levelMult * ngHpAtkMult),
    maxHp: Math.floor(monster.hp * levelMult * ngHpAtkMult),
    attack: Math.floor(monster.attack * levelMult * ngHpAtkMult),
    exp: Math.floor(monster.exp * levelMult * ngRewardMult),
    gold: Math.floor(monster.gold * levelMult * ngRewardMult),
  };
};

/** 던전에 몬스터 스폰 - subRegion이 있으면 해당 풀 사용, 없으면 지역 기본 풀 */
export const spawnMonsters = (regionId: string, dungeonLevel: number, subRegionId?: string, ngPlus = 0): SpawnedMonster[] => {
  let monsterPool: string[];
  let count: number;

  if (subRegionId && SUB_REGIONS[subRegionId]) {
    const sub = SUB_REGIONS[subRegionId];
    monsterPool = sub.monsters;
    count = sub.monsterCount + dungeonLevel;
  } else {
    const spawn = REGION_SPAWNS[regionId] || REGION_SPAWNS.portugal;
    monsterPool = spawn.monsters;
    count = spawn.count + dungeonLevel;
  }

  return Array(count).fill(null).map((_, i) => {
    const type = monsterPool[Math.floor(Math.random() * monsterPool.length)];
    const base = MONSTERS[type];
    const scaled = scaleMonster(base, dungeonLevel, ngPlus);
    // 엘리트 변종: Lv.3+ 던전부터 15% 확률
    const isElite = dungeonLevel >= 3 && Math.random() < 0.15;
    let eliteAffixes: ReturnType<typeof rollEliteAffixes> | undefined;

    // Base elite scaling (kept for backwards compatibility — applied first)
    let working = {
      attack: isElite ? Math.floor(scaled.attack * 1.5) : scaled.attack,
      defense: scaled.defense,
      speed: scaled.speed,
      hp: isElite ? Math.floor(scaled.hp * 1.5) : scaled.hp,
      maxHp: isElite ? Math.floor(scaled.hp * 1.5) : scaled.hp,
      exp: isElite ? Math.floor(scaled.exp * 1.8) : scaled.exp,
      gold: isElite ? Math.floor(scaled.gold * 2) : scaled.gold,
    };

    // Roll affixes for elites and apply spawn-time effects (swift/tank).
    // regen/explosive are runtime-only and just live on eliteAffixes.
    if (isElite) {
      eliteAffixes = rollEliteAffixes(dungeonLevel);
      working = applySpawnTimeAffixEffects(working, eliteAffixes);
    }

    return {
      ...scaled,
      hp: working.maxHp,
      maxHp: working.maxHp,
      attack: working.attack,
      defense: working.defense,
      speed: working.speed,
      exp: working.exp,
      gold: working.gold,
      dropChance: isElite ? Math.min(0.95, (scaled.dropChance || 0.3) * 1.5) : scaled.dropChance,
      size: isElite ? scaled.size * 1.2 : scaled.size,
      uid: `m_${Date.now()}_${i}`,
      x: 200 + Math.random() * (GAME_CONFIG.MAP_WIDTH * GAME_CONFIG.TILE_SIZE - 400),
      y: 100 + Math.random() * (GAME_CONFIG.MAP_HEIGHT * GAME_CONFIG.TILE_SIZE - 200),
      currentHp: working.maxHp,
      lastAttack: 0,
      isElite,
      eliteAffixes,
    };
  });
};

/** 지역 보스 스폰 - 맵 중앙 상단에 배치, isBoss 플래그 + 페이즈 추적 초기화 */
export const spawnBoss = (regionId: string, dungeonLevel: number, ngPlus = 0): SpawnedMonster | null => {
  const base = BOSSES[regionId];
  if (!base) return null;
  const scaled = scaleMonster(base as unknown as Monster, dungeonLevel, ngPlus);
  return {
    ...scaled,
    uid: `boss_${Date.now()}`,
    x: GAME_CONFIG.MAP_WIDTH * GAME_CONFIG.TILE_SIZE / 2,
    y: GAME_CONFIG.MAP_HEIGHT * GAME_CONFIG.TILE_SIZE / 3,
    currentHp: scaled.maxHp,
    lastAttack: 0,
    isBoss: true,
    phases: base.phases,
    activatedPhases: [],
  };
};

/** 몬스터 처치 시 드롭 아이템 생성 - 골드 + 재료/소모품 + 보스 EPIC/LEGENDARY 보장 */
export const generateDrop = (monster: SpawnedMonster, level: number): DroppedItem[] => {
  const drops: DroppedItem[] = [];
  if (monster.gold) {
    drops.push({
      uid: `g_${Date.now()}_${Math.random()}`,
      type: 'gold',
      amount: monster.gold + Math.floor(Math.random() * 15),
      x: monster.x,
      y: monster.y,
      icon: '💰',
    });
  }
  if (Math.random() < (monster.dropChance || 0.3)) {
    const itemKeys = Object.keys(ITEMS).filter(k => ITEMS[k].type === 'material' || ITEMS[k].type === 'consumable');
    const randomItem = ITEMS[itemKeys[Math.floor(Math.random() * itemKeys.length)]];
    if (randomItem) {
      drops.push({
        ...withRolledAffixes(randomItem, level),
        uid: `i_${Date.now()}_${Math.random()}`,
        x: monster.x + (Math.random() - 0.5) * 30,
        y: monster.y + (Math.random() - 0.5) * 30,
      });
    }
  }

  // Legendary drops: only from bosses (EPIC/LEGENDARY guaranteed)
  if (monster.isBoss) {
    const epicItems = Object.values(ITEMS).filter(i => i.rarity === 'EPIC' || i.rarity === 'LEGENDARY');
    if (epicItems.length > 0) {
      const bossItem = epicItems[Math.floor(Math.random() * epicItems.length)];
      drops.push({
        ...withRolledAffixes(bossItem, level),
        uid: `bi_${Date.now()}`,
        x: monster.x,
        y: monster.y + 40,
      });
    }
  }

  // Small chance for legendary from regular dungeon monsters
  if (!monster.isBoss) {
    const eliteBonus = monster.isElite ? 3 : 1;
    const legendaryChance = 0.02 * level * eliteBonus;
    if (Math.random() < legendaryChance) {
      const legendaryItems = Object.values(ITEMS).filter(i => i.rarity === 'LEGENDARY' && i.type === 'equipment');
      if (legendaryItems.length > 0) {
        const item = legendaryItems[Math.floor(Math.random() * legendaryItems.length)];
        drops.push({
          ...withRolledAffixes(item, level),
          uid: `li_${Date.now()}`,
          x: monster.x + (Math.random() - 0.5) * 20,
          y: monster.y + (Math.random() - 0.5) * 20,
        });
      }
    }
  }

  return drops;
};

/**
 * 던전에 상자 1~3개 배치. 바닥 타일 중 임의 위치에 스폰.
 */
export const spawnChests = (map: TileMap, dungeonLevel: number): DroppedItem[] => {
  const floorTiles: Array<[number, number]> = [];
  for (let y = 2; y < GAME_CONFIG.MAP_HEIGHT - 2; y++) {
    for (let x = 4; x < GAME_CONFIG.MAP_WIDTH - 2; x++) {
      if (map[y]?.[x] === TILE_TYPES.FLOOR) floorTiles.push([x, y]);
    }
  }
  if (floorTiles.length === 0) return [];

  const count = 1 + Math.floor(Math.random() * 3); // 1~3
  const chests: DroppedItem[] = [];
  for (let i = 0; i < count; i++) {
    const [tx, ty] = floorTiles[Math.floor(Math.random() * floorTiles.length)];
    chests.push({
      uid: `chest_${Date.now()}_${i}_${Math.random()}`,
      type: 'chest',
      x: tx * GAME_CONFIG.TILE_SIZE + GAME_CONFIG.TILE_SIZE / 2,
      y: ty * GAME_CONFIG.TILE_SIZE + GAME_CONFIG.TILE_SIZE / 2,
      icon: '📦',
      name: '보물 상자',
      rarity: 'LEGENDARY',
      amount: dungeonLevel,
    });
  }
  return chests;
};

/**
 * 상자를 열었을 때 드롭할 전리품 생성. 골드 + 1~2개 아이템 + 소량 경험치.
 */
export const generateChestLoot = (chest: DroppedItem, dungeonLevel: number): { drops: DroppedItem[]; gold: number; exp: number } => {
  const gold = 50 + dungeonLevel * 30 + Math.floor(Math.random() * 40);
  const exp = 20 + dungeonLevel * 15;
  const drops: DroppedItem[] = [];

  // Weighted rarity roll — higher dungeon level = more epic/legendary
  const rarityRoll = Math.random();
  let pool: string[];
  if (rarityRoll < 0.02 + dungeonLevel * 0.01) {
    pool = Object.keys(ITEMS).filter(k => ITEMS[k].rarity === 'LEGENDARY');
  } else if (rarityRoll < 0.1 + dungeonLevel * 0.02) {
    pool = Object.keys(ITEMS).filter(k => ITEMS[k].rarity === 'EPIC');
  } else if (rarityRoll < 0.3 + dungeonLevel * 0.02) {
    pool = Object.keys(ITEMS).filter(k => ITEMS[k].rarity === 'RARE');
  } else {
    pool = Object.keys(ITEMS).filter(k => ITEMS[k].rarity === 'UNCOMMON' || ITEMS[k].rarity === 'COMMON');
  }

  if (pool.length > 0) {
    const itemCount = 1 + (Math.random() < 0.4 ? 1 : 0);
    for (let i = 0; i < itemCount; i++) {
      const item = ITEMS[pool[Math.floor(Math.random() * pool.length)]];
      if (!item) continue;
      drops.push({
        ...withRolledAffixes(item, dungeonLevel),
        uid: `chest_loot_${Date.now()}_${i}_${Math.random()}`,
        x: chest.x + (Math.random() - 0.5) * 40,
        y: chest.y + (Math.random() - 0.5) * 40,
      });
    }
  }

  return { drops, gold, exp };
};
