/**
 * 죽음 파티클 - 모듈 레벨 싱글톤. spawnBurst 로 등록하고
 * <ParticleField /> 컴포넌트가 useFrame 으로 매 프레임 업데이트.
 * React state 를 거치지 않아 60fps 에서도 비용이 거의 없음.
 */

export interface Particle {
  x: number; y: number;
  vx: number; vy: number; vz: number;
  life: number;     // remaining ms
  maxLife: number;
  color: string;
  scale: number;
}

const MAX_PARTICLES = 200;

const state: { particles: Particle[] } = { particles: [] };

import { getGraphicsSettings } from '../utils/graphicsSettings';

/**
 * 픽셀 좌표에 8개 입자 폭발. 색상은 몬스터/이벤트별로 다르게.
 */
export function spawnBurst(x: number, y: number, color: string, count = 8) {
  if (!getGraphicsSettings().particles) return;
  if (state.particles.length > MAX_PARTICLES) return;
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2 + Math.random() * 0.5;
    const speed = 25 + Math.random() * 35; // pixels/sec
    state.particles.push({
      x, y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      vz: 30 + Math.random() * 40,    // upward initial
      life: 600,
      maxLife: 600,
      color,
      scale: 0.3 + Math.random() * 0.3,
    });
  }
}

/**
 * 매 프레임 호출. dtMs 만큼 입자 위치/수명 갱신, 만료된 것 제거.
 * 중력 가속도(픽셀/초²) 모방.
 */
export function tickParticles(dtMs: number) {
  if (state.particles.length === 0) return;
  const dt = dtMs / 1000;
  const remaining: Particle[] = [];
  for (const p of state.particles) {
    p.life -= dtMs;
    if (p.life <= 0) continue;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vz -= 120 * dt; // gravity
    remaining.push(p);
  }
  state.particles = remaining;
}

export function getParticles(): readonly Particle[] {
  return state.particles;
}

export function clearParticles() {
  state.particles = [];
}
