import type { TravelEncounter } from '../types';
import { STAT_CONFIG } from '../constants/config';

/** 조우 이벤트 템플릿 - 가중치 기반 랜덤 선택 (해적30/괴물20/난파선20/보물20/상인10) */
const ENCOUNTER_TEMPLATES = [
  { type: 'pirate' as const, weight: 30, name: '해적 습격', icon: '🏴‍☠️' },
  { type: 'sea_monster' as const, weight: 20, name: '바다 괴물', icon: '🐙' },
  { type: 'shipwreck' as const, weight: 20, name: '난파선 발견', icon: '🚢' },
  { type: 'treasure' as const, weight: 20, name: '보물 발견', icon: '💰' },
  { type: 'merchant' as const, weight: 10, name: '떠돌이 상인', icon: '🧳' },
];

/** 가중치 기반 랜덤 조우 유형 선택 */
function pickEncounterType(): typeof ENCOUNTER_TEMPLATES[number] {
  const totalWeight = ENCOUNTER_TEMPLATES.reduce((s, t) => s + t.weight, 0);
  let roll = Math.random() * totalWeight;
  for (const t of ENCOUNTER_TEMPLATES) {
    roll -= t.weight;
    if (roll <= 0) return t;
  }
  return ENCOUNTER_TEMPLATES[0];
}

/** 항해 중 조우 이벤트 0~3개 생성 (여행 시간 비례, 진행률 15~85%에 배치) */
export function generateTravelEncounters(duration: number, level: number): TravelEncounter[] {
  // More encounters for longer journeys: 0-3 encounters
  const maxEncounters = Math.min(3, Math.floor(duration / 60000) + 1);
  const count = Math.floor(Math.random() * (maxEncounters + 1));

  const encounters: TravelEncounter[] = [];
  const usedPercents = new Set<number>();

  for (let i = 0; i < count; i++) {
    const template = pickEncounterType();
    let percent: number;
    do {
      percent = 15 + Math.floor(Math.random() * 70); // 15%~85%
    } while (usedPercents.has(percent));
    usedPercents.add(percent);

    const encounter: TravelEncounter = {
      type: template.type,
      triggeredAtPercent: percent,
      resolved: false,
      data: {
        name: template.name,
        icon: template.icon,
      },
    };

    if (template.type === 'pirate') {
      encounter.data.enemyPower = Math.floor(20 + level * 8 + Math.random() * 20);
      encounter.data.reward = {
        gold: Math.floor(30 + level * 10 + Math.random() * 50),
        exp: Math.floor(20 + level * 5),
      };
    } else if (template.type === 'sea_monster') {
      encounter.data.enemyPower = Math.floor(40 + level * 12 + Math.random() * 30);
      encounter.data.reward = {
        gold: Math.floor(50 + level * 15 + Math.random() * 80),
        exp: Math.floor(40 + level * 8),
        items: ['kraken_ink'],
      };
    } else if (template.type === 'shipwreck') {
      const materials = ['wood', 'iron', 'silk', 'gold_bar', 'ancient_stone', 'phoenix_ash'];
      const randomMat = materials[Math.floor(Math.random() * materials.length)];
      encounter.data.reward = {
        gold: Math.floor(20 + Math.random() * 40),
        items: [randomMat],
      };
    } else if (template.type === 'treasure') {
      encounter.data.reward = {
        gold: Math.floor(80 + level * 20 + Math.random() * 100),
        exp: Math.floor(30 + level * 5),
      };
    } else if (template.type === 'merchant') {
      encounter.data.shopItems = ['elixir', 'mana_crystal', 'captain_hat', 'spyglass', 'phoenix_feather', 'ankh_amulet'];
    }

    encounters.push(encounter);
  }

  // Sort by triggeredAtPercent
  encounters.sort((a, b) => a.triggeredAtPercent - b.triggeredAtPercent);
  return encounters;
}

/** 항해 전투 조우 승패 판정 - (플레이어 + 용병30%) vs 적, 최대 승률 90% */
export function resolveCombatEncounter(
  playerPower: number,
  mercenaryPower: number,
  enemyPower: number,
): boolean {
  const totalPower = playerPower + mercenaryPower * STAT_CONFIG.MERC_COMBAT_BONUS_PCT;
  const winChance = Math.min(0.9, totalPower / (totalPower + enemyPower));
  return Math.random() < winChance;
}
