import { useCallback, useRef } from 'react';
import type { Item, CraftingRecipe, AchievementTrigger, InventoryItem } from '../types';
import { GAME_CONFIG } from '../constants/config';
import { ITEMS } from '../constants/items';
import { calculateTradePrice } from '../utils/trade';
import { usePlayerStore, setPlayer } from '../stores/usePlayerStore';
import { useInventoryStore, setInventory } from '../stores/useInventoryStore';
import { useCurrentRegion } from '../stores/useWorldStore';

/**
 * 상점/제작 도메인 훅: 구매(아이템/식량) · 판매 · 제작.
 *
 * 무게/슬롯 한계 검사, 무역품 가격 계산, 업적 트리거를 캡슐화한다.
 */
export interface ShopHandlersHooks {
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
  unlockAchievement: (id: AchievementTrigger) => void;
  /** trade quest 진행도 갱신 — sellItem이 무역품을 팔 때 호출 */
  onTradeSold?: (itemId: string, destinationRegion: string) => void;
}

export function useShopHandlers(hooks: ShopHandlersHooks) {
  const currentRegion = useCurrentRegion();
  const hooksRef = useRef(hooks);
  hooksRef.current = hooks;

  const buyItem = useCallback(
    (item: Item) => {
      const player = usePlayerStore.getState().player;
      const inventory = useInventoryStore.getState().inventory;
      if (player.gold < item.price) return;
      if (inventory.length >= GAME_CONFIG.INVENTORY_MAX_SLOTS) return;
      if (player.currentWeight + item.weight > player.maxWeight) {
        hooksRef.current.addFloatingText(player.x, player.y, '무게 초과!', '#e74c3c');
        return;
      }
      setPlayer((p) => ({ ...p, gold: p.gold - item.price }));
      setInventory((inv) => [...inv, { ...item, uid: `inv_${Date.now()}` }]);
      hooksRef.current.addFloatingText(player.x, player.y, `${item.name} 구매!`, '#2ecc71');
    },
    [],
  );

  const buyFood = useCallback((item: Item) => {
    const player = usePlayerStore.getState().player;
    if (player.gold < item.price || !item.foodValue) return;
    setPlayer((p) => ({ ...p, gold: p.gold - item.price, food: p.food + item.foodValue! }));
    hooksRef.current.addFloatingText(player.x, player.y, `+${item.foodValue} 식량`, '#2ecc71');
  }, []);

  const sellItem = useCallback(
    (uid: string) => {
      const player = usePlayerStore.getState().player;
      const inventory = useInventoryStore.getState().inventory;
      const item = inventory.find((i) => i.uid === uid);
      if (!item) return;

      let sellPrice: number;
      if (item.type === 'trade_good') {
        sellPrice = calculateTradePrice(item, currentRegion);
        const buyPrice = item.tradeInfo?.basePrice || item.price;
        if (sellPrice > buyPrice) hooksRef.current.unlockAchievement('trade_profit');
        hooksRef.current.onTradeSold?.(item.id, currentRegion);
      } else {
        sellPrice = Math.floor(item.price * 0.5);
      }

      setPlayer((p) => ({ ...p, gold: p.gold + sellPrice }));
      setInventory((inv) => inv.filter((i) => i.uid !== uid));
      hooksRef.current.addFloatingText(player.x, player.y, `+${sellPrice}G`, '#ffd700');
    },
    [currentRegion],
  );

  const craftItem = useCallback((recipe: CraftingRecipe) => {
    const player = usePlayerStore.getState().player;
    const inventory = useInventoryStore.getState().inventory;
    const result = ITEMS[recipe.result];

    let canCraft = player.gold >= recipe.goldCost;
    for (const mat of recipe.materials) {
      if (inventory.filter((i) => i.id === mat.itemId).length < mat.count) canCraft = false;
    }
    if (!canCraft) return;

    if (result && player.currentWeight + result.weight > player.maxWeight) {
      hooksRef.current.addFloatingText(player.x, player.y, '무게 초과!', '#e74c3c');
      return;
    }

    setPlayer((p) => ({ ...p, gold: p.gold - recipe.goldCost }));

    // 재료 소모: 각 재료 종류별로 필요 수량만큼 제거
    setInventory((inv) => {
      const next: InventoryItem[] = [...inv];
      for (const mat of recipe.materials) {
        let removed = 0;
        for (let i = next.length - 1; i >= 0 && removed < mat.count; i--) {
          if (next[i].id === mat.itemId) {
            next.splice(i, 1);
            removed++;
          }
        }
      }
      if (result) next.push({ ...result, uid: `inv_${Date.now()}` });
      return next;
    });

    hooksRef.current.addFloatingText(player.x, player.y, `${result?.name} 제작!`, '#ff9800');
  }, []);

  return { buyItem, buyFood, sellItem, craftItem };
}
