import type { BossPhaseTrigger, SpawnedMonster } from '../types';

/**
 * 보스가 이번 프레임에 새로 진입한 페이즈들을 찾는다.
 *
 * 진입 조건: currentHp / maxHp * 100 ≤ phase.hpPercent && !activatedPhases.includes(i)
 *
 * 반환:
 *   - newPhaseIndices: 새로 진입한 페이즈의 인덱스 배열 (오름차순 정렬)
 *                       호출자가 각 페이즈의 triggers를 순서대로 적용해야 한다.
 */
export function findNewlyEnteredPhases(
  m: Pick<SpawnedMonster, 'currentHp' | 'maxHp' | 'phases' | 'activatedPhases'>,
): number[] {
  if (!m.phases || m.phases.length === 0) return [];
  const hpPct = (m.currentHp / m.maxHp) * 100;
  const activated = m.activatedPhases ?? [];
  const newly: number[] = [];
  for (let i = 0; i < m.phases.length; i++) {
    if (activated.includes(i)) continue;
    if (hpPct <= m.phases[i].hpPercent) newly.push(i);
  }
  return newly;
}

/** 한 페이즈의 모든 triggers를 보스에 누적 적용한 결과를 반환. 입력 mutation 없음. */
export function applyPhaseTriggers(
  boss: SpawnedMonster,
  triggers: BossPhaseTrigger[],
  playerDistance: number,
): { boss: SpawnedMonster; aoeDamageToPlayer: number } {
  let next = boss;
  let aoeDamageToPlayer = 0;

  for (const t of triggers) {
    switch (t.kind) {
      case 'enrage': {
        const attackMult = t.attackMult ?? 1;
        const speedMult = t.speedMult ?? 1;
        next = {
          ...next,
          attack: Math.floor(next.attack * attackMult),
          speed: next.speed * speedMult,
        };
        break;
      }
      case 'heal': {
        const healed = Math.min(next.maxHp, next.currentHp + t.amount);
        if (healed !== next.currentHp) next = { ...next, currentHp: healed };
        break;
      }
      case 'aoe': {
        if (playerDistance <= t.radius) aoeDamageToPlayer += t.damage;
        break;
      }
    }
  }

  return { boss: next, aoeDamageToPlayer };
}

/** 보스가 정의된 페이즈를 모두 활성화했는지 (모든 hpPercent threshold 통과). 디버깅용. */
export function allPhasesActivated(
  m: Pick<SpawnedMonster, 'phases' | 'activatedPhases'>,
): boolean {
  if (!m.phases || m.phases.length === 0) return true;
  const activated = m.activatedPhases ?? [];
  return m.phases.every((_, i) => activated.includes(i));
}

/** trigger 종류별 floating-text 라벨 */
export const PHASE_TRIGGER_LABELS: Record<BossPhaseTrigger['kind'], string> = {
  enrage: '⚔️ 분노!',
  aoe: '💥 광역 공격!',
  heal: '💚 재생!',
};
