import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import ko from './ko';
import en from './en';

/**
 * i18n 스캐폴딩 (Phase 5 #4).
 *
 * 기본 언어는 한국어. 영어 사전은 메뉴/설정 등 핵심 UI만 우선 채워졌고,
 * 게임 내 문자열(아이템명/몬스터명/스킬 설명 등) 전체 마이그레이션은
 * 점진적으로 진행할 예정. 현재 t()를 사용하지 않는 곳은 한글 하드코딩이
 * 그대로 유지되어 한국어 사용자에겐 회귀가 없다.
 *
 * 언어 선택은 localStorage('bc_lang')에 저장.
 */

const STORAGE_KEY = 'bc_lang';

function getInitialLang(): string {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'ko' || stored === 'en') return stored;
    // 브라우저 언어 감지 (en으로 시작하면 en, 그 외 ko)
    const nav = (navigator.language || 'ko').toLowerCase();
    return nav.startsWith('en') ? 'en' : 'ko';
  } catch {
    return 'ko';
  }
}

i18n
  .use(initReactI18next)
  .init({
    resources: {
      ko: { translation: ko },
      en: { translation: en },
    },
    lng: getInitialLang(),
    fallbackLng: 'ko',
    interpolation: { escapeValue: false },
  });

export function setLanguage(lang: 'ko' | 'en'): void {
  i18n.changeLanguage(lang);
  try { localStorage.setItem(STORAGE_KEY, lang); } catch { /* noop */ }
}

export function getLanguage(): 'ko' | 'en' {
  return (i18n.language === 'en' ? 'en' : 'ko');
}

export default i18n;
