import { MERCENARY_TEMPLATES, getMercenaryTypeName } from '../../constants/mercenaries';
import { calculateMaxMercenaries } from '../../utils/stats';
import type { Player, Mercenary, MercenaryType } from '../../types';
import { Panel, Button } from '../ui';

interface MercenaryModalProps {
  player: Player;
  mercenaries: Mercenary[];
  currentRegion: string;
  onHire: (type: MercenaryType) => void;
  onFire: (uid: string) => void;
  onClose: () => void;
}

export default function MercenaryModal({ player, mercenaries, onHire, onFire, onClose }: MercenaryModalProps) {
  const maxSlots = calculateMaxMercenaries(player.level);

  const headerExtra = (
    <>
      <span className="text-age-gold text-sm">{'💰'} {player.gold}G</span>
      <span className="text-age-paper/60 text-sm">{mercenaries.length}/{maxSlots} 슬롯</span>
    </>
  );

  return (
    <Panel title="용병 길드" icon={'⚔️'} onClose={onClose} headerExtra={headerExtra} maxWidth="min-w-[440px]">
      {mercenaries.length > 0 && (
        <div className="mb-4">
          <h3 className="text-age-amber text-sm mb-2">고용된 용병</h3>
          <div className="space-y-2">
            {mercenaries.map(merc => {
              const template = MERCENARY_TEMPLATES[merc.type];
              return (
                <div key={merc.uid} className="flex items-center gap-3 bg-age-navy/70 border border-age-gold/20 p-2 rounded">
                  <span className="text-2xl">{template.icon}</span>
                  <div className="flex-1">
                    <div className="text-age-paper text-sm">
                      {merc.name} <span className="text-age-paper/60">({getMercenaryTypeName(merc.type)})</span>
                    </div>
                    <div className="text-[10px] text-age-paper/60">
                      {'⚔️'}{merc.attack} {'🛡️'}{merc.defense} {'✨'}{merc.magic} | {'🍞'} 이동당 {merc.foodPerTravel}
                    </div>
                  </div>
                  <Button size="xs" variant="danger" onClick={() => onFire(merc.uid)}>해고</Button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div>
        <h3 className="text-age-amber text-sm mb-2">고용 가능한 용병</h3>
        <div className="space-y-2">
          {(Object.keys(MERCENARY_TEMPLATES) as MercenaryType[]).map(type => {
            const template = MERCENARY_TEMPLATES[type];
            const canHire = mercenaries.length < maxSlots && player.gold >= template.hireCost;
            return (
              <div key={type} className="flex items-center gap-3 bg-age-navy/70 border border-age-gold/20 p-2 rounded">
                <span className="text-2xl">{template.icon}</span>
                <div className="flex-1">
                  <div className="text-age-paper text-sm">{getMercenaryTypeName(type)}</div>
                  <div className="text-[10px] text-age-paper/60">
                    {'⚔️'}{template.baseAttack} {'🛡️'}{template.baseDefense} {'✨'}{template.baseMagic} | {'🍞'} 이동당 {template.foodPerTravel}
                  </div>
                </div>
                <Button size="xs" disabled={!canHire} onClick={() => canHire && onHire(type)}>
                  {'💰'} {template.hireCost}G
                </Button>
              </div>
            );
          })}
        </div>
      </div>
    </Panel>
  );
}
