import { GAME_CONFIG, TILE_TYPES } from '../constants/config';
import { REGIONS } from '../constants/regions';
import type { TileMap } from '../types';

/** 특정 픽셀 좌표가 벽 또는 맵 밖인지 충돌 검사 */
export const checkCollision = (x: number, y: number, map: TileMap): boolean => {
  const tileX = Math.floor(x / GAME_CONFIG.TILE_SIZE);
  const tileY = Math.floor(y / GAME_CONFIG.TILE_SIZE);
  if (tileX < 0 || tileX >= GAME_CONFIG.MAP_WIDTH || tileY < 0 || tileY >= GAME_CONFIG.MAP_HEIGHT) return true;
  return map[tileY]?.[tileX] === TILE_TYPES.WALL;
};

/** 마을 맵 생성 (25x15) - 외벽, 상점/제작/게시판/포탈 타일 배치, 항구 테마 시 물 타일 */
export const generateTownMap = (regionId: string): TileMap => {
  const region = REGIONS[regionId];
  const map: TileMap = Array(GAME_CONFIG.MAP_HEIGHT).fill(null).map((_, y) =>
    Array(GAME_CONFIG.MAP_WIDTH).fill(null).map((_, x) => {
      if (x === 0 || x === GAME_CONFIG.MAP_WIDTH - 1 || y === 0 || y === GAME_CONFIG.MAP_HEIGHT - 1) return TILE_TYPES.WALL;
      if (region?.theme === 'port' && y >= GAME_CONFIG.MAP_HEIGHT - 3 && x > 3 && x < GAME_CONFIG.MAP_WIDTH - 4) return TILE_TYPES.WATER;
      return TILE_TYPES.FLOOR;
    })
  );
  map[3][4] = TILE_TYPES.SHOP;
  map[3][20] = TILE_TYPES.CRAFTING;
  map[7][12] = TILE_TYPES.QUEST_BOARD;
  map[12][12] = TILE_TYPES.PORTAL;
  return map;
};

/** 던전 맵 생성 - 레벨에 비례하여 벽 밀도 증가, SEA 지역은 물 타일 포함 */
export const generateDungeonMap = (level: number, regionId: string): TileMap => {
  const region = REGIONS[regionId];
  const map: TileMap = Array(GAME_CONFIG.MAP_HEIGHT).fill(null).map((_, y) =>
    Array(GAME_CONFIG.MAP_WIDTH).fill(null).map((_, x) => {
      if (x === 0 || x === GAME_CONFIG.MAP_WIDTH - 1 || y === 0 || y === GAME_CONFIG.MAP_HEIGHT - 1) return TILE_TYPES.WALL;
      if (region?.primaryType === 'SEA' && Math.random() < 0.08) return TILE_TYPES.WATER;
      if (Math.random() < 0.05 + level * 0.01 && x > 4 && y > 4) return TILE_TYPES.WALL;
      return TILE_TYPES.FLOOR;
    })
  );
  map[2][2] = TILE_TYPES.PORTAL;
  map[3][3] = TILE_TYPES.FLOOR;
  map[3][4] = TILE_TYPES.FLOOR;
  return map;
};

/** 보스 맵 생성 - 넓은 아레나, 4개 기둥 장애물, 하단 포탈 */
export const generateBossMap = (): TileMap => {
  const map: TileMap = Array(GAME_CONFIG.MAP_HEIGHT).fill(null).map((_, y) =>
    Array(GAME_CONFIG.MAP_WIDTH).fill(null).map((_, x) => {
      if (x === 0 || x === GAME_CONFIG.MAP_WIDTH - 1 || y === 0 || y === GAME_CONFIG.MAP_HEIGHT - 1) return TILE_TYPES.WALL;
      return TILE_TYPES.FLOOR;
    })
  );
  ([[4, 6], [4, 18], [10, 6], [10, 18]] as [number, number][]).forEach(([py, px]) => {
    map[py][px] = TILE_TYPES.WALL;
    if (map[py][px + 1] !== undefined) map[py][px + 1] = TILE_TYPES.WALL;
  });
  map[GAME_CONFIG.MAP_HEIGHT - 2][12] = TILE_TYPES.PORTAL;
  return map;
};
