import { useEffect, useRef } from 'react';
import { GAME_CONFIG, GAME_STATES, QUEST_TYPES, STAT_CONFIG } from '../constants/config';
import { checkCollision } from '../utils/mapGenerator';
import { getDistance } from '../utils/math';
import { generateDrop } from '../utils/spawner';
import { rollDamage } from '../utils/combat';
import { playSfx } from '../utils/audio';
import {
  applyStatusEffect,
  tickStatusEffects,
  isStunned,
  getEffectiveSpeedMult,
} from '../utils/statusEffects';
import {
  findNewlyEnteredPhases,
  applyPhaseTriggers,
  PHASE_TRIGGER_LABELS,
} from '../utils/bossPhases';
import {
  hasRegen,
  hasExplosive,
  calculateRegenAmount,
  EXPLOSIVE_DAMAGE_MULT,
  EXPLOSIVE_RADIUS,
} from '../utils/eliteAffixes';
import { triggerShake } from '../three/cameraShake';
import { spawnBurst } from '../three/particles';
import { setPlayer } from '../stores/usePlayerStore';
import { setMonsters, setProjectiles, setDroppedItems, useCombatStore } from '../stores/useCombatStore';
import { setGameState } from '../stores/useWorldStore';
import type { GameState, Player, SpawnedMonster, Projectile, FloatingText, TileMap, DroppedItem, Mercenary, StatusEffectType } from '../types';

/** 상태이상 부여 시 떠오르는 라벨 (피격 위치 위에 한 번 표시) */
const STATUS_LABELS: Record<StatusEffectType, string> = {
  burn: '🔥 화상',
  bleed: '🩸 출혈',
  slow: '❄️ 둔화',
  stun: '💫 스턴',
};
/** 상태이상 tick 주기 (ms). 마나 재생과 같은 10Hz. */
const STATUS_TICK_INTERVAL_MS = 100;

/** useGameLoop 훅 파라미터 - 게임 상태, 맵, 플레이어 등. set* 액션은 store에서 직접 import. */
interface UseGameLoopParams {
  gameState: GameState;
  map: TileMap;
  player: Player;
  dungeonLevel: number;
  mercenaries: Mercenary[];
  pressedKeys: React.RefObject<Set<string>>;
  paused?: boolean;
  autoLootRadius?: number;
  setFloatingTexts: React.Dispatch<React.SetStateAction<FloatingText[]>>;
  gainExp: (amount: number) => void;
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
  updateQuestProgress: (type: string, target: string) => void;
  onMonsterKilled?: (monster: SpawnedMonster) => void;
  /** 자동 루팅 대상 1개를 처리. true 반환 시 아이템 소비됨. */
  onAutoLoot?: (item: DroppedItem) => boolean;
}

/**
 * 메인 게임 루프 훅 - requestAnimationFrame 기반
 * - WASD 이동 (충돌 검사 포함)
 * - 몬스터 AI (추적 + 근접 공격)
 * - 투사체 이동 + 적중 판정 (용병 보너스 포함)
 * - 마나 자동 재생
 * - 플로팅 텍스트 애니메이션
 *
 * 최적화: player/mercenaries/map/콜백을 ref로 참조해 매 프레임 effect 재구독 방지
 */
export function useGameLoop({
  gameState,
  map,
  player,
  dungeonLevel,
  mercenaries,
  pressedKeys,
  paused = false,
  autoLootRadius = GAME_CONFIG.AUTO_LOOT_RADIUS,
  setFloatingTexts,
  gainExp,
  addFloatingText,
  updateQuestProgress,
  onMonsterKilled,
  onAutoLoot,
}: UseGameLoopParams) {
  // Refs updated every render so the rAF loop reads latest values without re-subscribing
  const playerRef = useRef(player);
  const mercRef = useRef(mercenaries);
  const mapRef = useRef(map);
  const dungeonLevelRef = useRef(dungeonLevel);
  const gainExpRef = useRef(gainExp);
  const addFloatingTextRef = useRef(addFloatingText);
  const updateQuestProgressRef = useRef(updateQuestProgress);
  const onMonsterKilledRef = useRef(onMonsterKilled);
  const pausedRef = useRef(paused);
  const onAutoLootRef = useRef(onAutoLoot);
  const autoLootRadiusRef = useRef(autoLootRadius);

  playerRef.current = player;
  mercRef.current = mercenaries;
  mapRef.current = map;
  dungeonLevelRef.current = dungeonLevel;
  gainExpRef.current = gainExp;
  addFloatingTextRef.current = addFloatingText;
  updateQuestProgressRef.current = updateQuestProgress;
  onMonsterKilledRef.current = onMonsterKilled;
  pausedRef.current = paused;
  onAutoLootRef.current = onAutoLoot;
  autoLootRadiusRef.current = autoLootRadius;

  useEffect(() => {
    if (gameState !== GAME_STATES.TOWN && gameState !== GAME_STATES.DUNGEON && gameState !== GAME_STATES.BOSS) return;

    let rafId = 0;
    // throttled mana regen — see GAME_CONFIG.MANA_REGEN_INTERVAL_MS rationale
    let lastManaRegenAt = Date.now();
    // throttled status-effect tick (100ms): bleeds/burns deal damage and durations expire here
    let lastStatusTickAt = Date.now();

    const loop = () => {
      if (pausedRef.current) {
        rafId = requestAnimationFrame(loop);
        return;
      }
      const now = Date.now();
      const keys = pressedKeys.current;
      const p = playerRef.current;
      const currentMap = mapRef.current;
      const mercs = mercRef.current;

      const mercAttack = mercs.reduce((s, m) => s + m.attack, 0) * STAT_CONFIG.MERC_COMBAT_BONUS_PCT;
      const mercDefense = mercs.reduce((s, m) => s + m.defense, 0) * STAT_CONFIG.MERC_COMBAT_BONUS_PCT;

      // 방향키 이동
      if (keys && keys.size > 0) {
        let dx = 0;
        let dy = 0;
        if (keys.has('w')) dy -= 1;
        if (keys.has('s')) dy += 1;
        if (keys.has('a')) dx -= 1;
        if (keys.has('d')) dx += 1;

        if (dx !== 0 || dy !== 0) {
          const len = Math.hypot(dx, dy);
          dx = (dx / len) * p.speed;
          dy = (dy / len) * p.speed;

          setPlayer(prev => {
            const nx = prev.x + dx;
            const ny = prev.y + dy;
            if (!checkCollision(nx, ny, currentMap)) return { ...prev, x: nx, y: ny };
            return prev;
          });
        }
      }

      // 전투 로직은 던전/보스에서만
      if (gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) {
        // 자동 루팅 - 반경 내 골드/일반 아이템 자동 획득 (상자/장비 제외는 onAutoLoot 정책에 위임)
        const lootCb = onAutoLootRef.current;
        if (lootCb) {
          const items = useCombatStore.getState().droppedItems;
          const r2 = autoLootRadiusRef.current * autoLootRadiusRef.current;
          for (const item of items) {
            const dx = item.x - p.x;
            const dy = item.y - p.y;
            if (dx * dx + dy * dy <= r2) {
              lootCb(item);
            }
          }
        }

        const effectiveDefense = p.defense + mercDefense;

        // === 1) Read current state from store ===
        const monsters = useCombatStore.getState().monsters;
        const projectiles = useCombatStore.getState().projectiles;

        // === 2) Accumulate side effects so we can dispatch a single setPlayer at the end ===
        let damageToPlayer = 0;
        let goldFromKills = 0;
        const dropsToAdd: DroppedItem[] = [];

        // === 3) Monster AI: move + opportunistic melee strike (no nested setPlayer) ===
        // status: stun blocks all action; slow multiplies movement & attack speed.
        const movedMonsters: SpawnedMonster[] = monsters.map((m) => {
          if (isStunned(m)) return m;

          const speedMult = getEffectiveSpeedMult(m);
          const mdx = p.x - m.x;
          const mdy = p.y - m.y;
          const dist = Math.hypot(mdx, mdy);
          let nx = m.x;
          let ny = m.y;
          let lastAttack = m.lastAttack;

          if (dist > 40 && dist < 350) {
            const tx = m.x + (mdx / dist) * m.speed * speedMult;
            const ty = m.y + (mdy / dist) * m.speed * speedMult;
            if (!checkCollision(tx, ty, currentMap)) { nx = tx; ny = ty; }
          }

          // Slowed monsters also attack less often (cooldown scales inversely with speedMult, capped 1.0)
          const attackCooldown = speedMult > 0 ? 1000 / speedMult : Infinity;
          if (dist < 50 && now - m.lastAttack > attackCooldown) {
            const baseDmg = Math.max(1, m.attack - effectiveDefense * 0.5);
            const { damage: dmg } = rollDamage(baseDmg);
            damageToPlayer += dmg;
            addFloatingTextRef.current(p.x, p.y - 20, `-${dmg}`, '#e74c3c');
            triggerShake(0.18, 140);
            playSfx('hit');
            lastAttack = now;
          }

          if (nx === m.x && ny === m.y && lastAttack === m.lastAttack) return m;
          return { ...m, x: nx, y: ny, lastAttack };
        });

        // === 4) Projectile step + hit detection. Monsters are mutated/marked killed locally; one final write. ===
        const killedMonsterUids = new Set<string>();
        const survivingProjectiles: Projectile[] = [];

        for (const proj of projectiles) {
          proj.x += proj.vx;
          proj.y += proj.vy;
          proj.traveled += Math.hypot(proj.vx, proj.vy);

          let hit = false;
          for (let i = 0; i < movedMonsters.length; i++) {
            const m = movedMonsters[i];
            if (killedMonsterUids.has(m.uid)) continue;
            if (getDistance(m.x, m.y, proj.x, proj.y) < m.size) {
              hit = true;
              const baseDmg = proj.damage + Math.floor(mercAttack);
              const { damage: totalDamage, isCrit } = rollDamage(baseDmg, p.critChance, p.critDamage);
              const newHp = m.currentHp - totalDamage;
              if (isCrit) {
                addFloatingTextRef.current(m.x, m.y - 20, `✦ ${totalDamage} ✦`, '#f97316', 1.6);
                triggerShake(0.22, 160);
                playSfx('crit');
              } else {
                addFloatingTextRef.current(m.x, m.y - 20, `-${totalDamage}`, '#ffd700');
                playSfx('hit');
              }
              if (newHp <= 0) {
                killedMonsterUids.add(m.uid);
                gainExpRef.current(m.exp);
                goldFromKills += m.gold;
                addFloatingTextRef.current(m.x, m.y, `+${m.exp} EXP`, '#9b59b6');
                updateQuestProgressRef.current(QUEST_TYPES.KILL, m.id);
                if (m.isBoss) updateQuestProgressRef.current(QUEST_TYPES.BOSS, m.id);
                dropsToAdd.push(...generateDrop(m, dungeonLevelRef.current));
                onMonsterKilledRef.current?.(m);
                playSfx('kill');
                spawnBurst(m.x, m.y, m.color, m.isBoss ? 24 : m.isElite ? 14 : 8);

                // Elite "explosive" affix: AOE damage to player on death
                if (m.isElite && hasExplosive(m)) {
                  const distToPlayer = Math.hypot(p.x - m.x, p.y - m.y);
                  if (distToPlayer <= EXPLOSIVE_RADIUS) {
                    const explosiveDmg = Math.floor(m.attack * EXPLOSIVE_DAMAGE_MULT);
                    damageToPlayer += explosiveDmg;
                    addFloatingTextRef.current(m.x, m.y - 60, `💥 -${explosiveDmg}`, '#fb923c', 1.5);
                  }
                  triggerShake(0.4, 200);
                  spawnBurst(m.x, m.y, '#fb923c', 20);
                }
              } else {
                // Apply status effect on hit (if projectile carries one and chance rolls)
                let nextEffects = m.statusEffects;
                if (proj.applyStatus) {
                  const before = nextEffects;
                  nextEffects = applyStatusEffect(nextEffects, proj.applyStatus);
                  if (nextEffects !== before) {
                    const label = STATUS_LABELS[proj.applyStatus.type];
                    addFloatingTextRef.current(m.x, m.y - 35, label, '#f97316');
                  }
                }
                let updatedM: SpawnedMonster = { ...m, currentHp: newHp, statusEffects: nextEffects };

                // === Boss phase progression: trigger on HP threshold crossings ===
                if (updatedM.isBoss && updatedM.phases && updatedM.phases.length > 0) {
                  const newlyEntered = findNewlyEnteredPhases(updatedM);
                  if (newlyEntered.length > 0) {
                    const distToPlayer = Math.hypot(p.x - updatedM.x, p.y - updatedM.y);
                    for (const phaseIdx of newlyEntered) {
                      const triggers = updatedM.phases![phaseIdx].triggers ?? [];
                      if (triggers.length > 0) {
                        const result = applyPhaseTriggers(updatedM, triggers, distToPlayer);
                        updatedM = result.boss;
                        if (result.aoeDamageToPlayer > 0) damageToPlayer += result.aoeDamageToPlayer;
                        for (const t of triggers) {
                          addFloatingTextRef.current(updatedM.x, updatedM.y - 50, PHASE_TRIGGER_LABELS[t.kind], '#ff4444', 1.4);
                        }
                      }
                    }
                    updatedM = {
                      ...updatedM,
                      activatedPhases: [...(updatedM.activatedPhases ?? []), ...newlyEntered],
                    };
                    triggerShake(0.3, 180);
                  }
                }

                movedMonsters[i] = updatedM;
              }
              break;
            }
          }

          if (!hit && checkCollision(proj.x, proj.y, currentMap)) hit = true;
          if (!hit && proj.traveled < proj.range) survivingProjectiles.push(proj);
        }

        // === 5) Commit all changes once per frame ===
        const finalMonsters = killedMonsterUids.size
          ? movedMonsters.filter((m) => !killedMonsterUids.has(m.uid))
          : movedMonsters;
        setMonsters(finalMonsters);
        setProjectiles(survivingProjectiles);
        if (dropsToAdd.length) setDroppedItems((prev) => [...prev, ...dropsToAdd]);

        if (damageToPlayer > 0 || goldFromKills > 0) {
          setPlayer((prev) => {
            const tentativeHp = prev.hp - damageToPlayer;
            const tentativeGold = prev.gold + goldFromKills;
            if (damageToPlayer > 0 && tentativeHp <= 0) {
              const goldLost = Math.floor(prev.gold * STAT_CONFIG.DEATH_GOLD_LOSS_PCT);
              if (goldLost > 0) {
                addFloatingTextRef.current(prev.x, prev.y - 40, `-${goldLost}💰`, '#ffd700');
              }
              triggerShake(0.9, 420);
              playSfx('death');
              setGameState(GAME_STATES.GAMEOVER as GameState);
              return { ...prev, hp: 0, gold: Math.max(0, tentativeGold - goldLost) };
            }
            return { ...prev, hp: tentativeHp, gold: tentativeGold };
          });
        }

        if (now - lastManaRegenAt >= GAME_CONFIG.MANA_REGEN_INTERVAL_MS) {
          const dtSec = (now - lastManaRegenAt) / 1000;
          lastManaRegenAt = now;
          setPlayer(prev => ({ ...prev, mp: Math.min(prev.maxMp, prev.mp + GAME_CONFIG.MANA_REGEN_PER_SECOND * dtSec) }));
        }

        // === 6) Status-effect tick (10Hz) — applies bleed/burn dps, decrements durations,
        //        removes expired effects, and may kill monsters via DoT. ===
        if (now - lastStatusTickAt >= STATUS_TICK_INTERVAL_MS) {
          const dtMs = now - lastStatusTickAt;
          lastStatusTickAt = now;
          const current = useCombatStore.getState().monsters;
          const additionalKills: string[] = [];
          let tickChanged = false;
          const ticked = current.map((m) => {
            let nextHp = m.currentHp;
            let nextEffects = m.statusEffects;
            let mutated = false;

            // Elite "regen" affix: heal a fraction of maxHp each tick
            if (m.isElite && hasRegen(m) && m.currentHp < m.maxHp) {
              const regenAmt = calculateRegenAmount(m.maxHp, dtMs);
              const healed = Math.min(m.maxHp, m.currentHp + regenAmt);
              if (healed !== m.currentHp) {
                nextHp = healed;
                mutated = true;
              }
            }

            // Status DoT (burn / bleed) + expiry sweep
            if (m.statusEffects && m.statusEffects.length > 0) {
              const { effects, damageDealt } = tickStatusEffects(m.statusEffects, dtMs);
              if (damageDealt > 0) nextHp -= damageDealt;
              if (damageDealt > 0 || effects !== m.statusEffects) mutated = true;
              nextEffects = effects;
            }

            if (!mutated) return m;
            tickChanged = true;

            if (nextHp <= 0) {
              additionalKills.push(m.uid);
              gainExpRef.current(m.exp);
              addFloatingTextRef.current(m.x, m.y, `+${m.exp} EXP`, '#9b59b6');
              updateQuestProgressRef.current(QUEST_TYPES.KILL, m.id);
              if (m.isBoss) updateQuestProgressRef.current(QUEST_TYPES.BOSS, m.id);
              onMonsterKilledRef.current?.(m);
              playSfx('kill');
              spawnBurst(m.x, m.y, m.color, m.isBoss ? 24 : m.isElite ? 14 : 8);
              return m; // marked for removal below
            }
            return { ...m, currentHp: nextHp, statusEffects: nextEffects };
          });
          if (additionalKills.length > 0) {
            const killSet = new Set(additionalKills);
            const dotKilledMonsters = current.filter((m) => killSet.has(m.uid));
            let dotGold = 0;
            for (const m of dotKilledMonsters) {
              dotGold += m.gold;
              dropsToAdd.push(...generateDrop(m, dungeonLevelRef.current));
            }
            if (dotGold > 0) {
              setPlayer((prev) => ({ ...prev, gold: prev.gold + dotGold }));
            }
            setMonsters(ticked.filter((m) => !killSet.has(m.uid)));
          } else if (tickChanged) {
            setMonsters(ticked);
          }
        }
      }

      setFloatingTexts(prev => prev.map(t => ({ ...t, offsetY: t.offsetY - 1, opacity: t.opacity - 0.02 })));

      rafId = requestAnimationFrame(loop);
    };

    rafId = requestAnimationFrame(loop);
    return () => { if (rafId) cancelAnimationFrame(rafId); };
  }, [gameState, pressedKeys, setFloatingTexts]);
}
