import type { Player } from '../types';

interface LowHpVignetteProps {
  player: Player;
}

/**
 * HP < 30% 일 때 화면 가장자리에 붉은 비네트 표시.
 * radial-gradient + 펄스 애니메이션. pointer-events-none.
 */
export default function LowHpVignette({ player }: LowHpVignetteProps) {
  const pct = player.maxHp > 0 ? player.hp / player.maxHp : 1;
  if (pct >= 0.3 || player.hp <= 0) return null;

  // 0.3 → opacity 0.25, 0.05 → opacity 0.85
  const intensity = Math.min(1, (0.3 - pct) / 0.25);
  const opacity = 0.25 + intensity * 0.6;

  return (
    <div
      className="absolute inset-0 pointer-events-none z-[55] animate-pulse"
      style={{
        background:
          'radial-gradient(ellipse at center, transparent 35%, rgba(180,20,20,0.55) 75%, rgba(140,10,10,0.95) 100%)',
        opacity,
        mixBlendMode: 'multiply',
      }}
    />
  );
}
