import { QUESTS } from '../constants/quests';
import { QUEST_STATUS } from '../constants/config';
import type { QuestProgress } from '../types';

interface QuestTrackerProps {
  questProgress: Record<string, QuestProgress>;
  /** 표시할 활성 퀘스트 최대 개수 (기본 2) */
  maxVisible?: number;
}

/** 진행 중인 퀘스트를 HUD 좌측 하단 위에 항시 표시. 메인 퀘스트 우선. */
export default function QuestTracker({ questProgress, maxVisible = 2 }: QuestTrackerProps) {
  const active = Object.entries(questProgress)
    .filter(([, p]) => p.status === QUEST_STATUS.ACTIVE)
    .map(([id, p]) => ({ id, progress: p, quest: QUESTS[id] }))
    .filter(e => !!e.quest)
    .sort((a, b) => Number(b.quest.isMain) - Number(a.quest.isMain))
    .slice(0, maxVisible);

  if (active.length === 0) return null;

  return (
    <div className="absolute top-12 right-2 panel-parchment rounded-md p-2 text-age-paper text-[11px] min-w-[180px] max-w-[240px] animate-fade-in pointer-events-none">
      <div className="text-age-gold font-bold text-[10px] mb-1.5 flex items-center gap-1">
        {'📜'} 진행 퀘스트
      </div>
      <div className="space-y-1.5">
        {active.map(({ id, quest, progress }) => {
          const pct = Math.min(100, (progress.currentCount / quest.targetCount) * 100);
          const done = progress.currentCount >= quest.targetCount;
          return (
            <div key={id}>
              <div className="flex items-center justify-between gap-2 mb-0.5">
                <span className={`truncate ${quest.isMain ? 'text-age-gold' : 'text-age-paper'}`}>
                  {quest.isMain ? '⭐ ' : ''}{quest.name}
                </span>
                <span className={`text-[10px] tabular-nums ${done ? 'text-age-leaf' : 'text-age-paper/70'}`}>
                  {progress.currentCount}/{quest.targetCount}
                </span>
              </div>
              <div className="h-1 bg-age-navy/80 rounded-sm overflow-hidden border border-age-gold/20">
                <div
                  className={`h-full transition-all ${done ? 'bg-age-leaf' : 'bg-age-amber'}`}
                  style={{ width: `${pct}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
