/**
 * Module-level camera shake controller.
 * Imperatively trigger shake from any game-loop code; the camera reads
 * the active shake offset each frame via `sampleShake`.
 */

let endTime = 0;
let intensity = 0;
let duration = 0;

import { getGraphicsSettings } from '../utils/graphicsSettings';

/** Trigger a camera shake. Later calls extend/override weaker ongoing shakes. */
export function triggerShake(amount = 0.25, ms = 180) {
  if (!getGraphicsSettings().cameraShake) return;
  const now = performance.now();
  const remaining = Math.max(0, endTime - now);
  if (amount * ms >= intensity * remaining) {
    intensity = amount;
    duration = ms;
    endTime = now + ms;
  }
}

/** Returns current shake offset {x, y} in world units. Zero when inactive. */
export function sampleShake(): { x: number; y: number } {
  const now = performance.now();
  if (now >= endTime || intensity <= 0) return { x: 0, y: 0 };
  const remaining = (endTime - now) / duration;
  const falloff = remaining * remaining;
  const amp = intensity * falloff;
  return {
    x: (Math.random() * 2 - 1) * amp,
    y: (Math.random() * 2 - 1) * amp,
  };
}
