import { useCallback, useEffect, useRef, useState } from 'react';
import { GAME_STATES } from '../constants/config';
import {
  saveGame,
  loadGame,
  saveToSlot,
  loadFromSlot,
  deleteSlot,
} from '../utils/saveLoad';
import type { GameState, SaveData, SaveSlotId } from '../types';
import type { UseAchievementsApi } from './useAchievements';

interface UseSaveSystemParams {
  gameState: GameState;
  autoSaveEnabled: boolean;
  autoSaveIntervalMinutes: number;
  buildSaveData: () => SaveData;
  applyLoadedData: (data: SaveData) => void;
  achievements: UseAchievementsApi;
}

const AUTOSAVE_STATES: GameState[] = [GAME_STATES.TOWN, GAME_STATES.WORLD_MAP];

/**
 * Centralizes save/load: file export/import, slot save/load/delete, and the autosave timer.
 * Keeps `App.tsx` focused on game state.
 */
export function useSaveSystem({
  gameState,
  autoSaveEnabled,
  autoSaveIntervalMinutes,
  buildSaveData,
  applyLoadedData,
  achievements,
}: UseSaveSystemParams) {
  const [slotsMode, setSlotsMode] = useState<'save' | 'load' | null>(null);

  // Refs let the autosave interval read latest values without re-binding every state change
  const buildRef = useRef(buildSaveData);
  buildRef.current = buildSaveData;
  const achievementsRef = useRef(achievements);
  achievementsRef.current = achievements;

  const handleSaveGame = useCallback(async () => {
    const data = buildRef.current();
    const ok = await saveGame(data);
    if (ok) {
      achievementsRef.current.pushToast({ title: '저장 완료', message: '항해일지에 기록했습니다.', icon: '📜', tone: 'success', duration: 2400 });
      achievementsRef.current.unlock('first_save');
    } else {
      achievementsRef.current.pushToast({ title: '저장 실패', icon: '⚠️', tone: 'warn', duration: 2400 });
    }
  }, []);

  const handleLoadGame = useCallback(async () => {
    const data = await loadGame();
    if (!data) return;
    applyLoadedData(data);
    achievementsRef.current.pushToast({ title: '불러오기 완료', icon: '📂', tone: 'success', duration: 2400 });
  }, [applyLoadedData]);

  const handleSaveToSlot = useCallback((slotId: SaveSlotId) => {
    const data = buildRef.current();
    const ok = saveToSlot(slotId, data);
    if (ok) {
      achievementsRef.current.pushToast({ title: '슬롯 저장 완료', message: slotId === 'auto' ? '자동 슬롯' : slotId, icon: '💾', tone: 'success', duration: 2400 });
      achievementsRef.current.unlock('first_save');
    } else {
      achievementsRef.current.pushToast({ title: '저장 실패', icon: '⚠️', tone: 'warn', duration: 2400 });
    }
    setSlotsMode(null);
  }, []);

  const handleLoadFromSlot = useCallback((slotId: SaveSlotId) => {
    const data = loadFromSlot(slotId);
    if (!data) {
      achievementsRef.current.pushToast({ title: '슬롯이 비어있습니다', icon: '⚠️', tone: 'warn', duration: 2400 });
      return;
    }
    applyLoadedData(data);
    setSlotsMode(null);
    achievementsRef.current.pushToast({ title: '불러오기 완료', icon: '📂', tone: 'success', duration: 2400 });
  }, [applyLoadedData]);

  const handleDeleteSlot = useCallback((slotId: SaveSlotId) => {
    deleteSlot(slotId);
    achievementsRef.current.pushToast({ title: '슬롯 삭제', icon: '🗑️', tone: 'info', duration: 1800 });
  }, []);

  useEffect(() => {
    if (!autoSaveEnabled) return;
    if (!AUTOSAVE_STATES.includes(gameState)) return;

    const intervalMs = Math.max(1, autoSaveIntervalMinutes) * 60 * 1000;
    const id = window.setInterval(() => {
      const ok = saveToSlot('auto', buildRef.current());
      if (ok) {
        achievementsRef.current.pushToast({ title: '자동 저장', icon: '💾', tone: 'info', duration: 1800 });
      }
    }, intervalMs);
    return () => window.clearInterval(id);
  }, [autoSaveEnabled, autoSaveIntervalMinutes, gameState]);

  return {
    slotsMode,
    setSlotsMode,
    handleSaveGame,
    handleLoadGame,
    handleSaveToSlot,
    handleLoadFromSlot,
    handleDeleteSlot,
  };
}
