import type { ReactNode } from 'react';

interface PanelProps {
  title?: ReactNode;
  icon?: ReactNode;
  onClose?: () => void;
  children: ReactNode;
  /** Positioning: 'center' = screen-center absolute overlay, 'inline' = static flow */
  layout?: 'center' | 'inline';
  /** Backdrop behavior: when using center layout, dim the rest of the screen */
  backdrop?: boolean;
  className?: string;
  headerExtra?: ReactNode;
  maxWidth?: string;
}

/**
 * 공통 패널 컴포넌트 - 대항해시대 양피지 톤 (딥 네이비 + 앰버 테두리)
 * 모든 모달과 화면에서 재사용되는 기본 컨테이너.
 */
export default function Panel({
  title,
  icon,
  onClose,
  children,
  layout = 'center',
  backdrop = false,
  className = '',
  headerExtra,
  maxWidth = 'min-w-[360px]',
}: PanelProps) {
  const body = (
    <div
      className={`panel-parchment rounded-lg p-5 ${maxWidth} animate-slide-up ${className}`}
    >
      {(title || onClose) && (
        <>
          <div className="flex items-center justify-between gap-3 mb-3">
            <h2 className="font-display text-lg font-bold text-age-gold flex items-center gap-2 whitespace-nowrap">
              {icon && <span className="text-xl">{icon}</span>}
              <span className="whitespace-nowrap">{title}</span>
            </h2>
            <div className="flex items-center gap-3">
              {headerExtra}
              {onClose && (
                <button
                  onClick={onClose}
                  className="text-age-paper/60 hover:text-age-gold text-xl leading-none transition-colors"
                  aria-label="close"
                >
                  {'✕'}
                </button>
              )}
            </div>
          </div>
          <div className="divider-gold mb-4" />
        </>
      )}
      {children}
    </div>
  );

  if (layout === 'inline') return body;

  if (backdrop) {
    return (
      <div className="fixed inset-0 modal-backdrop flex items-center justify-center z-50 animate-fade-in">
        {body}
      </div>
    );
  }

  return (
    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50">
      {body}
    </div>
  );
}
