/** 특정 지역의 특산 무역품 ID 목록 반환 */
export const getTradeGoodsForRegion = (regionId: string): string[] => {
  return Object.keys(ITEMS).filter(id => {
    const item = ITEMS[id];
    return item.type === 'trade_good' && item.tradeInfo?.originRegion === regionId;
  });
};
