import { useState, useCallback, useEffect, useRef, lazy, Suspense } from 'react';
import type { Player, InventoryItem, Equipment, DroppedItem, SaveData } from './types';
import { usePlayer, setPlayer } from './stores/usePlayerStore';
import { setMercenaries } from './stores/useMercenaryStore';
import { useMercenarySystem } from './hooks/useMercenarySystem';
import { useShopHandlers } from './hooks/useShopHandlers';
import { useQuestHandlers } from './hooks/useQuestHandlers';
import { useTravelSystem } from './hooks/useTravelSystem';
import { useCombatHandlers } from './hooks/useCombatHandlers';
import { useInventory, useEquipment, setInventory, setEquipment, EMPTY_EQUIPMENT } from './stores/useInventoryStore';
import {
  useMonsters,
  useBoss,
  useProjectiles,
  useDroppedItems,
  setMonsters,
  setBoss,
  setProjectiles,
  setDroppedItems,
} from './stores/useCombatStore';
import { useQuestProgress, setQuestProgress, resetQuestProgress } from './stores/useQuestStore';
import {
  useGameState,
  useCurrentRegion,
  useCurrentSubRegion,
  useDungeonLevel,
  useMap,
  useUnlockedRegions,
  useClearedSubRegions,
  useNgPlusLevel,
  useWorldStore,
  setGameState,
  setCurrentRegion,
  setCurrentSubRegion,
  setDungeonLevel,
  setMap,
  setUnlockedRegions,
  setClearedSubRegions,
  setNgPlusLevel,
} from './stores/useWorldStore';
import { GAME_CONFIG, GAME_STATES, STAT_CONFIG } from './constants/config';
import { REGIONS } from './constants/regions';
import { getNPCsForRegion } from './constants/regions';
import { ITEMS } from './constants/items';
import { SKILLS } from './constants/skills';
import { REGION_SPAWNS } from './constants/monsters';
import { SUB_REGIONS } from './constants/subRegions';
import { getDistance, pixelToTile, calculateExpToLevel } from './utils/math';
import { generateTownMap, generateDungeonMap, generateBossMap } from './utils/mapGenerator';
import { spawnMonsters, spawnBoss, spawnChests, generateChestLoot } from './utils/spawner';
import { createSaveData, listSlots } from './utils/saveLoad';
import { captureGameThumbnail } from './utils/screenshot';
import { ACHIEVEMENTS } from './constants/achievements';
import { useAchievements } from './hooks/useAchievements';
import { useSaveSystem } from './hooks/useSaveSystem';
import { ToastStack, Panel, Button } from './components/ui';
import { calculateDerivedStats, calculateInventoryWeight } from './utils/stats';
import { useFloatingText } from './hooks/useFloatingText';
import { useKeyboardInput } from './hooks/useKeyboardInput';
import { useArrowKeys } from './hooks/useArrowKeys';
import { useGameLoop } from './hooks/useGameLoop';
import { playSfx, primeAudio } from './utils/audio';
import { triggerShake } from './three/cameraShake';
import {
  MenuScreen,
  CharacterCreateScreen,
  GameOverScreen,
  HUD,
  SkillBar,
  BossHealthBar,
  Minimap,
  InventoryModal,
  QuestModal,
  ShopModal,
  CraftingModal,
  RegionInfoModal,
  MercenaryModal,
  TravelEncounterModal,
  SettingsModal,
  SaveSlotsModal,
} from './components';
import PauseMenu from './components/PauseMenu';
import TutorialOverlay, { hasSeenTutorial } from './components/TutorialOverlay';
import VirtualJoystick from './components/VirtualJoystick';
import QuestTracker from './components/QuestTracker';
import LowHpVignette from './components/LowHpVignette';
import SkillTreeModal from './components/modals/SkillTreeModal';
import { investNodePoint } from './utils/skillTree';
import type { SkillNodeKind } from './types';

// Heavy 3D / map bundles — code-split so the menu screen loads instantly
const SceneRoot = lazy(() => import('./three/SceneRoot'));
const WorldMap = lazy(() => import('./components/WorldMap'));
const TravelScreen = lazy(() => import('./components/TravelScreen'));

function LazyFallback({ message }: { message: string }) {
  return (
    <div className="w-full h-full flex items-center justify-center bg-age-navy">
      <div className="panel-parchment rounded-md px-5 py-3 text-age-gold text-sm animate-glow-pulse">
        {message}
      </div>
    </div>
  );
}

export default function App() {
  const gameState = useGameState();
  const currentRegion = useCurrentRegion();
  const dungeonLevel = useDungeonLevel();
  const map = useMap();
  const monsters = useMonsters();
  const boss = useBoss();
  const projectiles = useProjectiles();
  const droppedItems = useDroppedItems();
  const unlockedRegions = useUnlockedRegions();
  // mercenaries는 useMercenarySystem이 반환 (아래에서 hook 호출)
  const clearedSubRegions = useClearedSubRegions();
  const currentSubRegion = useCurrentSubRegion();

  const player = usePlayer();

  const inventory = useInventory();
  const equipment = useEquipment();
  // selectedSkill / skillCooldowns / lockedTargetUid는 useCombatHandlers가 보유 (아래에서 호출)

  const questProgress = useQuestProgress();

  const [showInventory, setShowInventory] = useState(false);
  const [showQuests, setShowQuests] = useState(false);
  const [showShop, setShowShop] = useState(false);
  const [showCrafting, setShowCrafting] = useState(false);
  const [showRegionInfo, setShowRegionInfo] = useState(false);
  const [showMercenary, setShowMercenary] = useState(false);
  const [showSkillTree, setShowSkillTree] = useState(false);

  // Travel state는 useTravelSystem이 보유 (아래에서 호출)

  // Sub-region selection
  const [showSubRegionSelect, setShowSubRegionSelect] = useState(false);

  // Settings & save slots
  const [showSettings, setShowSettings] = useState(false);
  const [autoSaveEnabled, setAutoSaveEnabled] = useState(true);
  const [autoSaveIntervalMinutes, setAutoSaveIntervalMinutes] = useState(5);

  // Pause
  const [paused, setPaused] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);

  const pressedKeys = useArrowKeys();

  const { floatingTexts, setFloatingTexts, addFloatingText } = useFloatingText();
  const achievements = useAchievements();
  const achievementsRef = useRef(achievements);
  achievementsRef.current = achievements;

  const { mercenaries, hireMercenary, fireMercenary } = useMercenarySystem({
    addFloatingText,
    unlockAchievement: (id) => achievementsRef.current.unlock(id),
  });

  // useShopHandlers는 useQuestHandlers 정의 이후로 이동 (onTradeSold가 updateQuestProgress 사용)

  // First-time tutorial trigger — fires the first time the player reaches TOWN
  useEffect(() => {
    if (gameState === GAME_STATES.TOWN && !hasSeenTutorial()) {
      setShowTutorial(true);
    }
  }, [gameState]);

  // Recalculate weight whenever inventory changes
  useEffect(() => {
    const weight = calculateInventoryWeight(inventory);
    setPlayer(prev => ({ ...prev, currentWeight: weight }));
  }, [inventory]);

  // Achievement triggers driven by derived state
  useEffect(() => {
    if (gameState === GAME_STATES.MENU || gameState === GAME_STATES.CHARACTER_CREATE) return;
    if (player.level >= 5) achievementsRef.current.unlock('reach_level_5');
    if (player.level >= 10) achievementsRef.current.unlock('reach_level_10');
    if (player.level >= 20) achievementsRef.current.unlock('reach_level_20');
    if (player.gold >= 1000) achievementsRef.current.unlock('gold_1000');
    if (player.gold >= 10000) achievementsRef.current.unlock('gold_10000');
  }, [gameState, player.level, player.gold]);

  useEffect(() => {
    if (gameState === GAME_STATES.MENU || gameState === GAME_STATES.CHARACTER_CREATE) return;
    const allRegionIds = Object.keys(REGIONS);
    if (unlockedRegions.length >= allRegionIds.length) {
      achievementsRef.current.unlock('visit_all_regions');
    }
    const allSubIds = Object.keys(SUB_REGIONS);
    if (allSubIds.length > 0 && clearedSubRegions.length >= allSubIds.length) {
      achievementsRef.current.unlock('clear_all_sub_regions');
    }
  }, [gameState, unlockedRegions, clearedSubRegions]);

  // NG+ 진입: 모든 sub-region을 클리어하면 차수를 +1 하고 진행도 초기화
  useEffect(() => {
    if (gameState === GAME_STATES.MENU || gameState === GAME_STATES.CHARACTER_CREATE) return;
    const allSubIds = Object.keys(SUB_REGIONS);
    if (allSubIds.length === 0) return;
    const cleared = allSubIds.every((id) => clearedSubRegions.includes(id));
    if (!cleared) return;
    setNgPlusLevel((n) => n + 1);
    setClearedSubRegions([]);
    setDungeonLevel(1);
    const nextLevel = useWorldStore.getState().ngPlusLevel; // updated atomically above
    addFloatingText(player.x || 500, (player.y || 400) - 100, `🌟 NG+${nextLevel} 진입!`, '#ffd700', 2.0);
  }, [gameState, clearedSubRegions, addFloatingText, player.x, player.y]);

  // Recalculate derived stats when primary stats or equipment change
  const recalcDerivedStats = useCallback((p: Player, eq: Equipment) => {
    const derived = calculateDerivedStats(p.str, p.agi, p.int, eq);
    return {
      ...p,
      attack: derived.attack,
      defense: derived.defense,
      magic: derived.magic,
      speed: derived.speed,
      critChance: derived.critChance,
      critDamage: derived.critDamage,
      maxWeight: derived.maxWeight,
      maxHp: 100 + (p.level - 1) * 25 + derived.maxHpBonus,
      maxMp: 80 + (p.level - 1) * 18 + derived.maxMpBonus,
    };
  }, []);

  const allocateStat = useCallback((stat: 'str' | 'agi' | 'int') => {
    setPlayer(prev => {
      if (prev.statPoints <= 0) return prev;
      const updated = { ...prev, [stat]: prev[stat] + 1, statPoints: prev.statPoints - 1 };
      return recalcDerivedStats(updated, equipment);
    });
  }, [equipment, recalcDerivedStats]);

  const gainExp = useCallback((amount: number) => {
    setPlayer(prev => {
      let exp = prev.exp + amount;
      let level = prev.level;
      let expToLevel = prev.expToLevel;
      let statPoints = prev.statPoints;
      let updated = { ...prev };

      while (exp >= expToLevel) {
        exp -= expToLevel;
        level++;
        expToLevel = calculateExpToLevel(level);
        statPoints += STAT_CONFIG.STAT_POINTS_PER_LEVEL;
        addFloatingText(prev.x, prev.y - 50, `레벨 업! Lv.${level}`, '#ffd700');
        playSfx('levelup');

        Object.entries(REGIONS).forEach(([id, region]) => {
          if (region.unlockLevel === level) {
            setUnlockedRegions(ur => [...new Set([...ur, id])]);
            addFloatingText(prev.x, prev.y - 80, `${region.name} 해금!`, '#00ff00');
          }
        });
      }

      updated = { ...updated, exp, level, expToLevel, statPoints };
      if (level > prev.level) {
        // Recalculate derived stats at new level
        const derived = calculateDerivedStats(updated.str, updated.agi, updated.int, equipment);
        updated.maxHp = 100 + (level - 1) * 25 + derived.maxHpBonus;
        updated.maxMp = 80 + (level - 1) * 18 + derived.maxMpBonus;
        updated.hp = updated.maxHp;
        updated.mp = updated.maxMp;
        updated.attack = derived.attack;
        updated.defense = derived.defense;
        updated.magic = derived.magic;
        updated.speed = derived.speed;
        updated.maxWeight = derived.maxWeight;
      }

      return updated;
    });
  }, [addFloatingText, equipment]);

  const { updateQuestProgress, acceptQuest, completeQuest } = useQuestHandlers({
    addFloatingText,
    gainExp,
  });

  const { buyItem, buyFood, sellItem, craftItem } = useShopHandlers({
    addFloatingText,
    unlockAchievement: (id) => achievementsRef.current.unlock(id),
    onTradeSold: (itemId, region) => updateQuestProgress('trade', itemId, { region }),
  });

  const {
    travelState,
    travelProgress,
    activeEncounter,
    selectRegion,
    cancelTravel,
    handleEncounterFight,
    handleEncounterCollectReward,
    handleEncounterFlee,
    handleEncounterBuyItem,
    closeEncounter,
  } = useTravelSystem({
    addFloatingText,
    gainExp,
    unlockAchievement: (id) => achievementsRef.current.unlock(id),
    onShowRegionInfo: () => setShowRegionInfo(true),
    onArrival: () => {
      setMonsters([]);
      setBoss(null);
      setDroppedItems([]);
      setProjectiles([]);
    },
  });

  const {
    selectedSkill,
    setSelectedSkill,
    skillCooldowns,
    lockedTargetUid,
    setLockedTargetUid,
    castSkillOnMonster,
    cycleTarget,
    attackLockedTarget,
  } = useCombatHandlers({ addFloatingText });

  const startGame = useCallback(() => {
    primeAudio();
    setGameState(GAME_STATES.CHARACTER_CREATE);
  }, []);

  const createCharacter = useCallback((name: string, str: number, agi: number, int: number, homeRegion: string) => {
    const eq: Equipment = { ...EMPTY_EQUIPMENT };
    const derived = calculateDerivedStats(str, agi, int, eq);
    const newPlayer: Player = {
      x: 500, y: 400, targetX: 500, targetY: 400,
      maxHp: 100 + derived.maxHpBonus, hp: 100 + derived.maxHpBonus,
      maxMp: 80 + derived.maxMpBonus, mp: 80 + derived.maxMpBonus,
      level: 1, exp: 0, expToLevel: 100,
      attack: derived.attack, defense: derived.defense,
      magic: derived.magic, speed: derived.speed,
      critChance: derived.critChance, critDamage: derived.critDamage,
      gold: 100,
      str, agi, int,
      statPoints: 0,
      name, homeRegion,
      food: 20,
      maxWeight: derived.maxWeight,
      currentWeight: 0,
      skillMastery: {},
    };

    setPlayer(newPlayer);
    setCurrentRegion(homeRegion);
    setMap(generateTownMap(homeRegion));
    setMonsters([]);
    setBoss(null);
    setProjectiles([]);
    setDroppedItems([]);
    setInventory([]);
    setEquipment(eq);
    setDungeonLevel(1);
    setMercenaries([]);
    setClearedSubRegions([]);
    setUnlockedRegions(['portugal', 'spain']);
    resetQuestProgress();
    achievementsRef.current.restore([]);
    setGameState(GAME_STATES.WORLD_MAP);
  }, []);

  const enterTown = useCallback(() => {
    setMap(generateTownMap(currentRegion));
    setPlayer(prev => ({ ...prev, x: 500, y: 400, targetX: 500, targetY: 400 }));
    setMonsters([]);
    setBoss(null);
    setDroppedItems([]);
    setProjectiles([]);
    setShowRegionInfo(false);
    setGameState(GAME_STATES.TOWN);
  }, [currentRegion]);

  const enterDungeon = useCallback((subRegionId?: string) => {
    const spawn = REGION_SPAWNS[currentRegion] || REGION_SPAWNS.portugal;
    const ngPlus = useWorldStore.getState().ngPlusLevel;
    setCurrentSubRegion(subRegionId);

    if (dungeonLevel % 3 === 0 && spawn.boss) {
      setMap(generateBossMap());
      const bossMonster = spawnBoss(currentRegion, dungeonLevel, ngPlus);
      setBoss(bossMonster);
      setMonsters(bossMonster ? [bossMonster] : []);
      setDroppedItems([]);
      setGameState(GAME_STATES.BOSS);
    } else {
      const newMap = generateDungeonMap(dungeonLevel, currentRegion);
      setMap(newMap);
      setMonsters(spawnMonsters(currentRegion, dungeonLevel, subRegionId, ngPlus));
      setBoss(null);
      setDroppedItems(spawnChests(newMap, dungeonLevel));
      setGameState(GAME_STATES.DUNGEON);
    }

    setPlayer(prev => ({ ...prev, x: 150, y: 150, targetX: 150, targetY: 150 }));
    setProjectiles([]);
    setShowSubRegionSelect(false);
  }, [currentRegion, dungeonLevel]);

  const returnToTown = useCallback(() => {
    setMap(generateTownMap(currentRegion));
    setPlayer(prev => ({ ...prev, x: 500, y: 400, targetX: 500, targetY: 400, hp: prev.maxHp, mp: prev.maxMp }));
    setMonsters([]);
    setBoss(null);
    setDroppedItems([]);
    setProjectiles([]);
    setGameState(GAME_STATES.TOWN);
  }, [currentRegion]);

  const returnToWorldMap = useCallback(() => {
    setPlayer(prev => ({ ...prev, hp: prev.maxHp, mp: prev.maxMp }));
    setGameState(GAME_STATES.WORLD_MAP);
  }, []);

  const nextDungeonLevel = useCallback(() => {
    setDungeonLevel(prev => prev + 1);
    addFloatingText(player.x, player.y - 50, '던전 클리어!', '#ffd700');
    achievementsRef.current.unlock('first_dungeon_clear');

    // Mark sub-region as cleared
    if (currentSubRegion) {
      setClearedSubRegions(prev => [...new Set([...prev, currentSubRegion])]);
    }

    returnToTown();
  }, [returnToTown, addFloatingText, player.x, player.y, currentSubRegion]);


  const handleGameClick = useCallback((x: number, y: number) => {
    if (gameState === GAME_STATES.TOWN) {
      const npcs = getNPCsForRegion(currentRegion);
      for (const npc of npcs) {
        if (getDistance(x, y, npc.x, npc.y) < 30) {
          if (npc.type === 'shop') setShowShop(true);
          else if (npc.type === 'crafting') setShowCrafting(true);
          else if (npc.type === 'quest') setShowQuests(true);
          else if (npc.type === 'mercenary') setShowMercenary(true);
          return;
        }
      }
      const { tileX, tileY } = pixelToTile(x, y);
      if (map[tileY]?.[tileX] === 2) {
        // Show sub-region selection
        const region = REGIONS[currentRegion];
        if (region?.subRegions.length > 0) {
          setShowSubRegionSelect(true);
        } else {
          enterDungeon();
        }
        return;
      }
    }

    if (gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) {
      const { tileX, tileY } = pixelToTile(x, y);
      if (map[tileY]?.[tileX] === 2) {
        if (monsters.length === 0) nextDungeonLevel();
        else returnToTown();
        return;
      }

      for (const item of droppedItems) {
        if (getDistance(x, y, item.x, item.y) < 25) {
          if (item.type === 'chest') {
            const { drops, gold, exp } = generateChestLoot(item, dungeonLevel);
            setPlayer(prev => ({ ...prev, gold: prev.gold + gold }));
            if (exp > 0) gainExp(exp);
            addFloatingText(item.x, item.y - 10, `+${gold} Gold`, '#ffd700');
            if (exp > 0) addFloatingText(item.x, item.y + 10, `+${exp} EXP`, '#9b59b6');
            setDroppedItems(prev => [...prev.filter(d => d.uid !== item.uid), ...drops]);
            playSfx('pickup');
            triggerShake(0.15, 120);
            return;
          }
          if (item.type === 'gold') {
            setPlayer(prev => ({ ...prev, gold: prev.gold + (item.amount || 0) }));
            addFloatingText(item.x, item.y, `+${item.amount} Gold`, '#ffd700');
            playSfx('pickup');
          } else if (inventory.length < GAME_CONFIG.INVENTORY_MAX_SLOTS) {
            // Weight check
            const itemWeight = item.weight || ITEMS[item.id || '']?.weight || 0;
            if (player.currentWeight + itemWeight > player.maxWeight) {
              addFloatingText(item.x, item.y, '무게 초과!', '#e74c3c');
              return;
            }
            const newItem = { ...item, uid: `inv_${Date.now()}`, weight: itemWeight } as InventoryItem;
            setInventory(prev => [...prev, newItem]);
            addFloatingText(item.x, item.y, `${item.name} 획득!`, '#fff');
            playSfx('pickup');
          }
          setDroppedItems(prev => prev.filter(i => i.uid !== item.uid));
          return;
        }
      }

      for (const monster of monsters) {
        if (getDistance(x, y, monster.x, monster.y) < monster.size) {
          setLockedTargetUid(monster.uid);
          castSkillOnMonster(monster);
          return;
        }
      }
    }
  }, [gameState, map, monsters, droppedItems, player, inventory, currentRegion, dungeonLevel, enterDungeon, returnToTown, nextDungeonLevel, addFloatingText, gainExp, castSkillOnMonster, setLockedTargetUid]);

  const ngPlusLevel = useNgPlusLevel();

  const buildSaveData = useCallback(() => {
    return createSaveData(
      player, inventory, equipment, questProgress, currentRegion,
      dungeonLevel, unlockedRegions, selectedSkill, mercenaries, clearedSubRegions,
      achievements.unlocked, 0, captureGameThumbnail(), ngPlusLevel,
    );
  }, [player, inventory, equipment, questProgress, currentRegion, dungeonLevel, unlockedRegions, selectedSkill, mercenaries, clearedSubRegions, achievements.unlocked, ngPlusLevel]);

  const applyLoadedData = useCallback((data: SaveData) => {
    const loadedPlayer: Player = {
      ...data.player,
      x: 500, y: 400, targetX: 500, targetY: 400,
    };
    setPlayer(loadedPlayer);
    setInventory(data.inventory);
    setEquipment(data.equipment);
    setQuestProgress(data.questProgress);
    setCurrentRegion(data.currentRegion);
    setDungeonLevel(data.dungeonLevel);
    setUnlockedRegions(data.unlockedRegions);
    setSelectedSkill(data.selectedSkill);
    setMercenaries(data.mercenaries || []);
    setClearedSubRegions(data.clearedSubRegions || []);
    setNgPlusLevel(data.ngPlusLevel ?? 0);
    achievements.restore(data.achievements || []);
    setMonsters([]);
    setBoss(null);
    setProjectiles([]);
    setDroppedItems([]);
    setMap(generateTownMap(data.currentRegion));
    setGameState(GAME_STATES.TOWN);
  }, [achievements, setSelectedSkill]);

  const {
    slotsMode,
    setSlotsMode,
    handleSaveGame,
    handleLoadGame,
    handleSaveToSlot,
    handleLoadFromSlot,
    handleDeleteSlot,
  } = useSaveSystem({
    gameState,
    autoSaveEnabled,
    autoSaveIntervalMinutes,
    buildSaveData,
    applyLoadedData,
    achievements,
  });

  const anyModalOpen =
    showInventory || showQuests || showShop || showCrafting ||
    showRegionInfo || showMercenary || showSkillTree || showSettings || !!slotsMode ||
    showSubRegionSelect || !!activeEncounter;

  const togglePause = useCallback(() => {
    setPaused(p => !p);
  }, []);

  // Reset pause on game state transitions out of in-game scenes
  useEffect(() => {
    if (gameState !== GAME_STATES.TOWN && gameState !== GAME_STATES.DUNGEON && gameState !== GAME_STATES.BOSS) {
      setPaused(false);
    }
  }, [gameState]);

  const handleReturnToMenuFromPause = useCallback(() => {
    setPaused(false);
    setGameState(GAME_STATES.MENU);
  }, []);

  // 자동 루팅 정책: 골드 + 비-상자 일반 아이템(인벤토리 여유 + 무게 가능 시).
  // 상자/장비는 명시적 클릭 유도. 무게 초과 / 인벤토리 풀이면 픽업 안 함(필드에 남김).
  const playerRefForLoot = useRef(player);
  playerRefForLoot.current = player;
  const inventoryRefForLoot = useRef(inventory);
  inventoryRefForLoot.current = inventory;

  const onAutoLoot = useCallback((item: DroppedItem): boolean => {
    if (item.type === 'chest') return false;
    if (item.type === 'gold') {
      const amount = item.amount || 0;
      setPlayer(prev => ({ ...prev, gold: prev.gold + amount }));
      addFloatingText(item.x, item.y, `+${amount} Gold`, '#ffd700');
      playSfx('pickup');
      setDroppedItems(prev => prev.filter(i => i.uid !== item.uid));
      return true;
    }
    // 일반 아이템: 장비도 포함해 인벤토리/무게가 허용되면 자동 픽업
    if (inventoryRefForLoot.current.length >= GAME_CONFIG.INVENTORY_MAX_SLOTS) return false;
    const itemWeight = item.weight || ITEMS[item.id || '']?.weight || 0;
    const p = playerRefForLoot.current;
    if (p.currentWeight + itemWeight > p.maxWeight) return false;
    const newItem = { ...item, uid: `inv_${Date.now()}_${Math.random()}`, weight: itemWeight } as InventoryItem;
    setInventory(prev => [...prev, newItem]);
    addFloatingText(item.x, item.y, `${item.name} 획득!`, '#fff');
    playSfx('pickup');
    setDroppedItems(prev => prev.filter(i => i.uid !== item.uid));
    return true;
  }, [addFloatingText]);

  useKeyboardInput({
    gameState,
    playerLevel: player.level,
    returnToWorldMap,
    setShowInventory,
    setShowQuests,
    setShowShop,
    setShowCrafting,
    setShowRegionInfo,
    setShowSkillTree,
    setSelectedSkill,
    onSaveGame: handleSaveGame,
    anyModalOpen,
    togglePause,
    cycleTarget,
    attackLockedTarget,
  });

  useGameLoop({
    gameState,
    map,
    player,
    dungeonLevel,
    mercenaries,
    pressedKeys,
    paused,
    autoLootRadius: GAME_CONFIG.AUTO_LOOT_RADIUS,
    setFloatingTexts,
    gainExp,
    addFloatingText,
    updateQuestProgress,
    onMonsterKilled: (m) => {
      achievementsRef.current.unlock('first_kill');
      if (m.isBoss) achievementsRef.current.unlock('first_boss_kill');
    },
    onAutoLoot,
  });

  // Canvas renderer replaced by Three.js SceneRoot in JSX

  // Item/quest/shop/craft handlers
  const useItem = (uid: string) => {
    const item = inventory.find(i => i.uid === uid);
    if (!item) return;
    if (item.type === 'consumable') {
      if (item.effect === 'hp') setPlayer(prev => ({ ...prev, hp: Math.min(prev.maxHp, prev.hp + (item.value || 0)) }));
      else if (item.effect === 'mp') setPlayer(prev => ({ ...prev, mp: Math.min(prev.maxMp, prev.mp + (item.value || 0)) }));
      else if (item.effect === 'both') setPlayer(prev => ({ ...prev, hp: Math.min(prev.maxHp, prev.hp + (item.value || 0)), mp: Math.min(prev.maxMp, prev.mp + (item.value || 0)) }));
      setInventory(prev => prev.filter(i => i.uid !== uid));
      addFloatingText(player.x, player.y, `+${item.value}`, item.effect === 'hp' ? '#e74c3c' : '#3498db');
    } else if (item.type === 'food') {
      setPlayer(prev => ({ ...prev, food: prev.food + (item.foodValue || 0) }));
      setInventory(prev => prev.filter(i => i.uid !== uid));
      addFloatingText(player.x, player.y, `+${item.foodValue} 식량`, '#2ecc71');
    } else if (item.type === 'equipment') {
      const slot = item.slot!;
      const prev = equipment[slot];
      setEquipment(e => ({ ...e, [slot]: item }));
      setInventory(inv => inv.filter(i => i.uid !== uid));
      if (prev) setInventory(inv => [...inv, { ...prev, uid: `inv_${Date.now()}` }]);

      // Recalculate derived stats
      const newEq = { ...equipment, [slot]: item };
      setPlayer(p => recalcDerivedStats(p, newEq));
    }
  };

  const investSkillNode = useCallback((skillId: string, kind: SkillNodeKind) => {
    setPlayer((prev) => {
      const next = investNodePoint(prev, skillId, kind);
      if (!next) return prev;
      return { ...prev, skillTreeAllocations: next };
    });
  }, []);

  const region = REGIONS[currentRegion];

  const totalAchievements = Object.keys(ACHIEVEMENTS).length;

  return (
    <div className="w-screen h-screen overflow-hidden bg-age-navy">
      <ToastStack toasts={achievements.toasts} onDismiss={achievements.dismissToast} />

      {gameState === GAME_STATES.MENU && (
        <div className="w-full h-full flex items-center justify-center">
          <MenuScreen onStartGame={startGame} onLoadGame={handleLoadGame} />
        </div>
      )}

      {gameState === GAME_STATES.CHARACTER_CREATE && (
        <div className="w-full h-full">
          <CharacterCreateScreen onCreateCharacter={createCharacter} />
        </div>
      )}

      {gameState === GAME_STATES.TRAVELING && travelState && (
        <div className="w-full h-full">
          <Suspense fallback={<LazyFallback message="항해 준비 중..." />}>
            <TravelScreen
              travelState={travelState}
              player={player}
              progress={travelProgress}
              onCancel={cancelTravel}
            />
          </Suspense>
          {activeEncounter && (
            <TravelEncounterModal
              encounter={activeEncounter}
              playerPower={player.attack + player.defense + player.magic}
              playerGold={player.gold}
              onFight={handleEncounterFight}
              onFlee={() => { handleEncounterFlee(); closeEncounter(); }}
              onCollectReward={handleEncounterCollectReward}
              onBuyItem={handleEncounterBuyItem}
              onClose={closeEncounter}
            />
          )}
        </div>
      )}

      {gameState === GAME_STATES.WORLD_MAP && (
        <div className="w-full h-full flex flex-col">
          <div className="flex justify-between items-center gap-3 p-3 shrink-0">
            <div className="panel-parchment rounded-md px-3 py-2 text-age-paper text-sm flex items-center gap-3">
              <span className="text-age-gold font-bold">{player.name} Lv.{player.level}</span>
              <span className="text-age-gold/40">|</span>
              <span className="text-age-gold">{'\uD83D\uDCB0'} {player.gold}</span>
              <span className="text-age-gold/40">|</span>
              <span className="text-age-leaf">{'\uD83C\uDF5E'} {Math.floor(player.food)}</span>
            </div>
            <div className="flex gap-2">
              <button onClick={handleSaveGame} className="btn-age btn-age-primary text-xs px-3 py-1.5">{'\uD83D\uDCBE'} 저장 F5</button>
              <button onClick={() => setSlotsMode('save')} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\uD83D\uDCC1'} 슬롯</button>
              <button onClick={() => setShowInventory(true)} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\uD83C\uDF92'} 인벤토리</button>
              <button onClick={() => setShowQuests(true)} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\uD83D\uDCDC'} 퀘스트</button>
              <button onClick={() => setShowSettings(true)} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\u2699\uFE0F'} 설정</button>
            </div>
          </div>
          <div className="flex-1 min-h-0 rounded-md overflow-hidden border-2 border-age-gold/50 shadow-panel mx-3 mb-3">
            <Suspense fallback={<LazyFallback message="해도 펼치는 중..." />}>
              <WorldMap onRegionSelect={selectRegion} unlockedRegions={unlockedRegions} currentRegion={currentRegion} playerLevel={player.level} />
            </Suspense>
          </div>

          {showRegionInfo && region && (
            <RegionInfoModal region={region} clearedSubRegions={clearedSubRegions} onEnterTown={enterTown} onClose={() => setShowRegionInfo(false)} />
          )}
        </div>
      )}

      {gameState === GAME_STATES.GAMEOVER && (
        <div className="w-full h-full flex items-center justify-center">
          <GameOverScreen region={region} dungeonLevel={dungeonLevel} player={player} onRestart={startGame} />
        </div>
      )}

      {(gameState === GAME_STATES.TOWN || gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && (
        <div className="w-full h-full bg-black flex items-center justify-center">
          <div
            className="relative"
            style={{
              width: 'min(100vw, calc(100vh * 5 / 3))',
              height: 'min(100vh, calc(100vw * 3 / 5))',
            }}
          >
            <Suspense fallback={<LazyFallback message="장면 로딩..." />}>
              <SceneRoot
                gameState={gameState}
                map={map}
                player={player}
                monsters={monsters}
                projectiles={projectiles}
                droppedItems={droppedItems}
                floatingTexts={floatingTexts}
                currentRegion={currentRegion}
                lockedTargetUid={lockedTargetUid}
                skillRange={SKILLS[selectedSkill]?.range || 0}
                onClickGround={handleGameClick}
              />
            </Suspense>

            <HUD player={player} region={region} gameState={gameState} dungeonLevel={dungeonLevel} onAllocateStat={allocateStat} />

            <QuestTracker questProgress={questProgress} />

            {(gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && (
              <LowHpVignette player={player} />
            )}

            {(gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && (
              <div className="absolute top-2 right-2 panel-parchment border border-age-gold/40 px-3 py-1.5 rounded-md text-age-paper text-xs">
                {boss ? <span className="text-age-blood font-bold">{'\uD83D\uDC51'} BOSS: {boss.name}</span> : <span className="text-age-blood">{'\u2694\uFE0F'} {monsters.length}마리</span>}
              </div>
            )}

            {(gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && (
              <Minimap map={map} player={player} monsters={monsters} boss={boss} />
            )}

            {boss && <BossHealthBar boss={boss} />}

            <SkillBar
              player={player}
              selectedSkill={selectedSkill}
              skillCooldowns={skillCooldowns}
              gameState={gameState}
              setSelectedSkill={setSelectedSkill}
              setShowInventory={setShowInventory}
              setShowQuests={setShowQuests}
              setShowMercenary={setShowMercenary}
              returnToWorldMap={returnToWorldMap}
            />

            {gameState === GAME_STATES.TOWN && (
              <>
                <div className="absolute top-2 right-2 z-10 flex gap-2">
                  <button onClick={handleSaveGame} className="btn-age btn-age-primary text-xs px-3 py-1.5">{'\uD83D\uDCBE'} 저장 F5</button>
                  <button onClick={() => setSlotsMode('save')} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\uD83D\uDCC1'} 슬롯</button>
                  <button onClick={() => setShowSettings(true)} className="btn-age btn-age-ghost text-xs px-3 py-1.5">{'\u2699\uFE0F'} 설정</button>
                </div>
                <div className="absolute bottom-20 left-1/2 -translate-x-1/2 panel-parchment border border-age-gold/30 px-4 py-2 rounded-md text-age-paper/70 text-xs whitespace-nowrap">NPC 클릭: 상점/제작/퀘스트/용병 · 포탈: 던전 입장 · M: 세계 지도</div>
              </>
            )}

            {(gameState === GAME_STATES.DUNGEON || gameState === GAME_STATES.BOSS) && monsters.length === 0 && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 panel-parchment border-2 border-age-gold/70 shadow-gold px-6 py-4 rounded-md text-2xl font-bold text-age-gold animate-glow-pulse">{'\uD83C\uDF89'} 클리어! 포탈로 이동</div>
            )}

            {/* Sub-region selection */}
            {showSubRegionSelect && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50">
                <Panel layout="inline" title="탐험 지역 선택" icon={'\u2694\uFE0F'} onClose={() => setShowSubRegionSelect(false)} maxWidth="min-w-[320px]">
                  <div className="space-y-2 mb-3">
                    {REGIONS[currentRegion]?.subRegions.map(id => {
                      const sub = SUB_REGIONS[id];
                      if (!sub) return null;
                      const cleared = clearedSubRegions.includes(id);
                      return (
                        <button key={id} onClick={() => enterDungeon(id)}
                          className="w-full p-3 rounded border border-age-gold/30 bg-age-navy/70 hover:border-age-gold/80 hover:bg-age-navy text-left transition-all">
                          <div className="flex items-center gap-2">
                            <span className={cleared ? 'text-age-leaf' : 'text-age-paper/60'}>{cleared ? '\u2705' : '\u2694\uFE0F'}</span>
                            <div>
                              <div className="text-age-paper text-sm font-bold">{sub.name}</div>
                              <div className="text-age-paper/60 text-xs">{sub.description}</div>
                            </div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                  <Button size="sm" fullWidth variant="ghost" onClick={() => enterDungeon()} className="mb-2">
                    일반 던전 (Lv.{dungeonLevel})
                  </Button>
                  <Button size="sm" fullWidth variant="danger" onClick={() => setShowSubRegionSelect(false)}>
                    취소
                  </Button>
                </Panel>
              </div>
            )}

            {showInventory && (
              <InventoryModal inventory={inventory} player={player} equipment={equipment} onUseItem={useItem} onClose={() => setShowInventory(false)} />
            )}

            {showQuests && (
              <QuestModal questProgress={questProgress} player={player} onAcceptQuest={acceptQuest} onCompleteQuest={completeQuest} onClose={() => setShowQuests(false)} />
            )}

            {showShop && (
              <ShopModal player={player} currentRegion={currentRegion} inventory={inventory} onBuyItem={buyItem} onBuyFood={buyFood} onSellItem={sellItem} onClose={() => setShowShop(false)} />
            )}

            {showCrafting && (
              <CraftingModal player={player} inventory={inventory} currentRegion={currentRegion} onCraftItem={craftItem} onClose={() => setShowCrafting(false)} />
            )}

            {showMercenary && (
              <MercenaryModal player={player} mercenaries={mercenaries} currentRegion={currentRegion} onHire={hireMercenary} onFire={fireMercenary} onClose={() => setShowMercenary(false)} />
            )}

            {showSkillTree && (
              <SkillTreeModal player={player} onInvest={investSkillNode} onClose={() => setShowSkillTree(false)} />
            )}

            {paused && !anyModalOpen && (
              <PauseMenu
                onResume={() => setPaused(false)}
                onSave={() => { handleSaveGame(); }}
                onOpenSettings={() => { setShowSettings(true); }}
                onReturnToMenu={handleReturnToMenuFromPause}
              />
            )}

            {showTutorial && (
              <TutorialOverlay onClose={() => setShowTutorial(false)} />
            )}

            <VirtualJoystick pressedKeys={pressedKeys} />
          </div>
        </div>
      )}

      {showSettings && (
        <SettingsModal
          autoSaveEnabled={autoSaveEnabled}
          autoSaveIntervalMinutes={autoSaveIntervalMinutes}
          unlockedAchievements={achievements.unlocked}
          totalAchievements={totalAchievements}
          onToggleAutoSave={() => setAutoSaveEnabled(v => !v)}
          onSetAutoSaveInterval={setAutoSaveIntervalMinutes}
          onOpenSlots={() => { setShowSettings(false); setSlotsMode('save'); }}
          onExport={handleSaveGame}
          onImport={handleLoadGame}
          onClose={() => setShowSettings(false)}
        />
      )}

      {slotsMode && (
        <SaveSlotsModal
          mode={slotsMode}
          slots={listSlots()}
          onSelect={slotsMode === 'save' ? handleSaveToSlot : handleLoadFromSlot}
          onDelete={handleDeleteSlot}
          onClose={() => setSlotsMode(null)}
        />
      )}
    </div>
  );
}
