import type { AffixType, ItemAffix, ItemRarityKey } from '../types';

/**
 * 등급별 affix 개수.
 * COMMON은 옵션 없음, LEGENDARY는 4개까지.
 */
export const AFFIX_COUNT_BY_RARITY: Record<ItemRarityKey, number> = {
  COMMON: 0,
  UNCOMMON: 1,
  RARE: 2,
  EPIC: 3,
  LEGENDARY: 4,
};

/**
 * affix별 (base, perLevel, type) — 던전 레벨에 비례해 강도 스케일.
 * value = round(base + perLevel * level) + 0..variance(20%)
 */
const AFFIX_TABLE: Record<AffixType, { base: number; perLevel: number; label: string }> = {
  attack: { base: 2, perLevel: 0.6, label: '공격력' },
  defense: { base: 2, perLevel: 0.5, label: '방어력' },
  magic: { base: 2, perLevel: 0.6, label: '마법력' },
  maxHp: { base: 10, perLevel: 4, label: '최대 HP' },
  maxMp: { base: 8, perLevel: 3, label: '최대 MP' },
  speed: { base: 0.1, perLevel: 0.02, label: '이동속도' },
  critChance: { base: 0.01, perLevel: 0.003, label: '치명타 확률' },
};

const ALL_AFFIX_TYPES: AffixType[] = Object.keys(AFFIX_TABLE) as AffixType[];

/**
 * 새로 드롭된 장비 아이템에 옵션을 롤한다.
 *
 * - 등급에 따라 개수 결정 (AFFIX_COUNT_BY_RARITY)
 * - 같은 타입은 중복 안 됨 (Fisher-Yates 무복원 추출)
 * - 강도 = AFFIX_TABLE의 base + perLevel * dungeonLevel, ±20% 변동
 * - rng 주입 가능 (테스트)
 */
export function rollAffixes(
  rarity: ItemRarityKey,
  dungeonLevel: number,
  rng: () => number = Math.random,
): ItemAffix[] {
  const count = AFFIX_COUNT_BY_RARITY[rarity];
  if (count <= 0) return [];

  // Sample `count` distinct affix types
  const pool = [...ALL_AFFIX_TYPES];
  const picks: AffixType[] = [];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = Math.floor(rng() * pool.length);
    picks.push(pool[idx]);
    pool.splice(idx, 1);
  }

  return picks.map((type) => {
    const cfg = AFFIX_TABLE[type];
    const raw = cfg.base + cfg.perLevel * Math.max(1, dungeonLevel);
    const variance = 0.8 + rng() * 0.4; // 0.8..1.2
    const value = type === 'speed' || type === 'critChance'
      ? Math.round(raw * variance * 100) / 100 // 2 decimals for fractional stats
      : Math.max(1, Math.round(raw * variance));
    return { type, value };
  });
}

/** affix 한 줄을 UI에 표시할 한글 문자열로 포맷 */
export function formatAffix(affix: ItemAffix): string {
  const cfg = AFFIX_TABLE[affix.type];
  if (affix.type === 'critChance') {
    return `${cfg.label} +${(affix.value * 100).toFixed(1)}%`;
  }
  if (affix.type === 'speed') {
    return `${cfg.label} +${affix.value.toFixed(2)}`;
  }
  return `${cfg.label} +${affix.value}`;
}
