import { create } from 'zustand';
import type { Player } from '../types';
import { STAT_CONFIG } from '../constants/config';

/**
 * 플레이어 상태를 보관하는 Zustand store.
 *
 * 마이그레이션 호환을 위해 React useState와 동일한 시그니처의 setPlayer를 노출한다:
 *   setPlayer(prev => ({ ...prev, hp: prev.hp - 10 }))
 *   setPlayer({ ...newPlayer })
 *
 * 컴포넌트는 다음 중 하나로 구독한다:
 *   const player = usePlayer();
 *   const setPlayer = useSetPlayer();
 *   const hp = usePlayerStore(s => s.player.hp); // selector — hp만 변할 때만 리렌더
 */
export function createDefaultPlayer(): Player {
  return {
    x: 500,
    y: 400,
    targetX: 500,
    targetY: 400,
    maxHp: 100,
    hp: 100,
    maxMp: 80,
    mp: 80,
    level: 1,
    exp: 0,
    expToLevel: 100,
    attack: 15,
    defense: 5,
    magic: 10,
    speed: 3,
    critChance: STAT_CONFIG.BASE_CRIT_CHANCE + STAT_CONFIG.STARTING_AGI * STAT_CONFIG.AGI_TO_CRIT,
    critDamage: STAT_CONFIG.BASE_CRIT_DAMAGE,
    gold: 100,
    str: STAT_CONFIG.STARTING_STR,
    agi: STAT_CONFIG.STARTING_AGI,
    int: STAT_CONFIG.STARTING_INT,
    statPoints: 0,
    name: '선장',
    homeRegion: 'portugal',
    food: 20,
    maxWeight: STAT_CONFIG.BASE_CARRY_WEIGHT + STAT_CONFIG.STARTING_STR * STAT_CONFIG.STR_TO_WEIGHT,
    currentWeight: 0,
    skillMastery: {},
  };
}

type SetPlayerArg = Player | ((prev: Player) => Player);

interface PlayerStore {
  player: Player;
}

export const usePlayerStore = create<PlayerStore>(() => ({
  player: createDefaultPlayer(),
}));

/**
 * Plain function (not a hook) — exported so callers can use it inside useCallback
 * without listing it in deps. Same React.useState dispatch contract:
 *   setPlayer(newPlayer)
 *   setPlayer(prev => ({ ...prev, hp: prev.hp - 10 }))
 */
export const setPlayer = (arg: SetPlayerArg): void => {
  usePlayerStore.setState((state) => ({
    player: typeof arg === 'function' ? (arg as (p: Player) => Player)(state.player) : arg,
  }));
};

/** Subscribe to the full player object. Prefer narrower selectors in leaf components. */
export const usePlayer = () => usePlayerStore((s) => s.player);
