import { useCallback, useRef } from 'react';
import { QUESTS } from '../constants/quests';
import { QUEST_STATUS } from '../constants/config';
import { ITEMS } from '../constants/items';
import { usePlayerStore, setPlayer } from '../stores/usePlayerStore';
import { setInventory } from '../stores/useInventoryStore';
import { setQuestProgress } from '../stores/useQuestStore';

/**
 * 퀘스트 도메인 훅: 수락 · 완료(보상 수령) · 진행도 갱신.
 *
 * - updateQuestProgress(type, target): 처치/수집 이벤트 발생 시 자동 진행 갱신.
 *   목표 달성 시 상태를 COMPLETED로 전환하고 플로팅 텍스트 출력.
 * - acceptQuest(qid): AVAILABLE → ACTIVE
 * - completeQuest(qid): COMPLETED 보상(exp/gold/items) 지급 후 REWARDED로 마감
 */
export interface QuestHandlersHooks {
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
  gainExp: (amount: number) => void;
}

export function useQuestHandlers(hooks: QuestHandlersHooks) {
  const hooksRef = useRef(hooks);
  hooksRef.current = hooks;

  /**
   * 진행도 갱신. type/target이 일치하는 ACTIVE 퀘스트를 +1.
   * trade 타입은 추가로 region context를 받아 quest.destinationRegion과 일치해야 진행.
   */
  const updateQuestProgress = useCallback((type: string, target: string, context?: { region?: string }) => {
    const player = usePlayerStore.getState().player;
    setQuestProgress((prev) => {
      const updated = { ...prev };
      let completedAny = false;
      for (const [qid, quest] of Object.entries(QUESTS)) {
        if (updated[qid]?.status !== QUEST_STATUS.ACTIVE) continue;
        if (quest.type !== type) continue;
        if (quest.target !== target) continue;
        // trade quests gate progress on the current selling region matching destinationRegion
        if (quest.destinationRegion && context?.region !== quest.destinationRegion) continue;
        updated[qid] = {
          ...updated[qid],
          currentCount: Math.min(updated[qid].currentCount + 1, quest.targetCount),
        };
        if (updated[qid].currentCount >= quest.targetCount) {
          updated[qid] = { ...updated[qid], status: QUEST_STATUS.COMPLETED };
          completedAny = true;
        }
      }
      if (completedAny) {
        hooksRef.current.addFloatingText(player.x, player.y - 50, '퀘스트 완료!', '#ffd700');
      }
      return updated;
    });
  }, []);

  const acceptQuest = useCallback((qid: string) => {
    const player = usePlayerStore.getState().player;
    setQuestProgress((prev) => ({ ...prev, [qid]: { ...prev[qid], status: QUEST_STATUS.ACTIVE } }));
    hooksRef.current.addFloatingText(player.x, player.y - 30, '퀘스트 수락!', '#ffd700');
  }, []);

  const completeQuest = useCallback((qid: string) => {
    const player = usePlayerStore.getState().player;
    const quest = QUESTS[qid];
    if (!quest) return;
    if (quest.rewards.exp) hooksRef.current.gainExp(quest.rewards.exp);
    if (quest.rewards.gold) {
      setPlayer((p) => ({ ...p, gold: p.gold + quest.rewards.gold! }));
    }
    if (quest.rewards.items) {
      for (const itemId of quest.rewards.items) {
        const item = ITEMS[itemId];
        if (item) {
          setInventory((inv) => [...inv, { ...item, uid: `inv_${Date.now()}_${Math.random()}` }]);
        }
      }
    }
    setQuestProgress((prev) => ({
      ...prev,
      [qid]: { ...prev[qid], status: QUEST_STATUS.REWARDED },
    }));
    hooksRef.current.addFloatingText(player.x, player.y, '보상 획득!', '#ffd700');
  }, []);

  return { updateQuestProgress, acceptQuest, completeQuest };
}
