import { useEffect } from 'react';

export interface ToastData {
  id: number;
  title: string;
  message?: string;
  icon?: string;
  tone?: 'info' | 'success' | 'warn' | 'achievement';
  duration?: number;
}

const TONE: Record<NonNullable<ToastData['tone']>, string> = {
  info:        'border-age-sea/60',
  success:     'border-age-leaf/60',
  warn:        'border-age-ember/60',
  achievement: 'border-age-gold shadow-gold animate-glow-pulse',
};

interface ToastProps {
  toast: ToastData;
  onDismiss: (id: number) => void;
}

function Toast({ toast, onDismiss }: ToastProps) {
  useEffect(() => {
    const id = window.setTimeout(() => onDismiss(toast.id), toast.duration ?? 3200);
    return () => window.clearTimeout(id);
  }, [toast.id, toast.duration, onDismiss]);

  return (
    <div
      className={`panel-parchment border ${TONE[toast.tone ?? 'info']} rounded-md px-3 py-2 min-w-[220px] max-w-[320px] animate-toast-in`}
    >
      <div className="flex items-start gap-2">
        {toast.icon && <span className="text-xl leading-none mt-0.5">{toast.icon}</span>}
        <div className="flex-1">
          <div className="text-age-gold font-bold text-sm leading-tight">{toast.title}</div>
          {toast.message && (
            <div className="text-age-paper/80 text-xs mt-0.5 leading-snug">{toast.message}</div>
          )}
        </div>
      </div>
    </div>
  );
}

interface ToastStackProps {
  toasts: ToastData[];
  onDismiss: (id: number) => void;
}

export default function ToastStack({ toasts, onDismiss }: ToastStackProps) {
  return (
    <div className="pointer-events-none fixed top-3 right-3 z-[60] flex flex-col gap-2">
      {toasts.map(t => (
        <div key={t.id} className="pointer-events-auto">
          <Toast toast={t} onDismiss={onDismiss} />
        </div>
      ))}
    </div>
  );
}
