import type { StatusEffectInstance, StatusApplySpec, SpawnedMonster } from '../types';

/**
 * 상태이상 부여 — 확률 체크 후 새 인스턴스 반환.
 * 같은 타입이 이미 걸려 있으면 remainingMs 갱신(스택 안 함, refresh).
 *
 * 순수 함수: 새 배열 반환, 입력 mutation 없음. rng를 주입 가능하게 해 테스트 가능.
 */
export function applyStatusEffect(
  existing: StatusEffectInstance[] | undefined,
  spec: StatusApplySpec,
  rng: () => number = Math.random,
): StatusEffectInstance[] | undefined {
  const chance = spec.chance ?? 1;
  if (rng() >= chance) return existing;

  const newInst: StatusEffectInstance = {
    type: spec.type,
    remainingMs: spec.durationMs,
    ...(spec.tickDps !== undefined ? { tickDps: spec.tickDps } : {}),
    ...(spec.speedMult !== undefined ? { speedMult: spec.speedMult } : {}),
  };

  if (!existing || existing.length === 0) return [newInst];

  // 같은 타입이 있으면 refresh (max 기간 유지)
  const idx = existing.findIndex((e) => e.type === spec.type);
  if (idx === -1) return [...existing, newInst];

  return existing.map((e, i) =>
    i === idx ? { ...e, remainingMs: Math.max(e.remainingMs, newInst.remainingMs) } : e,
  );
}

/**
 * 시간 진행: 각 effect의 remainingMs를 dtMs만큼 줄이고, tickDps에 비례한 데미지를 누적해 반환.
 * 만료된(remainingMs <= 0) effect는 결과에서 제외.
 *
 * 반환:
 *   - effects: 남은 effect들 (없으면 undefined)
 *   - damageDealt: 이번 tick 합산 데미지 (없으면 0)
 */
export function tickStatusEffects(
  effects: StatusEffectInstance[] | undefined,
  dtMs: number,
): { effects: StatusEffectInstance[] | undefined; damageDealt: number } {
  if (!effects || effects.length === 0) {
    return { effects: undefined, damageDealt: 0 };
  }

  let damage = 0;
  const next: StatusEffectInstance[] = [];
  for (const e of effects) {
    const remaining = e.remainingMs - dtMs;
    if (e.tickDps && e.tickDps > 0) {
      const tickedSec = dtMs / 1000;
      damage += e.tickDps * tickedSec;
    }
    if (remaining > 0) {
      next.push({ ...e, remainingMs: remaining });
    }
  }
  return {
    effects: next.length > 0 ? next : undefined,
    damageDealt: damage,
  };
}

/** 현재 활성 stun이 있으면 true (이동/공격 차단용). */
export function isStunned(monster: Pick<SpawnedMonster, 'statusEffects'>): boolean {
  const fx = monster.statusEffects;
  if (!fx) return false;
  return fx.some((e) => e.type === 'stun' && e.remainingMs > 0);
}

/**
 * 현재 상태이상을 고려한 이동/공격 속도 배율.
 * 모든 slow effect의 speedMult를 곱한다. stun이면 0.
 */
export function getEffectiveSpeedMult(monster: Pick<SpawnedMonster, 'statusEffects'>): number {
  const fx = monster.statusEffects;
  if (!fx || fx.length === 0) return 1;
  if (fx.some((e) => e.type === 'stun' && e.remainingMs > 0)) return 0;
  let mult = 1;
  for (const e of fx) {
    if (e.type === 'slow' && e.speedMult && e.remainingMs > 0) {
      mult *= e.speedMult;
    }
  }
  return mult;
}
