import * as Sentry from '@sentry/react';

/**
 * Sentry 초기화. VITE_SENTRY_DSN 환경변수가 설정되어 있을 때만 활성화.
 * DSN이 없으면 no-op (개발 환경 + DSN 없는 사용자에서 정상 동작).
 *
 * 호출: src/main.tsx에서 ReactDOM.render 이전에 1회.
 */
export function initSentry(): boolean {
  const dsn = import.meta.env.VITE_SENTRY_DSN as string | undefined;
  if (!dsn) {
    if (import.meta.env.DEV) {
      // 개발 환경에서만 알림 — DSN 없어도 정상이지만 누가 깜빡할 수 있음
      console.info('[Sentry] VITE_SENTRY_DSN 미설정 — error tracking off.');
    }
    return false;
  }

  Sentry.init({
    dsn,
    release: import.meta.env.VITE_APP_VERSION as string | undefined,
    environment: import.meta.env.MODE,
    // 게임은 클라이언트 전체 세션 기록은 비용↑ → 에러만 보냄
    integrations: [
      Sentry.browserTracingIntegration(),
    ],
    tracesSampleRate: 0.1,
    // PII 비활성 — 게임 진행도/유저명 등 보내지 않음
    sendDefaultPii: false,
  });
  return true;
}

/** 명시적 에러 캡처 (try/catch 안에서 호출). DSN 미설정 시 no-op. */
export function captureError(err: unknown, context?: Record<string, unknown>): void {
  if (context) {
    Sentry.captureException(err, { extra: context });
  } else {
    Sentry.captureException(err);
  }
}
