/**
 * Web Audio API based SFX layer — no external assets.
 * Each effect is synthesized with oscillators / noise buffers and a short envelope.
 * Master volume + mute state persists to localStorage.
 */

export type SfxKind = 'attack' | 'hit' | 'crit' | 'levelup' | 'pickup' | 'death' | 'kill' | 'drop';

interface AudioSettings {
  enabled: boolean;
  volume: number;
}

const STORAGE_KEY = 'bc_audio';
const DEFAULT_SETTINGS: AudioSettings = { enabled: true, volume: 0.5 };

let ctx: AudioContext | null = null;
let master: GainNode | null = null;
let settings: AudioSettings = loadSettings();
const listeners = new Set<() => void>();

function loadSettings(): AudioSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS };
    const parsed = JSON.parse(raw) as Partial<AudioSettings>;
    return {
      enabled: parsed.enabled !== false,
      volume: Math.max(0, Math.min(1, parsed.volume ?? DEFAULT_SETTINGS.volume)),
    };
  } catch {
    return { ...DEFAULT_SETTINGS };
  }
}

function persist() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(settings)); } catch { /* noop */ }
}

function ensureCtx(): AudioContext | null {
  if (ctx) return ctx;
  const Ctor: typeof AudioContext | undefined = window.AudioContext
    || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!Ctor) return null;
  try {
    ctx = new Ctor();
    master = ctx.createGain();
    master.gain.value = settings.enabled ? settings.volume : 0;
    master.connect(ctx.destination);
    return ctx;
  } catch {
    return null;
  }
}

export function getAudioSettings(): AudioSettings {
  return { ...settings };
}

export function setAudioEnabled(enabled: boolean) {
  settings = { ...settings, enabled };
  if (master) master.gain.value = enabled ? settings.volume : 0;
  persist();
  listeners.forEach(fn => fn());
}

export function setAudioVolume(volume: number) {
  const v = Math.max(0, Math.min(1, volume));
  settings = { ...settings, volume: v };
  if (master && settings.enabled) master.gain.value = v;
  persist();
  listeners.forEach(fn => fn());
}

export function subscribeAudio(fn: () => void): () => void {
  listeners.add(fn);
  return () => { listeners.delete(fn); };
}

function envelope(gain: GainNode, attack: number, decay: number, peak: number) {
  if (!ctx) return;
  const now = ctx.currentTime;
  gain.gain.cancelScheduledValues(now);
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), now + Math.max(0.001, attack));
  gain.gain.exponentialRampToValueAtTime(0.0001, now + attack + decay);
}

function tone(freq: number, type: OscillatorType, attack: number, decay: number, peak = 0.5, sweepTo?: number) {
  const c = ensureCtx();
  if (!c || !master || !settings.enabled) return;
  const osc = c.createOscillator();
  const gain = c.createGain();
  osc.type = type;
  const now = c.currentTime;
  osc.frequency.setValueAtTime(freq, now);
  if (sweepTo !== undefined) {
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, sweepTo), now + attack + decay);
  }
  osc.connect(gain);
  gain.connect(master);
  envelope(gain, attack, decay, peak);
  osc.start(now);
  osc.stop(now + attack + decay + 0.05);
}

function noiseBurst(dur: number, peak = 0.4) {
  const c = ensureCtx();
  if (!c || !master || !settings.enabled) return;
  const buf = c.createBuffer(1, Math.max(1, Math.floor(c.sampleRate * dur)), c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buf;
  const gain = c.createGain();
  src.connect(gain);
  gain.connect(master);
  envelope(gain, 0.005, dur, peak);
  src.start(c.currentTime);
  src.stop(c.currentTime + dur + 0.02);
}

const PLAYERS: Record<SfxKind, () => void> = {
  attack: () => tone(720, 'square', 0.004, 0.09, 0.35, 360),
  hit:    () => { noiseBurst(0.07, 0.32); tone(220, 'triangle', 0.004, 0.1, 0.3, 110); },
  crit:   () => {
    tone(1320, 'square', 0.004, 0.08, 0.4, 1760);
    setTimeout(() => tone(1976, 'square', 0.004, 0.12, 0.4), 60);
  },
  levelup: () => {
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) => setTimeout(() => tone(f, 'triangle', 0.006, 0.2, 0.4), i * 90));
  },
  pickup: () => {
    tone(1568, 'sine', 0.003, 0.1, 0.35);
    setTimeout(() => tone(2093, 'sine', 0.003, 0.1, 0.35), 55);
  },
  death:  () => tone(220, 'sawtooth', 0.01, 0.7, 0.5, 55),
  kill:   () => { noiseBurst(0.15, 0.3); tone(130, 'triangle', 0.005, 0.2, 0.4, 55); },
  drop:   () => tone(880, 'triangle', 0.003, 0.09, 0.25, 1320),
};

// 동일 kind 연타 방지용 스로틀 (ms). 전투 시 노드 플러딩 방지.
const THROTTLE_MS: Record<SfxKind, number> = {
  attack: 70,
  hit: 55,
  crit: 80,
  levelup: 300,
  pickup: 70,
  death: 500,
  kill: 90,
  drop: 100,
};
const lastPlayedAt: Partial<Record<SfxKind, number>> = {};

export function playSfx(kind: SfxKind) {
  const now = performance.now();
  const gap = THROTTLE_MS[kind];
  if ((lastPlayedAt[kind] ?? 0) + gap > now) return;
  lastPlayedAt[kind] = now;
  try { PLAYERS[kind]?.(); } catch { /* noop */ }
}

export function primeAudio() {
  ensureCtx();
  if (ctx && ctx.state === 'suspended') ctx.resume().catch(() => { /* noop */ });
}
