import { create } from 'zustand';
import type { InventoryItem, Equipment } from '../types';

/**
 * 인벤토리(아이템 목록)와 장비(5슬롯)을 함께 보관하는 store.
 * 둘은 장착/해제 시 함께 갱신되므로 같은 store에 둔다.
 */
interface InventoryStore {
  inventory: InventoryItem[];
  equipment: Equipment;
}

export const EMPTY_EQUIPMENT: Equipment = {
  weapon: null,
  armor: null,
  helmet: null,
  boots: null,
  accessory: null,
};

export const useInventoryStore = create<InventoryStore>(() => ({
  inventory: [],
  equipment: EMPTY_EQUIPMENT,
}));

type SetInventoryArg = InventoryItem[] | ((prev: InventoryItem[]) => InventoryItem[]);
type SetEquipmentArg = Equipment | ((prev: Equipment) => Equipment);

export const setInventory = (arg: SetInventoryArg): void => {
  useInventoryStore.setState((state) => ({
    inventory: typeof arg === 'function' ? arg(state.inventory) : arg,
  }));
};

export const setEquipment = (arg: SetEquipmentArg): void => {
  useInventoryStore.setState((state) => ({
    equipment: typeof arg === 'function' ? arg(state.equipment) : arg,
  }));
};

export const useInventory = () => useInventoryStore((s) => s.inventory);
export const useEquipment = () => useInventoryStore((s) => s.equipment);
