import { useCallback, useRef } from 'react';
import type { Mercenary, MercenaryType, AchievementTrigger } from '../types';
import { MERCENARY_TEMPLATES, generateMercenaryName } from '../constants/mercenaries';
import { usePlayerStore, setPlayer } from '../stores/usePlayerStore';
import { useMercenaries, setMercenaries } from '../stores/useMercenaryStore';
import { useCurrentRegion } from '../stores/useWorldStore';

/**
 * 용병 도메인 훅: 고용/해고 + 슬레이트 노출.
 *
 * 외부 의존성(플로팅 텍스트, 업적 등)은 hooks 옵션으로 주입한다.
 * hooks는 ref로 캡처되므로 매 렌더마다 새 객체로 와도 안전하다.
 */
export interface MercenarySystemHooks {
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
  unlockAchievement: (id: AchievementTrigger) => void;
}

export function useMercenarySystem(hooks: MercenarySystemHooks) {
  const mercenaries = useMercenaries();
  const currentRegion = useCurrentRegion();
  const hooksRef = useRef(hooks);
  hooksRef.current = hooks;

  const hireMercenary = useCallback(
    (type: MercenaryType): boolean => {
      const player = usePlayerStore.getState().player;
      const template = MERCENARY_TEMPLATES[type];
      if (player.gold < template.hireCost) return false;

      const merc: Mercenary = {
        uid: `merc_${Date.now()}`,
        name: generateMercenaryName(type, currentRegion),
        type,
        level: player.level,
        attack: template.baseAttack + Math.floor(player.level * 2),
        defense: template.baseDefense + Math.floor(player.level * 1.5),
        magic: template.baseMagic + Math.floor(player.level * 1),
        hireCost: template.hireCost,
        foodPerTravel: template.foodPerTravel,
      };

      setPlayer((p) => ({ ...p, gold: p.gold - template.hireCost }));
      setMercenaries((prev) => [...prev, merc]);
      hooksRef.current.addFloatingText(player.x, player.y, `${merc.name} 고용!`, '#ffd700');
      hooksRef.current.unlockAchievement('hire_mercenary');
      return true;
    },
    [currentRegion],
  );

  const fireMercenary = useCallback((uid: string) => {
    setMercenaries((prev) => prev.filter((m) => m.uid !== uid));
  }, []);

  return { mercenaries, hireMercenary, fireMercenary };
}
