import { useCallback, useEffect, useRef, useState } from 'react';
import type { SpawnedMonster } from '../types';
import { SKILLS } from '../constants/skills';
import { GAME_STATES } from '../constants/config';
import { getDistance, getAngle } from '../utils/math';
import { calculateTypeDamage } from '../utils/combat';
import { getSkillLevel, getMasteryDamageMult } from '../utils/skillMastery';
import { getDamageMult, getCooldownMult, getRangeMult } from '../utils/skillTree';
import { playSfx } from '../utils/audio';
import { usePlayerStore, setPlayer } from '../stores/usePlayerStore';
import { useMonsters, setProjectiles } from '../stores/useCombatStore';
import { useGameState } from '../stores/useWorldStore';

/**
 * 전투 도메인 훅:
 * - selectedSkill / skillCooldowns 상태 보관
 * - castSkillOnMonster: 스킬 시전 (사거리/쿨다운/마나 체크, 마스터리 적용,
 *   self는 즉시 힐, 그 외는 투사체 생성)
 * - 타겟 락온: lockedTargetUid + cycleTarget(Tab) + attackLockedTarget(Space)
 * - 던전/보스 진입 시 락 초기화, 몬스터 사라지면 락 해제 (effects)
 */
export interface CombatHandlersHooks {
  addFloatingText: (x: number, y: number, text: string, color: string, scale?: number) => void;
}

export function useCombatHandlers(hooks: CombatHandlersHooks) {
  const [selectedSkill, setSelectedSkill] = useState('cutlass');
  const [skillCooldowns, setSkillCooldowns] = useState<Record<string, number>>({});
  const [lockedTargetUid, setLockedTargetUid] = useState<string | null>(null);

  const monsters = useMonsters();
  const gameState = useGameState();

  const hooksRef = useRef(hooks);
  hooksRef.current = hooks;

  const castSkillOnMonster = useCallback(
    (monster: SpawnedMonster): boolean => {
      const skill = SKILLS[selectedSkill];
      if (!skill) return false;

      const player = usePlayerStore.getState().player;
      // Skill-tree multipliers (1.0 base; node points scale them)
      const treeDamageMult = getDamageMult(player.skillTreeAllocations, selectedSkill);
      const treeCooldownMult = getCooldownMult(player.skillTreeAllocations, selectedSkill);
      const treeRangeMult = getRangeMult(player.skillTreeAllocations, selectedSkill);
      const effectiveRange = (skill.range || 0) * treeRangeMult;

      const dist = getDistance(player.x, player.y, monster.x, monster.y);
      if (dist > effectiveRange + monster.size) {
        hooksRef.current.addFloatingText(player.x, player.y - 30, '너무 멀다!', '#ff9800');
        return true;
      }

      const now = Date.now();
      if (skillCooldowns[selectedSkill] && now < skillCooldowns[selectedSkill]) return true;
      if (player.mp < skill.manaCost) {
        hooksRef.current.addFloatingText(player.x, player.y - 30, '마나 부족!', '#3498db');
        return true;
      }

      const priorCasts = player.skillMastery[selectedSkill] || 0;
      const priorLevel = getSkillLevel(priorCasts);
      const nextLevel = getSkillLevel(priorCasts + 1);
      const masteryMult = getMasteryDamageMult(priorLevel);

      // Single setPlayer pass: mana cost + mastery bump (+ optional heal)
      const isSelf = skill.type === 'self';
      const healAmt = isSelf
        ? Math.floor(((skill.heal || 0) + Math.floor(player.magic * 0.3)) * masteryMult)
        : 0;

      setPlayer((prev) => {
        const nextMp = prev.mp - skill.manaCost;
        const nextSkillMastery = {
          ...prev.skillMastery,
          [selectedSkill]: (prev.skillMastery[selectedSkill] || 0) + 1,
        };
        if (isSelf) {
          return {
            ...prev,
            mp: nextMp,
            skillMastery: nextSkillMastery,
            hp: Math.min(prev.maxHp, prev.hp + healAmt),
          };
        }
        return { ...prev, mp: nextMp, skillMastery: nextSkillMastery };
      });
      setSkillCooldowns((prev) => ({ ...prev, [selectedSkill]: now + skill.cooldown * treeCooldownMult }));

      if (nextLevel > priorLevel) {
        hooksRef.current.addFloatingText(
          player.x,
          player.y - 70,
          `${skill.icon} 숙련도 Lv.${nextLevel}!`,
          '#ffd700',
          1.3,
        );
        playSfx('levelup');
      }

      if (isSelf) {
        hooksRef.current.addFloatingText(player.x, player.y, `+${healAmt}`, '#2ecc71');
        playSfx('pickup');
      } else {
        const angle = getAngle(player.x, player.y, monster.x, monster.y);
        let baseDamage = (skill.damage || 0) + (skill.type === 'melee' ? player.attack : player.magic);
        baseDamage = calculateTypeDamage(skill.element, monster.monsterType, baseDamage);
        baseDamage = Math.floor(baseDamage * masteryMult * treeDamageMult);

        setProjectiles((prev) => [
          ...prev,
          {
            id: Date.now(),
            x: player.x,
            y: player.y,
            vx: Math.cos(angle) * 10,
            vy: Math.sin(angle) * 10,
            damage: baseDamage,
            range: effectiveRange,
            traveled: 0,
            type: selectedSkill,
            element: skill.element,
            applyStatus: skill.applyStatus,
          },
        ]);
        playSfx('attack');
      }
      return true;
    },
    [selectedSkill, skillCooldowns],
  );

  // 락된 타겟 자동 정리
  useEffect(() => {
    if (lockedTargetUid && !monsters.some((m) => m.uid === lockedTargetUid)) {
      setLockedTargetUid(null);
    }
  }, [monsters, lockedTargetUid]);

  // 던전/보스 외 상태로 전환 시 락 해제
  useEffect(() => {
    if (gameState !== GAME_STATES.DUNGEON && gameState !== GAME_STATES.BOSS) {
      setLockedTargetUid(null);
    }
  }, [gameState]);

  const cycleTarget = useCallback(() => {
    if (monsters.length === 0) {
      setLockedTargetUid(null);
      return;
    }
    const player = usePlayerStore.getState().player;
    const sorted = [...monsters].sort(
      (a, b) =>
        getDistance(player.x, player.y, a.x, a.y) - getDistance(player.x, player.y, b.x, b.y),
    );
    if (!lockedTargetUid) {
      setLockedTargetUid(sorted[0].uid);
      return;
    }
    const idx = sorted.findIndex((m) => m.uid === lockedTargetUid);
    const next = sorted[(idx + 1) % sorted.length];
    setLockedTargetUid(next.uid);
  }, [monsters, lockedTargetUid]);

  const attackLockedTarget = useCallback(() => {
    if (!lockedTargetUid) {
      if (monsters.length === 0) return;
      const player = usePlayerStore.getState().player;
      const closest = monsters.reduce((a, b) =>
        getDistance(player.x, player.y, a.x, a.y) <= getDistance(player.x, player.y, b.x, b.y)
          ? a
          : b,
      );
      setLockedTargetUid(closest.uid);
      castSkillOnMonster(closest);
      return;
    }
    const m = monsters.find((mm) => mm.uid === lockedTargetUid);
    if (m) castSkillOnMonster(m);
  }, [lockedTargetUid, monsters, castSkillOnMonster]);

  return {
    selectedSkill,
    setSelectedSkill,
    skillCooldowns,
    lockedTargetUid,
    setLockedTargetUid,
    castSkillOnMonster,
    cycleTarget,
    attackLockedTarget,
  };
}
