import { useState } from 'react';
import { ITEMS, SHOP_ITEMS, FOOD_ITEMS, getTradeGoodsForRegion } from '../../constants/items';
import { getNPCsForRegion } from '../../constants/regions';
import { calculateTradePrice } from '../../utils/trade';
import { getRarityColor } from '../../utils/combat';
import type { Player, Item, InventoryItem } from '../../types';
import { Panel } from '../ui';

type ShopTab = 'general' | 'trade' | 'food';

interface ShopModalProps {
  player: Player;
  currentRegion: string;
  inventory: InventoryItem[];
  onBuyItem: (item: Item) => void;
  onBuyFood: (item: Item) => void;
  onSellItem: (uid: string) => void;
  onClose: () => void;
}

export default function ShopModal({ player, currentRegion, inventory, onBuyItem, onBuyFood, onSellItem, onClose }: ShopModalProps) {
  const [tab, setTab] = useState<ShopTab>('general');
  const localTradeGoods = getTradeGoodsForRegion(currentRegion);
  const tradeInventory = inventory.filter(i => i.type === 'trade_good');

  const tabs: { key: ShopTab; label: string }[] = [
    { key: 'general', label: '일반 상점' },
    { key: 'trade', label: '교역품' },
    { key: 'food', label: '식량' },
  ];

  const npcName = getNPCsForRegion(currentRegion)[0]?.name || '상인';

  const headerExtra = (
    <>
      <span className="text-age-gold text-sm">{'💰'} {player.gold}</span>
      <span className="text-age-leaf text-sm">{'🍞'} {Math.floor(player.food)}</span>
    </>
  );

  return (
    <Panel
      title={npcName}
      icon={'🧔'}
      onClose={onClose}
      headerExtra={headerExtra}
      maxWidth="min-w-[460px]"
      className="max-h-[80vh] overflow-y-auto"
    >
      <div className="flex gap-1 mb-3">
        {tabs.map(t => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={`px-3 py-1.5 text-sm rounded transition-colors ${
              tab === t.key
                ? 'bg-age-gold/25 text-age-gold border border-age-gold/50'
                : 'bg-age-navy/70 text-age-paper/60 border border-age-gold/15 hover:text-age-paper hover:border-age-gold/40'
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'general' && (
        <>
          <div className="grid grid-cols-4 gap-2 mb-4">
            {SHOP_ITEMS.map(id => {
              const item = ITEMS[id];
              const affordable = player.gold >= item.price;
              return (
                <button
                  key={id}
                  onClick={() => onBuyItem(item)}
                  className={`p-2 rounded border text-center transition-all ${
                    affordable
                      ? 'border-age-gold/25 bg-age-navy/70 hover:border-age-gold/70 hover:shadow-gold'
                      : 'border-age-blood/40 bg-age-navy/70 opacity-50'
                  }`}
                >
                  <div className="text-2xl mb-1">{item.icon}</div>
                  <div className="text-xs text-age-paper truncate">{item.name}</div>
                  <div className="text-xs text-age-gold">{item.price}G</div>
                  <div className="text-[10px] text-age-paper/50">{item.weight}kg</div>
                </button>
              );
            })}
          </div>

          {inventory.length > 0 && (
            <div>
              <h3 className="text-age-amber text-sm mb-2">판매</h3>
              <div className="grid grid-cols-5 gap-1">
                {inventory.filter(i => i.type !== 'trade_good').map(item => (
                  <button
                    key={item.uid}
                    onClick={() => onSellItem(item.uid)}
                    className="p-1 rounded border-2 bg-age-navy/70 hover:bg-age-navy/40 text-center transition-all"
                    style={{ borderColor: getRarityColor(item.rarity) }}
                    title={`${item.name} - ${Math.floor(item.price * 0.5)}G`}
                  >
                    <span className="text-lg">{item.icon}</span>
                    <div className="text-[9px] text-age-gold">{Math.floor(item.price * 0.5)}G</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      {tab === 'trade' && (
        <>
          <h3 className="text-age-amber text-sm mb-2">이 나라의 특산물 (구매)</h3>
          <div className="grid grid-cols-2 gap-2 mb-4">
            {localTradeGoods.map(id => {
              const item = ITEMS[id];
              const buyPrice = item.tradeInfo?.basePrice || item.price;
              const affordable = player.gold >= buyPrice;
              return (
                <button
                  key={id}
                  onClick={() => onBuyItem({ ...item, price: buyPrice })}
                  className={`p-3 rounded border text-left transition-all ${
                    affordable
                      ? 'border-age-gold/25 bg-age-navy/70 hover:border-age-gold/70 hover:shadow-gold'
                      : 'border-age-blood/40 bg-age-navy/70 opacity-50'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <span className="text-2xl">{item.icon}</span>
                    <div>
                      <div className="text-sm text-age-paper">{item.name}</div>
                      <div className="text-xs text-age-gold">구매: {buyPrice}G | {item.weight}kg</div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>

          {tradeInventory.length > 0 && (
            <>
              <h3 className="text-age-amber text-sm mb-2">보유 교역품 (판매)</h3>
              <div className="space-y-2">
                {tradeInventory.map(item => {
                  const sellPrice = calculateTradePrice(item, currentRegion);
                  const buyPrice = item.tradeInfo?.basePrice || item.price;
                  const profit = sellPrice - buyPrice;
                  return (
                    <button
                      key={item.uid}
                      onClick={() => onSellItem(item.uid)}
                      className="w-full p-2 rounded border border-age-gold/25 bg-age-navy/70 hover:border-age-gold/70 hover:shadow-gold transition-all flex items-center gap-3"
                    >
                      <span className="text-2xl">{item.icon}</span>
                      <div className="flex-1 text-left">
                        <div className="text-sm text-age-paper">{item.name}</div>
                        <div className="text-xs">
                          <span className="text-age-gold">판매: {sellPrice}G</span>
                          {profit > 0 && <span className="text-age-leaf ml-2">(+{profit}G 이익)</span>}
                          {profit <= 0 && <span className="text-age-blood ml-2">({profit}G)</span>}
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </>
          )}
        </>
      )}

      {tab === 'food' && (
        <div className="grid grid-cols-2 gap-2">
          {FOOD_ITEMS.map(id => {
            const item = ITEMS[id];
            const affordable = player.gold >= item.price;
            return (
              <button
                key={id}
                onClick={() => onBuyFood(item)}
                className={`p-3 rounded border text-left transition-all ${
                  affordable
                    ? 'border-age-gold/25 bg-age-navy/70 hover:border-age-gold/70 hover:shadow-gold'
                    : 'border-age-blood/40 bg-age-navy/70 opacity-50'
                }`}
              >
                <div className="flex items-center gap-2">
                  <span className="text-2xl">{item.icon}</span>
                  <div>
                    <div className="text-sm text-age-paper">{item.name}</div>
                    <div className="text-xs text-age-gold">{item.price}G</div>
                    <div className="text-xs text-age-leaf">+{item.foodValue} 식량</div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </Panel>
  );
}
