/**
 * 게임 캔버스(R3F) 스크린샷 캡처 → 240x135 PNG dataURL.
 * 세이브 슬롯 썸네일 용도.
 */

const THUMB_W = 240;
const THUMB_H = 135;

/** 첫 번째 <canvas> (R3F SceneRoot) 를 240x135 PNG dataURL 로 변환 */
export function captureGameThumbnail(): string | undefined {
  try {
    const canvas = document.querySelector('canvas') as HTMLCanvasElement | null;
    if (!canvas || canvas.width === 0 || canvas.height === 0) return undefined;

    const out = document.createElement('canvas');
    out.width = THUMB_W;
    out.height = THUMB_H;
    const ctx = out.getContext('2d');
    if (!ctx) return undefined;

    ctx.fillStyle = '#0d0608';
    ctx.fillRect(0, 0, THUMB_W, THUMB_H);

    // 원본 비율 유지 + 중앙 크롭
    const srcRatio = canvas.width / canvas.height;
    const dstRatio = THUMB_W / THUMB_H;
    let sx = 0, sy = 0, sw = canvas.width, sh = canvas.height;
    if (srcRatio > dstRatio) {
      sw = canvas.height * dstRatio;
      sx = (canvas.width - sw) / 2;
    } else {
      sh = canvas.width / dstRatio;
      sy = (canvas.height - sh) / 2;
    }
    ctx.drawImage(canvas, sx, sy, sw, sh, 0, 0, THUMB_W, THUMB_H);
    return out.toDataURL('image/png');
  } catch {
    return undefined;
  }
}
